RAW_SCRIPTS = {
    'hospital': 'import json\nimport math\nimport re\nfrom collections import Counter\nfrom itertools import combinations\nfrom typing import Dict, List, Tuple, Any, Optional\n\nimport pandas as pd\n\n\n# ============================================================\n# 1. 用户配置区\n# ============================================================\n\nINPUT_CSV = "/mnt/mydata/dq/projects/Splittree/hospital/hospital_dirty_no_address23.csv"\nOUTPUT_JSON = "rule_pool_high_recall_v2.json"\n\n# 缺失值标记\nMISSING_TOKENS = {"", "empty", "null", "none", "nan", "na", "n/a", "missing", "unk"}\n\n# 列类型判定\nNUMERIC_RATIO_THRESHOLD = 0.90\nENUM_UNIQUE_THRESHOLD = 30\nENUM_RATIO_THRESHOLD = 0.05\n\n# semantic type 判定\nID_LIKE_UNIQUE_RATIO_THRESHOLD = 0.98\nCODE_LIKE_AVG_LEN_THRESHOLD = 20\nCODE_LIKE_DOMINANT_PATTERN_THRESHOLD = 0.70\n\n# 主模式规则阈值\nDOMINANT_PATTERN_THRESHOLD = 0.70\n\n# FD 挖掘参数（强规则）\nMAX_LHS_SIZE = 2\nFD_CONFIDENCE_THRESHOLD = 0.98\nMIN_SUPPORT_ROWS = 5\n\n# 软 FD 参数（高召回候选规则）\nSOFT_FD_CONFIDENCE_THRESHOLD = 0.80\nSOFT_FD_MIN_GROUP_SIZE = 3\n\n# 过滤超高基数字段作为 FD 左部候选\nHIGH_CARDINALITY_RATIO_FOR_LHS = 0.95\n\n# 是否保留 index 型列参与规则发现\nALLOW_INDEX_COLUMN = False\n\n# 默认不对 id_like 生成太多 schema 规则\nSKIP_SCHEMA_FOR_ID_LIKE = True\nSKIP_NUMERIC_RANGE_FOR_CODE_LIKE = True\n\n# 高风险列：对缺失值更激进地纳入候选\nHIGH_RISK_MISSING_COLUMNS = {"Score", "Sample"}\n\n# 列专属格式规则\nENABLE_SPECIAL_COLUMN_RULES = True\n\n# typo-aware 主值候选规则\nENABLE_DOMINANT_TYPO_RULE = True\nDOMINANT_TYPO_MAX_EDIT_DISTANCE = 2\nDOMINANT_TYPO_MIN_COUNT = 20\nDOMINANT_TYPO_MIN_RATIO = 0.50\n\n# 稀有值弱候选\nENABLE_RARE_VALUE_RULE = True\nRARE_VALUE_MAX_FREQ = 2\n\n# 稀有 pattern 弱候选\nENABLE_RARE_PATTERN_RULE = True\nRARE_PATTERN_MAX_RATIO = 0.02\n\n\n# ============================================================\n# 2. 基础工具函数\n# ============================================================\n\ndef normalize_value(x):\n    """归一化单元格值。"""\n    if pd.isna(x):\n        return None\n    s = str(x).strip()\n    if s.lower() in MISSING_TOKENS:\n        return None\n    return s.lower()\n\n\ndef normalize_series(s: pd.Series) -> pd.Series:\n    return s.map(normalize_value)\n\n\ndef maybe_drop_unnamed_columns(df: pd.DataFrame) -> pd.DataFrame:\n    keep_cols = [c for c in df.columns if not str(c).lower().startswith("unnamed:")]\n    return df[keep_cols].copy()\n\n\ndef is_index_like_column(series: pd.Series) -> bool:\n    s = series.dropna()\n    if len(s) == 0:\n        return False\n\n    numeric = pd.to_numeric(s, errors="coerce")\n    if numeric.notna().mean() < 0.95:\n        return False\n\n    unique_ratio = s.nunique() / len(s)\n    return unique_ratio > 0.98\n\n\ndef detect_basic_pattern(value: str) -> str:\n    """\n    抽取粗粒度模式。\n    例:\n      2053258100 -> D10\n      scip-card-2 -> L4S1L4S1D1\n      al_ami-1 -> L2S1L3S1D1\n    """\n    if value is None:\n        return "NULL"\n\n    parts = []\n    prev_type = None\n    cnt = 0\n\n    for ch in value:\n        if ch.isdigit():\n            cur = "D"\n        elif ch.isalpha():\n            cur = "L"\n        elif ch in {" ", "-", "_", "/", ".", ",", "(", ")", "%", ":", ";", "&", "\'"}:\n            cur = "S"\n        else:\n            cur = "X"\n\n        if cur == prev_type:\n            cnt += 1\n        else:\n            if prev_type is not None:\n                parts.append(f"{prev_type}{cnt}")\n            prev_type = cur\n            cnt = 1\n\n    if prev_type is not None:\n        parts.append(f"{prev_type}{cnt}")\n\n    return "".join(parts)\n\n\ndef try_parse_numeric(series: pd.Series):\n    cleaned = (\n        series.dropna()\n        .astype(str)\n        .str.replace(",", "", regex=False)\n        .str.replace("%", "", regex=False)\n    )\n    numeric = pd.to_numeric(cleaned, errors="coerce")\n    success_ratio = numeric.notna().mean() if len(cleaned) > 0 else 0.0\n    return numeric, success_ratio\n\n\ndef shannon_entropy(series: pd.Series) -> float:\n    vals = series.dropna().tolist()\n    if not vals:\n        return 0.0\n    cnt = Counter(vals)\n    total = len(vals)\n    ent = 0.0\n    for c in cnt.values():\n        p = c / total\n        ent -= p * math.log2(p)\n    return ent\n\n\ndef value_frequency_dict(series: pd.Series, topk=20):\n    cnt = Counter(series.dropna().tolist())\n    total = sum(cnt.values()) if cnt else 0\n    out = []\n    for k, v in cnt.most_common(topk):\n        out.append({\n            "value": k,\n            "count": v,\n            "ratio": round(v / total, 6) if total > 0 else 0.0\n        })\n    return out\n\n\ndef levenshtein_distance(a: str, b: str) -> int:\n    """简单编辑距离。"""\n    if a is None or b is None:\n        return 999999\n    if a == b:\n        return 0\n    if len(a) < len(b):\n        a, b = b, a\n\n    prev = list(range(len(b) + 1))\n    for i, ca in enumerate(a, start=1):\n        cur = [i]\n        for j, cb in enumerate(b, start=1):\n            ins = cur[j - 1] + 1\n            dele = prev[j] + 1\n            rep = prev[j - 1] + (0 if ca == cb else 1)\n            cur.append(min(ins, dele, rep))\n        prev = cur\n    return prev[-1]\n\n\ndef looks_like_score_format(v: Optional[str]) -> bool:\n    """Score 列常见格式：98%、100%、0% 等。"""\n    if v is None:\n        return False\n    return re.fullmatch(r"\\d{1,3}%", v) is not None\n\n\ndef split_sample_value(v: Optional[str]) -> Tuple[Optional[str], Optional[str]]:\n    """\n    Sample 列预期类似: \'149 patients\'\n    返回 (number_part, suffix_part)\n    """\n    if v is None:\n        return None, None\n    m = re.fullmatch(r"(\\d+)\\s+(.+)", v.strip())\n    if not m:\n        return None, None\n    return m.group(1), m.group(2).strip()\n\n\ndef looks_like_sample_format(v: Optional[str]) -> bool:\n    if v is None:\n        return False\n    return re.fullmatch(r"\\d+\\s+patients", v) is not None\n\n\ndef is_typo_like_patients(v: Optional[str]) -> bool:\n    """\n    抓 \'619 paxienxs\' / \'0 patixnts\' / \'82 patientx\' 这类。\n    """\n    if v is None:\n        return False\n    num, suffix = split_sample_value(v)\n    if num is None or suffix is None:\n        return False\n    if suffix == "patients":\n        return False\n    return levenshtein_distance(suffix, "patients") <= 2\n\n\n# ============================================================\n# 3. semantic type 判定\n# ============================================================\n\ndef is_id_like_column(non_null: pd.Series, unique_ratio: float, numeric_ratio: float, avg_len: float) -> bool:\n    if len(non_null) == 0:\n        return False\n\n    if unique_ratio >= ID_LIKE_UNIQUE_RATIO_THRESHOLD and avg_len <= CODE_LIKE_AVG_LEN_THRESHOLD:\n        return True\n\n    if unique_ratio >= ID_LIKE_UNIQUE_RATIO_THRESHOLD and numeric_ratio >= NUMERIC_RATIO_THRESHOLD:\n        return True\n\n    return False\n\n\ndef is_code_like_column(\n    non_null: pd.Series,\n    unique_ratio: float,\n    numeric_ratio: float,\n    avg_len: float,\n    top_patterns: List[Dict[str, Any]]\n) -> bool:\n    if len(non_null) == 0:\n        return False\n\n    dominant_ratio = top_patterns[0]["ratio"] if top_patterns else 0.0\n\n    if avg_len <= CODE_LIKE_AVG_LEN_THRESHOLD and dominant_ratio >= CODE_LIKE_DOMINANT_PATTERN_THRESHOLD:\n        if unique_ratio > ENUM_RATIO_THRESHOLD:\n            return True\n\n    if numeric_ratio >= 0.95 and avg_len <= 15 and unique_ratio < ID_LIKE_UNIQUE_RATIO_THRESHOLD:\n        return True\n\n    return False\n\n\n# ============================================================\n# 4. 规则质量评估\n# ============================================================\n\ndef calc_fd_confidence_and_support(df: pd.DataFrame, lhs_cols: List[str], rhs_col: str):\n    sub = df[lhs_cols + [rhs_col]].dropna()\n    support = len(sub)\n\n    if support < MIN_SUPPORT_ROWS:\n        return 0.0, support\n\n    grouped = sub.groupby(lhs_cols, dropna=True)[rhs_col]\n    majority_sum = 0\n\n    for _, grp in grouped:\n        cnt = Counter(grp.tolist())\n        majority_sum += cnt.most_common(1)[0][1]\n\n    confidence = majority_sum / support if support > 0 else 0.0\n    return round(confidence, 6), int(support)\n\n\ndef calc_soft_fd_confidence_and_support(df: pd.DataFrame, lhs_cols: List[str], rhs_col: str):\n    sub = df[lhs_cols + [rhs_col]].dropna()\n    support = len(sub)\n\n    if support < SOFT_FD_MIN_GROUP_SIZE:\n        return 0.0, support\n\n    grouped = sub.groupby(lhs_cols, dropna=True)[rhs_col]\n    majority_sum = 0\n\n    for _, grp in grouped:\n        if len(grp) < SOFT_FD_MIN_GROUP_SIZE:\n            continue\n        cnt = Counter(grp.tolist())\n        majority_sum += cnt.most_common(1)[0][1]\n\n    confidence = majority_sum / support if support > 0 else 0.0\n    return round(confidence, 6), int(support)\n\n\ndef calc_not_null_confidence_and_support(series: pd.Series):\n    total = len(series)\n    if total == 0:\n        return 0.0, 0\n    non_null = series.notna().sum()\n    return round(non_null / total, 6), int(total)\n\n\ndef calc_enum_confidence_and_support(series: pd.Series, allowed_values: set):\n    non_null = series.dropna()\n    support = len(non_null)\n    if support == 0:\n        return 0.0, 0\n    ok = non_null.isin(allowed_values).sum()\n    return round(ok / support, 6), int(support)\n\n\ndef calc_pattern_confidence_and_support(series: pd.Series, dominant_pattern: str):\n    non_null = series.dropna()\n    support = len(non_null)\n    if support == 0:\n        return 0.0, 0\n    pats = non_null.map(detect_basic_pattern)\n    ok = (pats == dominant_pattern).sum()\n    return round(ok / support, 6), int(support)\n\n\ndef calc_numeric_range_confidence_and_support(series: pd.Series, min_val: float, max_val: float):\n    numeric, _ = try_parse_numeric(series)\n    nums = numeric.dropna()\n    support = len(nums)\n    if support == 0:\n        return 0.0, 0\n    ok = ((nums >= min_val) & (nums <= max_val)).sum()\n    return round(ok / support, 6), int(support)\n\n\n# ============================================================\n# 5. 列分析\n# ============================================================\n\ndef analyze_columns(df: pd.DataFrame) -> Dict[str, Dict[str, Any]]:\n    profiles = {}\n    n = len(df)\n\n    for col in df.columns:\n        s = normalize_series(df[col])\n        non_null = s.dropna()\n\n        missing_rate = 1.0 - (len(non_null) / n if n > 0 else 0.0)\n        unique_count = non_null.nunique()\n        unique_ratio = unique_count / len(non_null) if len(non_null) > 0 else 0.0\n\n        numeric_vals, numeric_ratio = try_parse_numeric(non_null)\n\n        patterns = non_null.map(detect_basic_pattern)\n        pattern_counter = Counter(patterns.tolist())\n        total_patterns = sum(pattern_counter.values())\n\n        top_patterns = [\n            {\n                "pattern": p,\n                "count": c,\n                "ratio": round(c / total_patterns, 6)\n            }\n            for p, c in pattern_counter.most_common(10)\n        ]\n\n        lengths = non_null.map(lambda x: len(str(x)))\n        avg_len = float(lengths.mean()) if len(lengths) > 0 else 0.0\n\n        profile = {\n            "column": col,\n            "missing_rate": round(missing_rate, 6),\n            "non_null_count": int(len(non_null)),\n            "unique_count": int(unique_count),\n            "unique_ratio": round(unique_ratio, 6),\n            "numeric_parse_ratio": round(float(numeric_ratio), 6),\n            "entropy": round(shannon_entropy(non_null), 6),\n            "detected_type": None,\n            "semantic_type": None,\n            "index_like": is_index_like_column(non_null),\n            "avg_length": round(avg_len, 6),\n            "top_values": value_frequency_dict(non_null, topk=20),\n            "top_patterns": top_patterns,\n            "value_counter": Counter(non_null.tolist())\n        }\n\n        if numeric_ratio >= NUMERIC_RATIO_THRESHOLD:\n            profile["detected_type"] = "numeric"\n        else:\n            if unique_count <= ENUM_UNIQUE_THRESHOLD or unique_ratio <= ENUM_RATIO_THRESHOLD:\n                profile["detected_type"] = "categorical"\n            else:\n                profile["detected_type"] = "text"\n\n        if profile["index_like"]:\n            profile["semantic_type"] = "id_like"\n        elif is_id_like_column(non_null, unique_ratio, numeric_ratio, avg_len):\n            profile["semantic_type"] = "id_like"\n        elif is_code_like_column(non_null, unique_ratio, numeric_ratio, avg_len, top_patterns):\n            profile["semantic_type"] = "code_like"\n        elif profile["detected_type"] == "numeric":\n            profile["semantic_type"] = "numeric"\n        elif profile["detected_type"] == "categorical":\n            profile["semantic_type"] = "categorical"\n        else:\n            profile["semantic_type"] = "text"\n\n        if profile["detected_type"] == "numeric":\n            nums = numeric_vals.dropna()\n            if len(nums) > 0:\n                q1 = float(nums.quantile(0.25))\n                q3 = float(nums.quantile(0.75))\n                iqr = q3 - q1\n                profile["numeric_stats"] = {\n                    "min": float(nums.min()),\n                    "max": float(nums.max()),\n                    "mean": float(nums.mean()),\n                    "std": float(nums.std(ddof=0)) if len(nums) > 1 else 0.0,\n                    "q1": q1,\n                    "median": float(nums.quantile(0.5)),\n                    "q3": q3,\n                    "iqr": iqr,\n                    "iqr_lower": q1 - 1.5 * iqr,\n                    "iqr_upper": q3 + 1.5 * iqr,\n                }\n\n        profiles[col] = profile\n\n    return profiles\n\n\n# ============================================================\n# 6. 构建 Schema / Domain / Pattern 规则\n# ============================================================\n\ndef build_schema_rules(df: pd.DataFrame, profiles: Dict[str, Dict[str, Any]]) -> List[Dict[str, Any]]:\n    rules = []\n    rule_id = 1\n\n    for col, info in profiles.items():\n        series = normalize_series(df[col])\n\n        if (not ALLOW_INDEX_COLUMN) and info.get("index_like", False):\n            continue\n\n        if SKIP_SCHEMA_FOR_ID_LIKE and info.get("semantic_type") == "id_like":\n            continue\n\n        # 6.1 非空规则：对高风险列放宽阈值\n        not_null_threshold = 0.30 if col in HIGH_RISK_MISSING_COLUMNS else 0.01\n        if info["missing_rate"] <= not_null_threshold:\n            confidence, support = calc_not_null_confidence_and_support(series)\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "not_null",\n                "column": col,\n                "description": f"{col} should not be null",\n                "confidence": confidence,\n                "support": support,\n                "usage_role": "strong_rule" if col not in HIGH_RISK_MISSING_COLUMNS else "candidate_generation_rule"\n            })\n            rule_id += 1\n\n        # 6.2 数值范围规则\n        if info["detected_type"] == "numeric" and "numeric_stats" in info:\n            if not (SKIP_NUMERIC_RANGE_FOR_CODE_LIKE and info.get("semantic_type") in {"code_like", "id_like"}):\n                stats = info["numeric_stats"]\n                confidence, support = calc_numeric_range_confidence_and_support(\n                    series, stats["min"], stats["max"]\n                )\n                rules.append({\n                    "rule_id": f"SCHEMA_{rule_id}",\n                    "rule_type": "numeric_range",\n                    "column": col,\n                    "description": f"{col} should be within observed numeric range",\n                    "range": {\n                        "min": stats["min"],\n                        "max": stats["max"]\n                    },\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "strong_rule"\n                })\n                rule_id += 1\n\n        # 6.3 枚举域规则\n        if info["semantic_type"] == "categorical":\n            allowed_values = [x["value"] for x in info["top_values"]]\n            confidence, support = calc_enum_confidence_and_support(series, set(allowed_values))\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "enumeration_domain",\n                "column": col,\n                "description": f"{col} should belong to a limited domain",\n                "allowed_values": allowed_values,\n                "confidence": confidence,\n                "support": support,\n                "usage_role": "strong_rule"\n            })\n            rule_id += 1\n\n        # 6.4 主模式规则\n        if len(info["top_patterns"]) > 0:\n            main_pattern = info["top_patterns"][0]\n            if main_pattern["ratio"] >= DOMINANT_PATTERN_THRESHOLD:\n                confidence, support = calc_pattern_confidence_and_support(\n                    series, main_pattern["pattern"]\n                )\n                rules.append({\n                    "rule_id": f"SCHEMA_{rule_id}",\n                    "rule_type": "pattern",\n                    "column": col,\n                    "description": f"{col} should mostly follow the dominant pattern",\n                    "pattern": main_pattern["pattern"],\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "strong_rule"\n                })\n                rule_id += 1\n\n        # 6.5 列专属规则：Score\n        if ENABLE_SPECIAL_COLUMN_RULES and col == "Score":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "score_format",\n                "column": col,\n                "description": "Score should usually look like a percentage, e.g. 98%",\n                "regex": r"^\\d{1,3}%$",\n                "confidence": 0.9,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule"\n            })\n            rule_id += 1\n\n        # 6.6 列专属规则：Sample\n        if ENABLE_SPECIAL_COLUMN_RULES and col == "Sample":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "sample_format",\n                "column": col,\n                "description": "Sample should usually look like \'<number> patients\'",\n                "regex": r"^\\d+\\s+patients$",\n                "confidence": 0.9,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule"\n            })\n            rule_id += 1\n\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "sample_patients_suffix",\n                "column": col,\n                "description": "Sample suffix should usually be canonical token \'patients\'",\n                "canonical_suffix": "patients",\n                "max_edit_distance": 2,\n                "confidence": 0.9,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule"\n            })\n            rule_id += 1\n\n    return rules\n\n\n# ============================================================\n# 7. 自动挖掘 FD 规则\n# ============================================================\n\ndef select_fd_lhs_candidates(profiles: Dict[str, Dict[str, Any]]) -> List[str]:\n    candidates = []\n\n    for col, info in profiles.items():\n        if (not ALLOW_INDEX_COLUMN) and info.get("index_like", False):\n            continue\n\n        if info["unique_ratio"] >= HIGH_CARDINALITY_RATIO_FOR_LHS:\n            continue\n\n        candidates.append(col)\n\n    return candidates\n\n\ndef build_fd_rules(df: pd.DataFrame, profiles: Dict[str, Dict[str, Any]]) -> List[Dict[str, Any]]:\n    rules = []\n    rule_id = 1\n\n    cols = list(df.columns)\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in cols})\n\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n\n    rhs_candidates = []\n    for c in cols:\n        if (not ALLOW_INDEX_COLUMN) and profiles[c].get("index_like", False):\n            continue\n        rhs_candidates.append(c)\n\n    lhs_sets = []\n    for k in range(1, MAX_LHS_SIZE + 1):\n        lhs_sets.extend(list(combinations(lhs_candidates, k)))\n\n    for lhs in lhs_sets:\n        for rhs in rhs_candidates:\n            if rhs in lhs:\n                continue\n\n            confidence, support = calc_fd_confidence_and_support(norm_df, list(lhs), rhs)\n\n            if support < MIN_SUPPORT_ROWS:\n                continue\n\n            if confidence >= FD_CONFIDENCE_THRESHOLD:\n                rules.append({\n                    "rule_id": f"FD_{rule_id}",\n                    "rule_type": "functional_dependency",\n                    "lhs": list(lhs),\n                    "rhs": rhs,\n                    "description": f"{\', \'.join(lhs)} -> {rhs}",\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "strong_rule"\n                })\n                rule_id += 1\n\n    # 去重 + 去冗余\n    dedup = {}\n    for r in rules:\n        key = (tuple(sorted(r["lhs"])), r["rhs"])\n        dedup[key] = r\n\n    filtered = list(dedup.values())\n\n    final_rules = []\n    for r in filtered:\n        lhs_set = set(r["lhs"])\n        rhs = r["rhs"]\n        dominated = False\n\n        for r2 in filtered:\n            if r2["rhs"] != rhs:\n                continue\n            lhs2_set = set(r2["lhs"])\n            if lhs2_set < lhs_set and r2["confidence"] >= r["confidence"]:\n                dominated = True\n                break\n\n        if not dominated:\n            final_rules.append(r)\n\n    return final_rules\n\n\n# ============================================================\n# 8. 软 FD / 候选生成规则\n# ============================================================\n\ndef build_soft_fd_rules(df: pd.DataFrame, profiles: Dict[str, Dict[str, Any]]) -> List[Dict[str, Any]]:\n    rules = []\n    rule_id = 1\n\n    cols = list(df.columns)\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in cols})\n\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n\n    rhs_candidates = []\n    for c in cols:\n        if (not ALLOW_INDEX_COLUMN) and profiles[c].get("index_like", False):\n            continue\n        rhs_candidates.append(c)\n\n    lhs_sets = []\n    for k in range(1, MAX_LHS_SIZE + 1):\n        lhs_sets.extend(list(combinations(lhs_candidates, k)))\n\n    for lhs in lhs_sets:\n        for rhs in rhs_candidates:\n            if rhs in lhs:\n                continue\n\n            confidence, support = calc_soft_fd_confidence_and_support(norm_df, list(lhs), rhs)\n\n            if support < SOFT_FD_MIN_GROUP_SIZE:\n                continue\n\n            if SOFT_FD_CONFIDENCE_THRESHOLD <= confidence < FD_CONFIDENCE_THRESHOLD:\n                rules.append({\n                    "rule_id": f"CAND_SOFTFD_{rule_id}",\n                    "rule_type": "soft_functional_dependency",\n                    "lhs": list(lhs),\n                    "rhs": rhs,\n                    "description": f"soft FD: {\', \'.join(lhs)} -> {rhs}",\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "candidate_generation_rule"\n                })\n                rule_id += 1\n\n    dedup = {}\n    for r in rules:\n        key = (tuple(sorted(r["lhs"])), r["rhs"])\n        # 保留更高置信度的\n        if key not in dedup or r["confidence"] > dedup[key]["confidence"]:\n            dedup[key] = r\n\n    return list(dedup.values())\n\n\n# ============================================================\n# 9. 主值 / 上下文主值 / 稀有值 / typo 候选规则\n# ============================================================\n\ndef build_candidate_generation_rules(df: pd.DataFrame, profiles: Dict[str, Dict[str, Any]]) -> List[Dict[str, Any]]:\n    rules = []\n    rule_id = 1\n\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in df.columns})\n\n    # 9.1 global dominant value\n    for col, prof in profiles.items():\n        top_values = prof.get("top_values", [])\n        if not top_values:\n            continue\n\n        top1 = top_values[0]\n        if top1["ratio"] >= DOMINANT_TYPO_MIN_RATIO:\n            rules.append({\n                "rule_id": f"CAND_GDOM_{rule_id}",\n                "rule_type": "global_dominant_value",\n                "column": col,\n                "description": f"global dominant value for {col}",\n                "dominant_value": top1["value"],\n                "dominant_count": top1["count"],\n                "dominant_ratio": top1["ratio"],\n                "confidence": round(top1["ratio"], 6),\n                "support": prof["non_null_count"],\n                "usage_role": "candidate_generation_rule"\n            })\n            rule_id += 1\n\n    # 9.2 dominant value by context\n    context_rule_id = 1\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n\n    for rhs in df.columns:\n        if (not ALLOW_INDEX_COLUMN) and profiles[rhs].get("index_like", False):\n            continue\n\n        for lhs in lhs_candidates:\n            if lhs == rhs:\n                continue\n\n            sub = norm_df[[lhs, rhs]].dropna()\n            if len(sub) < SOFT_FD_MIN_GROUP_SIZE:\n                continue\n\n            grouped = sub.groupby(lhs)[rhs]\n            majority_map = {}\n            total_support = 0\n\n            for lhs_val, grp in grouped:\n                if len(grp) < SOFT_FD_MIN_GROUP_SIZE:\n                    continue\n                cnt = Counter(grp.tolist())\n                maj_val, maj_cnt = cnt.most_common(1)[0]\n                ratio = maj_cnt / len(grp)\n\n                if ratio >= SOFT_FD_CONFIDENCE_THRESHOLD:\n                    majority_map[lhs_val] = {\n                        "dominant_value": maj_val,\n                        "group_size": len(grp),\n                        "ratio": round(ratio, 6)\n                    }\n                    total_support += len(grp)\n\n            if majority_map:\n                rules.append({\n                    "rule_id": f"CAND_CTXDOM_{context_rule_id}",\n                    "rule_type": "dominant_value_by_context",\n                    "lhs": [lhs],\n                    "rhs": rhs,\n                    "description": f"context dominant: {lhs} -> dominant {rhs}",\n                    "mapping_size": len(majority_map),\n                    "majority_map": majority_map,\n                    "confidence": 0.85,\n                    "support": total_support,\n                    "usage_role": "candidate_generation_rule"\n                })\n                context_rule_id += 1\n\n    # 9.3 稀有值规则\n    if ENABLE_RARE_VALUE_RULE:\n        for col, prof in profiles.items():\n            if prof["semantic_type"] not in {"categorical", "text", "code_like"}:\n                continue\n\n            counter = prof["value_counter"]\n            rare_values = [v for v, c in counter.items() if c <= RARE_VALUE_MAX_FREQ]\n\n            if rare_values:\n                rules.append({\n                    "rule_id": f"CAND_RAREVAL_{rule_id}",\n                    "rule_type": "rare_value",\n                    "column": col,\n                    "description": f"rare values in {col} may be suspicious",\n                    "rare_values": rare_values[:5000],\n                    "confidence": 0.6,\n                    "support": sum(counter[v] for v in rare_values),\n                    "usage_role": "candidate_generation_rule"\n                })\n                rule_id += 1\n\n    # 9.4 稀有 pattern 规则\n    if ENABLE_RARE_PATTERN_RULE:\n        for col, prof in profiles.items():\n            top_patterns = prof.get("top_patterns", [])\n            rare_patterns = [x["pattern"] for x in top_patterns if x["ratio"] <= RARE_PATTERN_MAX_RATIO]\n\n            if rare_patterns:\n                rules.append({\n                    "rule_id": f"CAND_RAREPAT_{rule_id}",\n                    "rule_type": "rare_pattern",\n                    "column": col,\n                    "description": f"rare patterns in {col} may be suspicious",\n                    "rare_patterns": rare_patterns,\n                    "confidence": 0.6,\n                    "support": prof["non_null_count"],\n                    "usage_role": "candidate_generation_rule"\n                })\n                rule_id += 1\n\n    # 9.5 主值 typo 候选\n    if ENABLE_DOMINANT_TYPO_RULE:\n        for col, prof in profiles.items():\n            if prof["semantic_type"] not in {"categorical", "text"}:\n                continue\n\n            top_values = prof.get("top_values", [])\n            if not top_values:\n                continue\n\n            dominant = top_values[0]["value"]\n            dominant_count = top_values[0]["count"]\n            dominant_ratio = top_values[0]["ratio"]\n\n            if dominant_count < DOMINANT_TYPO_MIN_COUNT or dominant_ratio < DOMINANT_TYPO_MIN_RATIO:\n                continue\n\n            suspicious_values = []\n            for item in top_values[1:]:\n                v = item["value"]\n                if abs(len(v) - len(dominant)) > DOMINANT_TYPO_MAX_EDIT_DISTANCE:\n                    continue\n                if levenshtein_distance(v, dominant) <= DOMINANT_TYPO_MAX_EDIT_DISTANCE:\n                    suspicious_values.append(v)\n\n            if suspicious_values:\n                rules.append({\n                    "rule_id": f"CAND_DTYPO_{rule_id}",\n                    "rule_type": "dominant_value_typo",\n                    "column": col,\n                    "description": f"values close to dominant value in {col} may be typos",\n                    "dominant_value": dominant,\n                    "suspicious_values": suspicious_values,\n                    "confidence": 0.7,\n                    "support": dominant_count,\n                    "usage_role": "candidate_generation_rule"\n                })\n                rule_id += 1\n\n    # 9.6 高风险缺失规则\n    for col in HIGH_RISK_MISSING_COLUMNS:\n        if col not in profiles:\n            continue\n        prof = profiles[col]\n        rules.append({\n            "rule_id": f"CAND_HRMISS_{rule_id}",\n            "rule_type": "high_risk_missing",\n            "column": col,\n            "description": f"{col} missing values are suspicious in candidate generation",\n            "confidence": 0.8,\n            "support": prof["non_null_count"],\n            "usage_role": "candidate_generation_rule"\n        })\n        rule_id += 1\n\n    # 9.7 Score-Sample 联动\n    if "Score" in df.columns and "Sample" in df.columns:\n        rules.append({\n            "rule_id": f"CAND_PAIR_{rule_id}",\n            "rule_type": "paired_missing_consistency",\n            "columns": ["Score", "Sample"],\n            "description": "Score and Sample should usually co-occur",\n            "confidence": 0.8,\n            "support": len(df),\n            "usage_role": "candidate_generation_rule"\n        })\n        rule_id += 1\n\n    return rules\n\n\n# ============================================================\n# 10. 规则优先级\n# ============================================================\n\ndef assign_rule_priority(rule: Dict[str, Any]) -> str:\n    rule_type = rule["rule_type"]\n    conf = rule.get("confidence", 0.0)\n    supp = rule.get("support", 0)\n    usage_role = rule.get("usage_role", "candidate_generation_rule")\n\n    if usage_role == "candidate_generation_rule":\n        if conf >= 0.85 and supp >= 20:\n            return "medium"\n        return "low"\n\n    if rule_type == "functional_dependency":\n        if conf >= 0.995 and supp >= 20:\n            return "high"\n        return "medium"\n\n    if rule_type == "not_null":\n        return "high" if conf >= 0.99 else "medium"\n\n    if rule_type == "enumeration_domain":\n        return "medium"\n\n    if rule_type == "pattern":\n        return "medium" if conf >= 0.9 else "low"\n\n    if rule_type == "numeric_range":\n        return "medium"\n\n    return "low"\n\n\ndef enrich_rules_with_priority(rule_groups: Dict[str, List[Dict[str, Any]]]) -> Dict[str, List[Dict[str, Any]]]:\n    new_groups = {}\n    for group_name, rules in rule_groups.items():\n        enriched = []\n        for r in rules:\n            r2 = dict(r)\n            r2["priority"] = assign_rule_priority(r2)\n            enriched.append(r2)\n        new_groups[group_name] = enriched\n    return new_groups\n\n\n# ============================================================\n# 11. 主流程\n# ============================================================\n\ndef build_rule_pool(input_csv: str, output_json: str):\n    df = pd.read_csv(input_csv, dtype=str)\n    df = maybe_drop_unnamed_columns(df)\n\n    for col in df.columns:\n        df[col] = normalize_series(df[col])\n\n    profiles = analyze_columns(df)\n\n    schema_rules = build_schema_rules(df, profiles)\n    fd_rules = build_fd_rules(df, profiles)\n    soft_fd_rules = build_soft_fd_rules(df, profiles)\n    candidate_rules = build_candidate_generation_rules(df, profiles)\n\n    rule_groups = {\n        "schema_rules": schema_rules,\n        "fd_rules": fd_rules,\n        "soft_fd_rules": soft_fd_rules,\n        "candidate_rules": candidate_rules\n    }\n    rule_groups = enrich_rules_with_priority(rule_groups)\n\n    rule_pool = {\n        "metadata": {\n            "source_file": input_csv,\n            "row_count": int(len(df)),\n            "column_count": int(len(df.columns)),\n            "design_goal": "high_recall_candidate_generation",\n            "notes": [\n                "schema_rules and fd_rules are relatively strong rules",\n                "soft_fd_rules and candidate_rules are weak signals for high-recall candidate generation",\n                "candidate set is allowed to include clean tuples",\n                "global_dominant_value / context dominant / typo-aware rules should not be treated as hard error rules"\n            ]\n        },\n        "column_profiles": profiles,\n        "rules": rule_groups\n    }\n\n    with open(output_json, "w", encoding="utf-8") as f:\n        json.dump(rule_pool, f, ensure_ascii=False, indent=2)\n\n    print(f"[OK] Rule pool saved to: {output_json}")\n    print(f"Schema rules: {len(schema_rules)}")\n    print(f"FD rules: {len(fd_rules)}")\n    print(f"Soft FD rules: {len(soft_fd_rules)}")\n    print(f"Candidate generation rules: {len(candidate_rules)}")\n\n    print("\\nDetected semantic types:")\n    for col, prof in profiles.items():\n        print(\n            f"  {col}: detected_type={prof[\'detected_type\']}, "\n            f"semantic_type={prof[\'semantic_type\']}, "\n            f"unique_ratio={prof[\'unique_ratio\']}, "\n            f"numeric_parse_ratio={prof[\'numeric_parse_ratio\']}"\n        )\n\n    print("\\nSpecial notes:")\n    if "Score" in profiles:\n        print("  - Added Score-specific format and high-risk missing rules")\n    if "Sample" in profiles:\n        print("  - Added Sample-specific regex / suffix typo-aware / high-risk missing rules")\n    if "Score" in profiles and "Sample" in profiles:\n        print("  - Added Score-Sample paired consistency rule")\n\n\nif __name__ == "__main__":\n    build_rule_pool(INPUT_CSV, OUTPUT_JSON)',
    'flights': 'import json\nimport math\nimport re\nfrom collections import Counter\nfrom itertools import combinations\nfrom typing import Dict, List, Any, Optional\n\nimport pandas as pd\n\nINPUT_CSV = "/mnt/mydata/dq/projects/Splittree/flights/flights_dirty.csv"\nOUTPUT_JSON = "rule_pool_flights.json"\n\nMISSING_TOKENS = {\n    "", "empty", "null", "none", "nan", "na", "n/a", "missing", "unk",\n    "not available", "contact airline"\n}\n\nNUMERIC_RATIO_THRESHOLD = 0.90\nENUM_UNIQUE_THRESHOLD = 30\nENUM_RATIO_THRESHOLD = 0.05\n\nID_LIKE_UNIQUE_RATIO_THRESHOLD = 0.98\nCODE_LIKE_AVG_LEN_THRESHOLD = 20\nCODE_LIKE_DOMINANT_PATTERN_THRESHOLD = 0.70\nDOMINANT_PATTERN_THRESHOLD = 0.70\nDOMINANT_TYPO_MIN_RATIO = 0.50\n\nMAX_LHS_SIZE = 2\nFD_CONFIDENCE_THRESHOLD = 0.98\nMIN_SUPPORT_ROWS = 5\n\nSOFT_FD_CONFIDENCE_THRESHOLD = 0.80\nSOFT_FD_MIN_GROUP_SIZE = 3\nPAIR_CONTEXT_MIN_RATIO = 0.70\nPAIR_CONTEXT_MIN_GROUP_SIZE = 2\n\nHIGH_CARDINALITY_RATIO_FOR_LHS = 0.95\nALLOW_INDEX_COLUMN = False\nSKIP_SCHEMA_FOR_ID_LIKE = True\n\nTIME_COLUMNS = {"sched_dep_time", "act_dep_time", "sched_arr_time", "act_arr_time"}\nTARGET_CANDIDATE_COLUMNS = set(TIME_COLUMNS)\nHIGH_RISK_MISSING_COLUMNS = set(TIME_COLUMNS)\n\nENABLE_RARE_VALUE_RULE = True\nRARE_VALUE_MAX_FREQ = 2\nENABLE_RARE_PATTERN_RULE = True\nRARE_PATTERN_MAX_RATIO = 0.02\n\n\ndef normalize_value(x):\n    if pd.isna(x):\n        return None\n    s = str(x).strip()\n    if s.lower() in MISSING_TOKENS:\n        return None\n    return s.lower()\n\n\ndef normalize_series(s):\n    return s.map(normalize_value)\n\n\ndef maybe_drop_unnamed_columns(df):\n    keep_cols = [c for c in df.columns if not str(c).lower().startswith("unnamed:")]\n    return df[keep_cols].copy()\n\n\ndef detect_basic_pattern(value):\n    if value is None:\n        return "NULL"\n    parts, prev_type, cnt = [], None, 0\n    for ch in value:\n        if ch.isdigit():\n            cur = "D"\n        elif ch.isalpha():\n            cur = "L"\n        elif ch in {" ", "-", "_", "/", ".", ",", "(", ")", "%", ":", ";", "&", "\'", "+"}:\n            cur = "S"\n        else:\n            cur = "X"\n        if cur == prev_type:\n            cnt += 1\n        else:\n            if prev_type is not None:\n                parts.append(f"{prev_type}{cnt}")\n            prev_type = cur\n            cnt = 1\n    if prev_type is not None:\n        parts.append(f"{prev_type}{cnt}")\n    return "".join(parts)\n\n\ndef try_parse_numeric(series):\n    cleaned = series.dropna().astype(str).str.replace(",", "", regex=False).str.replace("%", "", regex=False)\n    numeric = pd.to_numeric(cleaned, errors="coerce")\n    success_ratio = numeric.notna().mean() if len(cleaned) > 0 else 0.0\n    return numeric, success_ratio\n\n\ndef shannon_entropy(series):\n    vals = series.dropna().tolist()\n    if not vals:\n        return 0.0\n    cnt = Counter(vals)\n    total = len(vals)\n    ent = 0.0\n    for c in cnt.values():\n        p = c / total\n        ent -= p * math.log2(p)\n    return ent\n\n\ndef value_frequency_dict(series, topk=20):\n    cnt = Counter(series.dropna().tolist())\n    total = sum(cnt.values()) if cnt else 0\n    out = []\n    for k, v in cnt.most_common(topk):\n        out.append({"value": k, "count": v, "ratio": round(v / total, 6) if total > 0 else 0.0})\n    return out\n\n\ndef parse_time_like(s: Optional[str]) -> Optional[int]:\n    if s is None:\n        return None\n    s = str(s).strip().lower()\n    s = re.sub(r"\\s+", " ", s)\n    for junk in ["(estimated runway)", "(estimated)", "(actual)", "(gate)", "(runway)", "(+8:00)", "(-00:00)"]:\n        s = s.replace(junk, "").strip()\n    s = re.sub(r"\\bdec\\s+\\d{1,2}\\b", "", s).strip()\n    m = re.search(r"(\\d{1,2}:\\d{2})\\s*(a\\.m\\.|p\\.m\\.)", s)\n    if not m:\n        return None\n    hhmm = m.group(1); ap = m.group(2)\n    hh, mm = map(int, hhmm.split(":"))\n    if ap == "p.m." and hh != 12:\n        hh += 12\n    if ap == "a.m." and hh == 12:\n        hh = 0\n    return hh * 60 + mm\n\n\ndef circ_diff(a: Optional[int], b: Optional[int]) -> Optional[int]:\n    if a is None or b is None:\n        return None\n    d = a - b\n    while d <= -720:\n        d += 1440\n    while d > 720:\n        d -= 1440\n    return d\n\n\ndef duration(start: Optional[int], end: Optional[int]) -> Optional[int]:\n    if start is None or end is None:\n        return None\n    d = end - start\n    if d < 0:\n        d += 1440\n    return d\n\n\ndef is_index_like_column(series):\n    s = series.dropna()\n    if len(s) == 0:\n        return False\n    numeric = pd.to_numeric(s, errors="coerce")\n    if numeric.notna().mean() < 0.95:\n        return False\n    unique_ratio = s.nunique() / len(s)\n    return unique_ratio > 0.98\n\n\ndef is_id_like_column(non_null, unique_ratio, numeric_ratio, avg_len):\n    if len(non_null) == 0:\n        return False\n    if unique_ratio >= ID_LIKE_UNIQUE_RATIO_THRESHOLD and avg_len <= CODE_LIKE_AVG_LEN_THRESHOLD:\n        return True\n    if unique_ratio >= ID_LIKE_UNIQUE_RATIO_THRESHOLD and numeric_ratio >= NUMERIC_RATIO_THRESHOLD:\n        return True\n    return False\n\n\ndef is_code_like_column(non_null, unique_ratio, numeric_ratio, avg_len, top_patterns):\n    if len(non_null) == 0:\n        return False\n    dominant_ratio = top_patterns[0]["ratio"] if top_patterns else 0.0\n    if avg_len <= CODE_LIKE_AVG_LEN_THRESHOLD and dominant_ratio >= CODE_LIKE_DOMINANT_PATTERN_THRESHOLD:\n        if unique_ratio > ENUM_RATIO_THRESHOLD:\n            return True\n    if numeric_ratio >= 0.95 and avg_len <= 15 and unique_ratio < ID_LIKE_UNIQUE_RATIO_THRESHOLD:\n        return True\n    return False\n\n\ndef calc_fd_confidence_and_support(df, lhs_cols, rhs_col):\n    sub = df[lhs_cols + [rhs_col]].dropna()\n    support = len(sub)\n    if support < MIN_SUPPORT_ROWS:\n        return 0.0, support\n    grouped = sub.groupby(lhs_cols, dropna=True)[rhs_col]\n    majority_sum = 0\n    for _, grp in grouped:\n        cnt = Counter(grp.tolist())\n        majority_sum += cnt.most_common(1)[0][1]\n    confidence = majority_sum / support if support > 0 else 0.0\n    return round(confidence, 6), int(support)\n\n\ndef calc_soft_fd_confidence_and_support(df, lhs_cols, rhs_col):\n    sub = df[lhs_cols + [rhs_col]].dropna()\n    support = len(sub)\n    if support < SOFT_FD_MIN_GROUP_SIZE:\n        return 0.0, support\n    grouped = sub.groupby(lhs_cols, dropna=True)[rhs_col]\n    majority_sum = 0\n    for _, grp in grouped:\n        if len(grp) < SOFT_FD_MIN_GROUP_SIZE:\n            continue\n        cnt = Counter(grp.tolist())\n        majority_sum += cnt.most_common(1)[0][1]\n    confidence = majority_sum / support if support > 0 else 0.0\n    return round(confidence, 6), int(support)\n\n\ndef calc_not_null_confidence_and_support(series):\n    total = len(series)\n    if total == 0:\n        return 0.0, 0\n    non_null = series.notna().sum()\n    return round(non_null / total, 6), int(total)\n\n\ndef calc_pattern_confidence_and_support(series, dominant_pattern):\n    non_null = series.dropna()\n    support = len(non_null)\n    if support == 0:\n        return 0.0, 0\n    pats = non_null.map(detect_basic_pattern)\n    ok = (pats == dominant_pattern).sum()\n    return round(ok / support, 6), int(support)\n\n\ndef analyze_columns(df):\n    profiles = {}\n    n = len(df)\n    for col in df.columns:\n        s = normalize_series(df[col])\n        non_null = s.dropna()\n        missing_rate = 1.0 - (len(non_null) / n if n > 0 else 0.0)\n        unique_count = non_null.nunique()\n        unique_ratio = unique_count / len(non_null) if len(non_null) > 0 else 0.0\n        numeric_vals, numeric_ratio = try_parse_numeric(non_null)\n        patterns = non_null.map(detect_basic_pattern)\n        pattern_counter = Counter(patterns.tolist())\n        total_patterns = sum(pattern_counter.values())\n        top_patterns = [{"pattern": p, "count": c, "ratio": round(c / total_patterns, 6)} for p, c in pattern_counter.most_common(10)]\n        lengths = non_null.map(lambda x: len(str(x)))\n        avg_len = float(lengths.mean()) if len(lengths) > 0 else 0.0\n        profile = {\n            "column": col,\n            "missing_rate": round(missing_rate, 6),\n            "non_null_count": int(len(non_null)),\n            "unique_count": int(unique_count),\n            "unique_ratio": round(unique_ratio, 6),\n            "numeric_parse_ratio": round(float(numeric_ratio), 6),\n            "entropy": round(shannon_entropy(non_null), 6),\n            "detected_type": None,\n            "semantic_type": None,\n            "index_like": is_index_like_column(non_null),\n            "avg_length": round(avg_len, 6),\n            "top_values": value_frequency_dict(non_null, topk=20),\n            "top_patterns": top_patterns,\n            "value_counter": Counter(non_null.tolist()),\n        }\n        if numeric_ratio >= NUMERIC_RATIO_THRESHOLD:\n            profile["detected_type"] = "numeric"\n        else:\n            if unique_count <= ENUM_UNIQUE_THRESHOLD or unique_ratio <= ENUM_RATIO_THRESHOLD:\n                profile["detected_type"] = "categorical"\n            else:\n                profile["detected_type"] = "text"\n        if profile["index_like"]:\n            profile["semantic_type"] = "id_like"\n        elif is_id_like_column(non_null, unique_ratio, numeric_ratio, avg_len):\n            profile["semantic_type"] = "id_like"\n        elif is_code_like_column(non_null, unique_ratio, numeric_ratio, avg_len, top_patterns):\n            profile["semantic_type"] = "code_like"\n        elif profile["detected_type"] == "numeric":\n            profile["semantic_type"] = "numeric"\n        elif profile["detected_type"] == "categorical":\n            profile["semantic_type"] = "categorical"\n        else:\n            profile["semantic_type"] = "text"\n        profiles[col] = profile\n    return profiles\n\n\ndef build_schema_rules(df, profiles):\n    rules = []\n    rule_id = 1\n    for col, info in profiles.items():\n        if col not in TARGET_CANDIDATE_COLUMNS:\n            continue\n        series = normalize_series(df[col])\n        not_null_threshold = 0.70 if col in {"act_dep_time", "act_arr_time"} else 0.55\n        if info["missing_rate"] <= not_null_threshold:\n            confidence, support = calc_not_null_confidence_and_support(series)\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "not_null",\n                "column": col,\n                "description": f"{col} should not be null",\n                "confidence": confidence,\n                "support": support,\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n        if len(info["top_patterns"]) > 0:\n            main_pattern = info["top_patterns"][0]\n            if main_pattern["ratio"] >= DOMINANT_PATTERN_THRESHOLD:\n                confidence, support = calc_pattern_confidence_and_support(series, main_pattern["pattern"])\n                rules.append({\n                    "rule_id": f"SCHEMA_{rule_id}",\n                    "rule_type": "pattern",\n                    "column": col,\n                    "description": f"{col} should mostly follow the dominant pattern",\n                    "pattern": main_pattern["pattern"],\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "strong_rule",\n                })\n                rule_id += 1\n        for rtype, regex, conf in [\n            ("time_format", r"^\\d{1,2}:\\d{2}\\s*(a\\.m\\.|p\\.m\\.)$", 0.85),\n            ("datetime_time_format", r"^(\\d{1,2}/\\d{1,2}/\\d{4}\\s+)?\\d{1,2}:\\d{2}\\s*(a\\.m\\.|p\\.m\\.)(\\s+\\w+\\s+\\d{1,2})?.*$", 0.8),\n            ("time_loose_pattern", r".*\\d{1,2}:\\d{2}\\s*(a\\.m\\.|p\\.m\\.).*", 0.8),\n        ]:\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": rtype,\n                "column": col,\n                "description": f"{col} regex check {rtype}",\n                "regex": regex,\n                "confidence": conf,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n    return rules\n\n\ndef select_fd_lhs_candidates(profiles):\n    candidates = []\n    for col, info in profiles.items():\n        if (not ALLOW_INDEX_COLUMN) and info.get("index_like", False):\n            continue\n        if info["unique_ratio"] >= HIGH_CARDINALITY_RATIO_FOR_LHS:\n            continue\n        candidates.append(col)\n    return candidates\n\n\ndef build_fd_rules(df, profiles):\n    rules = []\n    rule_id = 1\n    cols = list(df.columns)\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in cols})\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n    rhs_candidates = [c for c in TARGET_CANDIDATE_COLUMNS if c in cols]\n    lhs_sets = []\n    for k in range(1, MAX_LHS_SIZE + 1):\n        lhs_sets.extend(list(combinations(lhs_candidates, k)))\n    for lhs in lhs_sets:\n        for rhs in rhs_candidates:\n            if rhs in lhs:\n                continue\n            confidence, support = calc_fd_confidence_and_support(norm_df, list(lhs), rhs)\n            if support < MIN_SUPPORT_ROWS:\n                continue\n            if confidence >= FD_CONFIDENCE_THRESHOLD:\n                rules.append({\n                    "rule_id": f"FD_{rule_id}",\n                    "rule_type": "functional_dependency",\n                    "lhs": list(lhs),\n                    "rhs": rhs,\n                    "description": f"{\', \'.join(lhs)} -> {rhs}",\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "strong_rule",\n                })\n                rule_id += 1\n    dedup = {(tuple(sorted(r["lhs"])), r["rhs"]): r for r in rules}\n    return list(dedup.values())\n\n\ndef build_soft_fd_rules(df, profiles):\n    rules = []\n    rule_id = 1\n    cols = list(df.columns)\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in cols})\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n    rhs_candidates = [c for c in TARGET_CANDIDATE_COLUMNS if c in cols]\n    lhs_sets = []\n    for k in range(1, MAX_LHS_SIZE + 1):\n        lhs_sets.extend(list(combinations(lhs_candidates, k)))\n    for lhs in lhs_sets:\n        for rhs in rhs_candidates:\n            if rhs in lhs:\n                continue\n            confidence, support = calc_soft_fd_confidence_and_support(norm_df, list(lhs), rhs)\n            if support < SOFT_FD_MIN_GROUP_SIZE:\n                continue\n            if SOFT_FD_CONFIDENCE_THRESHOLD <= confidence < FD_CONFIDENCE_THRESHOLD:\n                rules.append({\n                    "rule_id": f"CAND_SOFTFD_{rule_id}",\n                    "rule_type": "soft_functional_dependency",\n                    "lhs": list(lhs),\n                    "rhs": rhs,\n                    "description": f"soft FD: {\', \'.join(lhs)} -> {rhs}",\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "candidate_generation_rule",\n                })\n                rule_id += 1\n    return rules\n\n\ndef build_pair_context_rules(df):\n    rules = []\n    rule_id = 1\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in df.columns})\n    pair_specs = [\n        (["flight", "sched_dep_time"], "act_dep_time"),\n        (["src", "sched_dep_time"], "act_dep_time"),\n        (["flight", "sched_arr_time"], "act_arr_time"),\n        (["src", "sched_arr_time"], "act_arr_time"),\n    ]\n    for lhs, rhs in pair_specs:\n        if any(c not in norm_df.columns for c in lhs + [rhs]):\n            continue\n        sub = norm_df[lhs + [rhs]].dropna()\n        if len(sub) < PAIR_CONTEXT_MIN_GROUP_SIZE:\n            continue\n        grouped = sub.groupby(lhs, dropna=True)[rhs]\n        majority_map = {}\n        total_support = 0\n        for key, grp in grouped:\n            if len(grp) < PAIR_CONTEXT_MIN_GROUP_SIZE:\n                continue\n            cnt = Counter(grp.tolist())\n            maj_val, maj_cnt = cnt.most_common(1)[0]\n            ratio = maj_cnt / len(grp)\n            if ratio >= PAIR_CONTEXT_MIN_RATIO:\n                if not isinstance(key, tuple):\n                    key = (key,)\n                majority_map["||".join(map(str, key))] = {"dominant_value": maj_val, "group_size": len(grp), "ratio": round(ratio, 6)}\n                total_support += len(grp)\n        if majority_map:\n            rules.append({\n                "rule_id": f"CAND_PAIRCTX_{rule_id}",\n                "rule_type": "dominant_value_by_context_pair",\n                "lhs": lhs,\n                "rhs": rhs,\n                "description": f"context pair dominant: {\', \'.join(lhs)} -> dominant {rhs}",\n                "mapping_size": len(majority_map),\n                "majority_map": majority_map,\n                "confidence": 0.84,\n                "support": total_support,\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n    return rules\n\n\ndef build_time_window_rules(df):\n    rules = []\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in df.columns})\n\n    for col in ["act_dep_time", "act_arr_time"]:\n        if col in norm_df.columns:\n            rules.append({\n                "rule_id": f"CAND_ACTFULL_{1 if col==\'act_dep_time\' else 2}",\n                "rule_type": "actual_time_global_candidate",\n                "column": col,\n                "description": f"{col} is globally included for high recall on flights",\n                "confidence": 0.7,\n                "support": len(norm_df),\n                "usage_role": "candidate_generation_rule",\n            })\n\n    if {"sched_dep_time", "act_dep_time"}.issubset(norm_df.columns):\n        sched = norm_df["sched_dep_time"].map(parse_time_like)\n        act = norm_df["act_dep_time"].map(parse_time_like)\n        diffs = [circ_diff(a, s) for a, s in zip(act, sched) if a is not None and s is not None]\n        if diffs:\n            ds = pd.Series(diffs)\n            lower = int(math.floor(ds.quantile(0.0005) - 15))\n            upper = int(math.ceil(ds.quantile(0.9995) + 30))\n            rules.append({\n                "rule_id": "CAND_DELAYWIN_1",\n                "rule_type": "delay_window",\n                "reference_column": "sched_dep_time",\n                "target_column": "act_dep_time",\n                "lower_bound": lower,\n                "upper_bound": upper,\n                "description": "act_dep_time should usually be within learned delay window of sched_dep_time",\n                "confidence": 0.82,\n                "support": len(diffs),\n                "usage_role": "candidate_generation_rule",\n            })\n\n    if {"sched_arr_time", "act_arr_time"}.issubset(norm_df.columns):\n        sched = norm_df["sched_arr_time"].map(parse_time_like)\n        act = norm_df["act_arr_time"].map(parse_time_like)\n        diffs = [circ_diff(a, s) for a, s in zip(act, sched) if a is not None and s is not None]\n        if diffs:\n            ds = pd.Series(diffs)\n            lower = int(math.floor(ds.quantile(0.0005) - 15))\n            upper = int(math.ceil(ds.quantile(0.9995) + 30))\n            rules.append({\n                "rule_id": "CAND_DELAYWIN_2",\n                "rule_type": "delay_window",\n                "reference_column": "sched_arr_time",\n                "target_column": "act_arr_time",\n                "lower_bound": lower,\n                "upper_bound": upper,\n                "description": "act_arr_time should usually be within learned delay window of sched_arr_time",\n                "confidence": 0.82,\n                "support": len(diffs),\n                "usage_role": "candidate_generation_rule",\n            })\n\n    needed = {"sched_dep_time", "sched_arr_time", "act_dep_time", "act_arr_time"}\n    if needed.issubset(norm_df.columns):\n        sdep = norm_df["sched_dep_time"].map(parse_time_like)\n        sarr = norm_df["sched_arr_time"].map(parse_time_like)\n        adep = norm_df["act_dep_time"].map(parse_time_like)\n        aarr = norm_df["act_arr_time"].map(parse_time_like)\n        diffs = []\n        for sd, sa, ad, aa in zip(sdep, sarr, adep, aarr):\n            sched_dur = duration(sd, sa)\n            act_dur = duration(ad, aa)\n            if sched_dur is None or act_dur is None:\n                continue\n            diffs.append(act_dur - sched_dur)\n        if diffs:\n            ds = pd.Series(diffs)\n            lower = int(math.floor(ds.quantile(0.001) - 20))\n            upper = int(math.ceil(ds.quantile(0.995) + 30))\n            rules.append({\n                "rule_id": "CAND_DURWIN_1",\n                "rule_type": "duration_consistency_window",\n                "sched_start_column": "sched_dep_time",\n                "sched_end_column": "sched_arr_time",\n                "act_start_column": "act_dep_time",\n                "act_end_column": "act_arr_time",\n                "lower_bound": lower,\n                "upper_bound": upper,\n                "description": "actual flight duration should usually stay within learned window around scheduled duration",\n                "confidence": 0.8,\n                "support": len(diffs),\n                "usage_role": "candidate_generation_rule",\n            })\n    return rules\n\n\ndef build_candidate_generation_rules(df, profiles):\n    rules = []\n    rule_id = 1\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in df.columns})\n\n    for col, prof in profiles.items():\n        if col not in TARGET_CANDIDATE_COLUMNS:\n            continue\n        top_values = prof.get("top_values", [])\n        if not top_values:\n            continue\n        top1 = top_values[0]\n        if top1["ratio"] >= DOMINANT_TYPO_MIN_RATIO:\n            rules.append({\n                "rule_id": f"CAND_GDOM_{rule_id}",\n                "rule_type": "global_dominant_value",\n                "column": col,\n                "description": f"global dominant value for {col}",\n                "dominant_value": top1["value"],\n                "dominant_count": top1["count"],\n                "dominant_ratio": top1["ratio"],\n                "confidence": round(top1["ratio"], 6),\n                "support": prof["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n    context_rule_id = 1\n    for rhs in TARGET_CANDIDATE_COLUMNS:\n        if rhs not in df.columns:\n            continue\n        for lhs in lhs_candidates:\n            if lhs == rhs:\n                continue\n            sub = norm_df[[lhs, rhs]].dropna()\n            if len(sub) < SOFT_FD_MIN_GROUP_SIZE:\n                continue\n            grouped = sub.groupby(lhs)[rhs]\n            majority_map = {}\n            total_support = 0\n            for lhs_val, grp in grouped:\n                if len(grp) < SOFT_FD_MIN_GROUP_SIZE:\n                    continue\n                cnt = Counter(grp.tolist())\n                maj_val, maj_cnt = cnt.most_common(1)[0]\n                ratio = maj_cnt / len(grp)\n                if ratio >= SOFT_FD_CONFIDENCE_THRESHOLD:\n                    majority_map[lhs_val] = {"dominant_value": maj_val, "group_size": len(grp), "ratio": round(ratio, 6)}\n                    total_support += len(grp)\n            if majority_map:\n                rules.append({\n                    "rule_id": f"CAND_CTXDOM_{context_rule_id}",\n                    "rule_type": "dominant_value_by_context",\n                    "lhs": [lhs],\n                    "rhs": rhs,\n                    "description": f"context dominant: {lhs} -> dominant {rhs}",\n                    "mapping_size": len(majority_map),\n                    "majority_map": majority_map,\n                    "confidence": 0.85,\n                    "support": total_support,\n                    "usage_role": "candidate_generation_rule",\n                })\n                context_rule_id += 1\n\n    if ENABLE_RARE_VALUE_RULE:\n        for col, prof in profiles.items():\n            if col not in TARGET_CANDIDATE_COLUMNS:\n                continue\n            counter = prof["value_counter"]\n            rare_values = [v for v, c in counter.items() if c <= RARE_VALUE_MAX_FREQ]\n            if rare_values:\n                rules.append({\n                    "rule_id": f"CAND_RAREVAL_{rule_id}",\n                    "rule_type": "rare_value",\n                    "column": col,\n                    "description": f"rare values in {col} may be suspicious",\n                    "rare_values": rare_values[:5000],\n                    "confidence": 0.6,\n                    "support": sum(counter[v] for v in rare_values),\n                    "usage_role": "candidate_generation_rule",\n                })\n                rule_id += 1\n\n    if ENABLE_RARE_PATTERN_RULE:\n        for col, prof in profiles.items():\n            if col not in TARGET_CANDIDATE_COLUMNS:\n                continue\n            top_patterns = prof.get("top_patterns", [])\n            rare_patterns = [x["pattern"] for x in top_patterns if x["ratio"] <= RARE_PATTERN_MAX_RATIO]\n            if rare_patterns:\n                rules.append({\n                    "rule_id": f"CAND_RAREPAT_{rule_id}",\n                    "rule_type": "rare_pattern",\n                    "column": col,\n                    "description": f"rare patterns in {col} may be suspicious",\n                    "rare_patterns": rare_patterns,\n                    "confidence": 0.6,\n                    "support": prof["non_null_count"],\n                    "usage_role": "candidate_generation_rule",\n                })\n                rule_id += 1\n\n    for col in HIGH_RISK_MISSING_COLUMNS:\n        if col not in profiles:\n            continue\n        prof = profiles[col]\n        rules.append({\n            "rule_id": f"CAND_HRMISS_{rule_id}",\n            "rule_type": "high_risk_missing",\n            "column": col,\n            "description": f"{col} missing values are suspicious in candidate generation",\n            "confidence": 0.8,\n            "support": prof["non_null_count"],\n            "usage_role": "candidate_generation_rule",\n        })\n        rule_id += 1\n\n    for a, b in [("sched_dep_time", "act_dep_time"), ("sched_arr_time", "act_arr_time")]:\n        if a in df.columns and b in df.columns:\n            rules.append({\n                "rule_id": f"CAND_PAIR_{rule_id}",\n                "rule_type": "paired_missing_consistency",\n                "columns": [a, b],\n                "description": f"{a} and {b} should usually co-occur",\n                "confidence": 0.8,\n                "support": len(df),\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n    for start_col, end_col in [("sched_dep_time", "sched_arr_time"), ("act_dep_time", "act_arr_time")]:\n        if start_col in df.columns and end_col in df.columns:\n            rules.append({\n                "rule_id": f"CAND_TIMEPAIR_{rule_id}",\n                "rule_type": "temporal_pair_consistency",\n                "columns": [start_col, end_col],\n                "description": f"{end_col} should usually not be earlier than {start_col}",\n                "confidence": 0.8,\n                "support": len(df),\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n    rules.extend(build_pair_context_rules(df))\n    rules.extend(build_time_window_rules(df))\n    return rules\n\n\ndef assign_rule_priority(rule):\n    if rule.get("usage_role", "candidate_generation_rule") == "candidate_generation_rule":\n        if rule.get("confidence", 0.0) >= 0.85 and rule.get("support", 0) >= 20:\n            return "medium"\n        return "low"\n    return "medium"\n\n\ndef enrich_rules_with_priority(rule_groups):\n    new_groups = {}\n    for group_name, rules in rule_groups.items():\n        enriched = []\n        for r in rules:\n            r2 = dict(r)\n            r2["priority"] = assign_rule_priority(r2)\n            enriched.append(r2)\n        new_groups[group_name] = enriched\n    return new_groups\n\n\ndef build_rule_pool(input_csv, output_json):\n    df = pd.read_csv(input_csv, dtype=str)\n    df = maybe_drop_unnamed_columns(df)\n    for col in df.columns:\n        df[col] = normalize_series(df[col])\n    profiles = analyze_columns(df)\n    schema_rules = build_schema_rules(df, profiles)\n    fd_rules = build_fd_rules(df, profiles)\n    soft_fd_rules = build_soft_fd_rules(df, profiles)\n    candidate_rules = build_candidate_generation_rules(df, profiles)\n    rule_groups = {"schema_rules": schema_rules, "fd_rules": fd_rules, "soft_fd_rules": soft_fd_rules, "candidate_rules": candidate_rules}\n    rule_groups = enrich_rules_with_priority(rule_groups)\n    rule_pool = {\n        "metadata": {\n            "source_file": input_csv,\n            "row_count": int(len(df)),\n            "column_count": int(len(df.columns)),\n            "design_goal": "high_recall_candidate_generation",\n            "notes": [\n                "candidate inclusion is determined only by violating rules in this pool",\n                "candidate target columns are restricted to flight time attributes; src/flight/index serve as context only",\n                "recall is boosted mainly by rules on act_dep_time and act_arr_time",\n            ],\n        },\n        "column_profiles": profiles,\n        "rules": rule_groups,\n    }\n    with open(output_json, "w", encoding="utf-8") as f:\n        json.dump(rule_pool, f, ensure_ascii=False, indent=2)\n    print(f"[OK] Rule pool saved to: {output_json}")\n    print(f"Schema rules: {len(schema_rules)}")\n    print(f"FD rules: {len(fd_rules)}")\n    print(f"Soft FD rules: {len(soft_fd_rules)}")\n    print(f"Candidate generation rules: {len(candidate_rules)}")\n\n\nif __name__ == "__main__":\n    build_rule_pool(INPUT_CSV, OUTPUT_JSON)\n',
    'beers': 'import json\nimport math\nimport re\nfrom collections import Counter\nfrom itertools import combinations\nfrom typing import Dict, List, Any, Optional\n\nimport pandas as pd\n\nINPUT_CSV = "/mnt/mydata/dq/projects/Splittree/beers/beers_dirty.csv"\nOUTPUT_JSON = "rule_pool_beers.json"\n\nMISSING_TOKENS = {\n    "", "empty", "null", "none", "nan", "na", "n/a", "missing", "unk",\n    "not available", "contact airline"\n}\n\nNUMERIC_RATIO_THRESHOLD = 0.90\nENUM_UNIQUE_THRESHOLD = 40\nENUM_RATIO_THRESHOLD = 0.08\n\nID_LIKE_UNIQUE_RATIO_THRESHOLD = 0.98\nCODE_LIKE_AVG_LEN_THRESHOLD = 20\nCODE_LIKE_DOMINANT_PATTERN_THRESHOLD = 0.70\nDOMINANT_PATTERN_THRESHOLD = 0.70\nDOMINANT_TYPO_MIN_RATIO = 0.50\n\nMAX_LHS_SIZE = 2\nFD_CONFIDENCE_THRESHOLD = 0.98\nMIN_SUPPORT_ROWS = 5\n\nSOFT_FD_CONFIDENCE_THRESHOLD = 0.80\nSOFT_FD_MIN_GROUP_SIZE = 3\nPAIR_CONTEXT_MIN_RATIO = 0.70\nPAIR_CONTEXT_MIN_GROUP_SIZE = 2\n\nHIGH_CARDINALITY_RATIO_FOR_LHS = 0.95\nALLOW_INDEX_COLUMN = False\n\nTARGET_CANDIDATE_COLUMNS = {\n    "beer_name", "style", "ounces", "abv", "ibu", "brewery_name", "city", "state"\n}\nHIGH_RISK_MISSING_COLUMNS = {"abv", "ibu", "style", "ounces", "brewery_name", "city", "state"}\n\nENABLE_RARE_VALUE_RULE = True\nRARE_VALUE_MAX_FREQ = 2\nENABLE_RARE_PATTERN_RULE = True\nRARE_PATTERN_MAX_RATIO = 0.02\n\n# 这些列天然长尾，不能再用 rare/global-dominant 这类规则硬打候选\nSKIP_RARE_VALUE_COLUMNS = {"beer_name", "brewery_name"}\nSKIP_RARE_PATTERN_COLUMNS = {"beer_name"}\nSKIP_GLOBAL_DOMINANT_COLUMNS = {"beer_name", "brewery_name", "style"}\n\n\ndef normalize_value(x):\n    if pd.isna(x):\n        return None\n    s = str(x).strip()\n    if s.lower() in MISSING_TOKENS:\n        return None\n    return s.lower()\n\n\ndef normalize_series(s):\n    return s.map(normalize_value)\n\n\ndef maybe_drop_unnamed_columns(df):\n    keep_cols = [c for c in df.columns if not str(c).lower().startswith("unnamed:")]\n    return df[keep_cols].copy()\n\n\ndef detect_basic_pattern(value):\n    if value is None:\n        return "NULL"\n    parts, prev_type, cnt = [], None, 0\n    for ch in value:\n        if ch.isdigit():\n            cur = "D"\n        elif ch.isalpha():\n            cur = "L"\n        elif ch in {" ", "-", "_", "/", ".", ",", "(", ")", "%", ":", ";", "&", "\'", "+"}:\n            cur = "S"\n        else:\n            cur = "X"\n        if cur == prev_type:\n            cnt += 1\n        else:\n            if prev_type is not None:\n                parts.append(f"{prev_type}{cnt}")\n            prev_type = cur\n            cnt = 1\n    if prev_type is not None:\n        parts.append(f"{prev_type}{cnt}")\n    return "".join(parts)\n\n\ndef try_parse_numeric(series):\n    cleaned = (\n        series.dropna().astype(str)\n        .str.replace(",", "", regex=False)\n        .str.replace("%", "", regex=False)\n    )\n    numeric = pd.to_numeric(cleaned, errors="coerce")\n    success_ratio = numeric.notna().mean() if len(cleaned) > 0 else 0.0\n    return numeric, success_ratio\n\n\ndef shannon_entropy(series):\n    vals = series.dropna().tolist()\n    if not vals:\n        return 0.0\n    cnt = Counter(vals)\n    total = len(vals)\n    ent = 0.0\n    for c in cnt.values():\n        p = c / total\n        ent -= p * math.log2(p)\n    return ent\n\n\ndef value_frequency_dict(series, topk=20):\n    cnt = Counter(series.dropna().tolist())\n    total = sum(cnt.values()) if cnt else 0\n    out = []\n    for k, v in cnt.most_common(topk):\n        out.append({"value": k, "count": v, "ratio": round(v / total, 6) if total > 0 else 0.0})\n    return out\n\n\ndef parse_abv_like(s: Optional[str]) -> Optional[float]:\n    if s is None:\n        return None\n    s = str(s).strip().lower().replace("%", "")\n    m = re.search(r"(\\d+(?:\\.\\d+)?)", s)\n    if not m:\n        return None\n    try:\n        return float(m.group(1))\n    except Exception:\n        return None\n\n\ndef parse_ibu_like(s: Optional[str]) -> Optional[float]:\n    if s is None:\n        return None\n    s = str(s).strip().lower()\n    if s in MISSING_TOKENS:\n        return None\n    m = re.search(r"(\\d+(?:\\.\\d+)?)", s)\n    if not m:\n        return None\n    try:\n        return float(m.group(1))\n    except Exception:\n        return None\n\n\ndef parse_ounces_like(s: Optional[str]) -> Optional[float]:\n    if s is None:\n        return None\n    s = str(s).strip().lower()\n    m = re.search(r"(\\d+(?:\\.\\d+)?)", s)\n    if not m:\n        return None\n    try:\n        return float(m.group(1))\n    except Exception:\n        return None\n\n\ndef canonicalize_ounces_value(s: Optional[str]) -> Optional[str]:\n    """\n    beers_clean 中 ounces 是纯数字（如 12），而 dirty 里常是 12.0 oz / 12.0 ounce 等。\n    这里统一规范成 clean 风格的字符串。\n    """\n    num = parse_ounces_like(s)\n    if num is None:\n        return None\n    if abs(num - round(num)) < 1e-9:\n        return str(int(round(num)))\n    # 很少用到，但保底\n    txt = f"{num:.6f}".rstrip("0").rstrip(".")\n    return txt\n\n\ndef canonicalize_abv_value(s: Optional[str]) -> Optional[str]:\n    """\n    beers_clean 中 abv 通常是纯数字字符串，不带百分号。\n    """\n    num = parse_abv_like(s)\n    if num is None:\n        return None\n    txt = f"{num:.15f}".rstrip("0").rstrip(".")\n    return txt\n\n\ndef looks_like_city_with_state_suffix(s: Optional[str]) -> bool:\n    if s is None:\n        return False\n    s = str(s).strip().lower()\n    # 如 "san diego ca" / "portland or"\n    return re.search(r"\\b[a-z]{2}$", s) is not None and len(s.split()) >= 2\n\n\ndef strip_city_state_suffix(s: Optional[str]) -> Optional[str]:\n    if s is None:\n        return None\n    s = str(s).strip().lower()\n    s2 = re.sub(r"\\s+[a-z]{2}$", "", s).strip()\n    return s2 if s2 != s else None\n\n\ndef is_index_like_column(series):\n    s = series.dropna()\n    if len(s) == 0:\n        return False\n    numeric = pd.to_numeric(s, errors="coerce")\n    if numeric.notna().mean() < 0.95:\n        return False\n    unique_ratio = s.nunique() / len(s)\n    return unique_ratio > 0.98\n\n\ndef is_id_like_column(non_null, unique_ratio, numeric_ratio, avg_len):\n    if len(non_null) == 0:\n        return False\n    if unique_ratio >= ID_LIKE_UNIQUE_RATIO_THRESHOLD and avg_len <= CODE_LIKE_AVG_LEN_THRESHOLD:\n        return True\n    if unique_ratio >= ID_LIKE_UNIQUE_RATIO_THRESHOLD and numeric_ratio >= NUMERIC_RATIO_THRESHOLD:\n        return True\n    return False\n\n\ndef is_code_like_column(non_null, unique_ratio, numeric_ratio, avg_len, top_patterns):\n    if len(non_null) == 0:\n        return False\n    dominant_ratio = top_patterns[0]["ratio"] if top_patterns else 0.0\n    if avg_len <= CODE_LIKE_AVG_LEN_THRESHOLD and dominant_ratio >= CODE_LIKE_DOMINANT_PATTERN_THRESHOLD:\n        if unique_ratio > ENUM_RATIO_THRESHOLD:\n            return True\n    if numeric_ratio >= 0.95 and avg_len <= 15 and unique_ratio < ID_LIKE_UNIQUE_RATIO_THRESHOLD:\n        return True\n    return False\n\n\ndef calc_fd_confidence_and_support(df, lhs_cols, rhs_col):\n    sub = df[lhs_cols + [rhs_col]].dropna()\n    support = len(sub)\n    if support < MIN_SUPPORT_ROWS:\n        return 0.0, support\n    grouped = sub.groupby(lhs_cols, dropna=True)[rhs_col]\n    majority_sum = 0\n    for _, grp in grouped:\n        cnt = Counter(grp.tolist())\n        majority_sum += cnt.most_common(1)[0][1]\n    confidence = majority_sum / support if support > 0 else 0.0\n    return round(confidence, 6), int(support)\n\n\ndef calc_soft_fd_confidence_and_support(df, lhs_cols, rhs_col):\n    sub = df[lhs_cols + [rhs_col]].dropna()\n    support = len(sub)\n    if support < SOFT_FD_MIN_GROUP_SIZE:\n        return 0.0, support\n    grouped = sub.groupby(lhs_cols, dropna=True)[rhs_col]\n    majority_sum = 0\n    for _, grp in grouped:\n        if len(grp) < SOFT_FD_MIN_GROUP_SIZE:\n            continue\n        cnt = Counter(grp.tolist())\n        majority_sum += cnt.most_common(1)[0][1]\n    confidence = majority_sum / support if support > 0 else 0.0\n    return round(confidence, 6), int(support)\n\n\ndef calc_not_null_confidence_and_support(series):\n    total = len(series)\n    if total == 0:\n        return 0.0, 0\n    non_null = series.notna().sum()\n    return round(non_null / total, 6), int(total)\n\n\ndef calc_pattern_confidence_and_support(series, dominant_pattern):\n    non_null = series.dropna()\n    support = len(non_null)\n    if support == 0:\n        return 0.0, 0\n    pats = non_null.map(detect_basic_pattern)\n    ok = (pats == dominant_pattern).sum()\n    return round(ok / support, 6), int(support)\n\n\ndef analyze_columns(df):\n    profiles = {}\n    n = len(df)\n    for col in df.columns:\n        s = normalize_series(df[col])\n        non_null = s.dropna()\n        missing_rate = 1.0 - (len(non_null) / n if n > 0 else 0.0)\n        unique_count = non_null.nunique()\n        unique_ratio = unique_count / len(non_null) if len(non_null) > 0 else 0.0\n        numeric_vals, numeric_ratio = try_parse_numeric(non_null)\n        patterns = non_null.map(detect_basic_pattern)\n        pattern_counter = Counter(patterns.tolist())\n        total_patterns = sum(pattern_counter.values())\n        top_patterns = [{"pattern": p, "count": c, "ratio": round(c / total_patterns, 6)} for p, c in pattern_counter.most_common(10)]\n        lengths = non_null.map(lambda x: len(str(x)))\n        avg_len = float(lengths.mean()) if len(lengths) > 0 else 0.0\n        profile = {\n            "column": col,\n            "missing_rate": round(missing_rate, 6),\n            "non_null_count": int(len(non_null)),\n            "unique_count": int(unique_count),\n            "unique_ratio": round(unique_ratio, 6),\n            "numeric_parse_ratio": round(float(numeric_ratio), 6),\n            "entropy": round(shannon_entropy(non_null), 6),\n            "detected_type": None,\n            "semantic_type": None,\n            "index_like": is_index_like_column(non_null),\n            "avg_length": round(avg_len, 6),\n            "top_values": value_frequency_dict(non_null, topk=20),\n            "top_patterns": top_patterns,\n            "value_counter": Counter(non_null.tolist()),\n        }\n        if numeric_ratio >= NUMERIC_RATIO_THRESHOLD:\n            profile["detected_type"] = "numeric"\n        else:\n            if unique_count <= ENUM_UNIQUE_THRESHOLD or unique_ratio <= ENUM_RATIO_THRESHOLD:\n                profile["detected_type"] = "categorical"\n            else:\n                profile["detected_type"] = "text"\n        if profile["index_like"]:\n            profile["semantic_type"] = "id_like"\n        elif is_id_like_column(non_null, unique_ratio, numeric_ratio, avg_len):\n            profile["semantic_type"] = "id_like"\n        elif is_code_like_column(non_null, unique_ratio, numeric_ratio, avg_len, top_patterns):\n            profile["semantic_type"] = "code_like"\n        elif profile["detected_type"] == "numeric":\n            profile["semantic_type"] = "numeric"\n        elif profile["detected_type"] == "categorical":\n            profile["semantic_type"] = "categorical"\n        else:\n            profile["semantic_type"] = "text"\n        profiles[col] = profile\n    return profiles\n\n\ndef build_schema_rules(df, profiles):\n    rules = []\n    rule_id = 1\n    for col, info in profiles.items():\n        if col not in TARGET_CANDIDATE_COLUMNS:\n            continue\n\n        series = normalize_series(df[col])\n\n        not_null_threshold = 0.75 if col in {"abv", "style", "ounces", "brewery_name", "city", "state"} else 0.55\n        if info["missing_rate"] <= not_null_threshold:\n            confidence, support = calc_not_null_confidence_and_support(series)\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "not_null",\n                "column": col,\n                "description": f"{col} should not be null",\n                "confidence": confidence,\n                "support": support,\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n        if len(info["top_patterns"]) > 0:\n            main_pattern = info["top_patterns"][0]\n            if main_pattern["ratio"] >= DOMINANT_PATTERN_THRESHOLD:\n                confidence, support = calc_pattern_confidence_and_support(series, main_pattern["pattern"])\n                rules.append({\n                    "rule_id": f"SCHEMA_{rule_id}",\n                    "rule_type": "pattern",\n                    "column": col,\n                    "description": f"{col} should mostly follow the dominant pattern",\n                    "pattern": main_pattern["pattern"],\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "strong_rule",\n                })\n                rule_id += 1\n\n        if col == "ounces":\n            # 保留宽格式规则，但更重要的是规范表示规则\n            for rtype, regex, conf in [\n                ("ounces_unit_format", r"^\\d+(?:\\.\\d+)?\\s*(oz|oz\\.|ounce|ounces|oz\\. alumi-tek|alumi-tek)$", 0.80),\n                ("ounces_loose_pattern", r".*\\d+(?:\\.\\d+)?\\s*(oz|ounce).*", 0.75),\n            ]:\n                rules.append({\n                    "rule_id": f"SCHEMA_{rule_id}",\n                    "rule_type": rtype,\n                    "column": col,\n                    "description": f"{col} regex check {rtype}",\n                    "regex": regex,\n                    "confidence": conf,\n                    "support": info["non_null_count"],\n                    "usage_role": "candidate_generation_rule",\n                })\n                rule_id += 1\n\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "ounces_canonical_format",\n                "column": col,\n                "description": "ounces should be stored in canonical clean style (e.g., 12 instead of 12.0 oz.)",\n                "confidence": 0.95,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n        if col == "abv":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "abv_numeric_format",\n                "column": col,\n                "description": "abv should usually be numeric or numeric percent",\n                "regex": r"^\\d+(?:\\.\\d+)?%?$",\n                "confidence": 0.82,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "abv_canonical_format",\n                "column": col,\n                "description": "abv should be stored in canonical clean style without redundant percent suffix",\n                "confidence": 0.95,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n        if col == "ibu":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "ibu_numeric_or_na_format",\n                "column": col,\n                "description": "ibu should usually be numeric or missing token",\n                "regex": r"^(\\d+(?:\\.\\d+)?|n/a|na|none|missing)$",\n                "confidence": 0.82,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n        if col == "state":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "state_abbr_format",\n                "column": col,\n                "description": "state should usually be a two-letter abbreviation",\n                "regex": r"^[a-z]{2}$",\n                "confidence": 0.85,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n        if col == "city":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "city_state_suffix_pollution",\n                "column": col,\n                "description": "city should not end with a trailing state abbreviation like \'san diego ca\'",\n                "confidence": 0.92,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n    return rules\n\n\ndef select_fd_lhs_candidates(profiles):\n    candidates = []\n    for col, info in profiles.items():\n        if (not ALLOW_INDEX_COLUMN) and info.get("index_like", False):\n            continue\n        if info["unique_ratio"] >= HIGH_CARDINALITY_RATIO_FOR_LHS:\n            continue\n        candidates.append(col)\n    return candidates\n\n\ndef build_fd_rules(df, profiles):\n    rules = []\n    rule_id = 1\n    cols = list(df.columns)\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in cols})\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n    rhs_candidates = [c for c in TARGET_CANDIDATE_COLUMNS if c in cols]\n    lhs_sets = []\n    for k in range(1, MAX_LHS_SIZE + 1):\n        lhs_sets.extend(list(combinations(lhs_candidates, k)))\n\n    for lhs in lhs_sets:\n        for rhs in rhs_candidates:\n            if rhs in lhs:\n                continue\n            confidence, support = calc_fd_confidence_and_support(norm_df, list(lhs), rhs)\n            if support < MIN_SUPPORT_ROWS:\n                continue\n            if confidence >= FD_CONFIDENCE_THRESHOLD:\n                rules.append({\n                    "rule_id": f"FD_{rule_id}",\n                    "rule_type": "functional_dependency",\n                    "lhs": list(lhs),\n                    "rhs": rhs,\n                    "description": f"{\', \'.join(lhs)} -> {rhs}",\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "strong_rule",\n                })\n                rule_id += 1\n\n    dedup = {(tuple(sorted(r["lhs"])), r["rhs"]): r for r in rules}\n    return list(dedup.values())\n\n\ndef build_soft_fd_rules(df, profiles):\n    rules = []\n    rule_id = 1\n    cols = list(df.columns)\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in cols})\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n    rhs_candidates = [c for c in TARGET_CANDIDATE_COLUMNS if c in cols]\n    lhs_sets = []\n    for k in range(1, MAX_LHS_SIZE + 1):\n        lhs_sets.extend(list(combinations(lhs_candidates, k)))\n\n    for lhs in lhs_sets:\n        for rhs in rhs_candidates:\n            if rhs in lhs:\n                continue\n            confidence, support = calc_soft_fd_confidence_and_support(norm_df, list(lhs), rhs)\n            if support < SOFT_FD_MIN_GROUP_SIZE:\n                continue\n            if SOFT_FD_CONFIDENCE_THRESHOLD <= confidence < FD_CONFIDENCE_THRESHOLD:\n                rules.append({\n                    "rule_id": f"CAND_SOFTFD_{rule_id}",\n                    "rule_type": "soft_functional_dependency",\n                    "lhs": list(lhs),\n                    "rhs": rhs,\n                    "description": f"soft FD: {\', \'.join(lhs)} -> {rhs}",\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "candidate_generation_rule",\n                })\n                rule_id += 1\n\n    return rules\n\n\ndef build_pair_context_rules(df):\n    rules = []\n    rule_id = 1\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in df.columns})\n    pair_specs = [\n        (["brewery_id"], "brewery_name"),\n        (["brewery_id"], "city"),\n        (["brewery_id"], "state"),\n        (["brewery_name"], "city"),\n        (["brewery_name"], "state"),\n        (["city"], "state"),\n        (["beer_name", "brewery_id"], "style"),\n        (["beer_name", "brewery_id"], "abv"),\n        (["beer_name", "brewery_id"], "ibu"),\n        (["beer_name", "brewery_id"], "ounces"),\n    ]\n    for lhs, rhs in pair_specs:\n        if any(c not in norm_df.columns for c in lhs + [rhs]):\n            continue\n        sub = norm_df[lhs + [rhs]].dropna()\n        if len(sub) < PAIR_CONTEXT_MIN_GROUP_SIZE:\n            continue\n        grouped = sub.groupby(lhs, dropna=True)[rhs]\n        majority_map = {}\n        total_support = 0\n        for key, grp in grouped:\n            if len(grp) < PAIR_CONTEXT_MIN_GROUP_SIZE:\n                continue\n            cnt = Counter(grp.tolist())\n            maj_val, maj_cnt = cnt.most_common(1)[0]\n            ratio = maj_cnt / len(grp)\n            if ratio >= PAIR_CONTEXT_MIN_RATIO:\n                if not isinstance(key, tuple):\n                    key = (key,)\n                majority_map["||".join(map(str, key))] = {\n                    "dominant_value": maj_val,\n                    "group_size": len(grp),\n                    "ratio": round(ratio, 6),\n                }\n                total_support += len(grp)\n        if majority_map:\n            rules.append({\n                "rule_id": f"CAND_PAIRCTX_{rule_id}",\n                "rule_type": "dominant_value_by_context_pair" if len(lhs) == 2 else "dominant_value_by_context",\n                "lhs": lhs,\n                "rhs": rhs,\n                "description": f"context dominant: {\', \'.join(lhs)} -> {rhs}",\n                "mapping_size": len(majority_map),\n                "majority_map": majority_map,\n                "confidence": 0.84,\n                "support": total_support,\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n    return rules\n\n\ndef build_numeric_window_rules(df):\n    rules = []\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in df.columns})\n\n    if "abv" in norm_df.columns:\n        abv_vals = norm_df["abv"].map(parse_abv_like).dropna()\n        if len(abv_vals) >= MIN_SUPPORT_ROWS:\n            ds = pd.Series(abv_vals)\n            q1 = float(ds.quantile(0.001))\n            q99 = float(ds.quantile(0.999))\n            lower = max(0.0, q1 - 0.01)\n            upper = q99 + 0.01\n            rules.append({\n                "rule_id": "CAND_NUMWIN_1",\n                "rule_type": "numeric_range_window",\n                "column": "abv",\n                "lower_bound": round(lower, 6),\n                "upper_bound": round(upper, 6),\n                "description": "abv should usually fall within learned numeric window",\n                "confidence": 0.82,\n                "support": len(abv_vals),\n                "usage_role": "candidate_generation_rule",\n            })\n\n    if "ibu" in norm_df.columns:\n        ibu_vals = norm_df["ibu"].map(parse_ibu_like).dropna()\n        if len(ibu_vals) >= MIN_SUPPORT_ROWS:\n            ds = pd.Series(ibu_vals)\n            q1 = float(ds.quantile(0.001))\n            q99 = float(ds.quantile(0.999))\n            lower = max(0.0, q1 - 5.0)\n            upper = q99 + 5.0\n            rules.append({\n                "rule_id": "CAND_NUMWIN_2",\n                "rule_type": "numeric_range_window",\n                "column": "ibu",\n                "lower_bound": round(lower, 6),\n                "upper_bound": round(upper, 6),\n                "description": "ibu should usually fall within learned numeric window",\n                "confidence": 0.82,\n                "support": len(ibu_vals),\n                "usage_role": "candidate_generation_rule",\n            })\n\n    if "ounces" in norm_df.columns:\n        oz_vals = norm_df["ounces"].map(parse_ounces_like).dropna()\n        if len(oz_vals) >= MIN_SUPPORT_ROWS:\n            ds = pd.Series(oz_vals)\n            q1 = float(ds.quantile(0.001))\n            q99 = float(ds.quantile(0.999))\n            lower = max(0.0, q1 - 1.0)\n            upper = q99 + 1.0\n            rules.append({\n                "rule_id": "CAND_NUMWIN_3",\n                "rule_type": "numeric_range_window",\n                "column": "ounces",\n                "lower_bound": round(lower, 6),\n                "upper_bound": round(upper, 6),\n                "description": "ounces should usually fall within learned numeric window",\n                "confidence": 0.82,\n                "support": len(oz_vals),\n                "usage_role": "candidate_generation_rule",\n            })\n\n    return rules\n\n\ndef build_candidate_generation_rules(df, profiles):\n    rules = []\n    rule_id = 1\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in df.columns})\n\n    for col, prof in profiles.items():\n        if col not in TARGET_CANDIDATE_COLUMNS:\n            continue\n        if col in SKIP_GLOBAL_DOMINANT_COLUMNS:\n            continue\n        top_values = prof.get("top_values", [])\n        if not top_values:\n            continue\n        top1 = top_values[0]\n        if top1["ratio"] >= DOMINANT_TYPO_MIN_RATIO:\n            rules.append({\n                "rule_id": f"CAND_GDOM_{rule_id}",\n                "rule_type": "global_dominant_value",\n                "column": col,\n                "description": f"global dominant value for {col}",\n                "dominant_value": top1["value"],\n                "dominant_count": top1["count"],\n                "dominant_ratio": top1["ratio"],\n                "confidence": round(top1["ratio"], 6),\n                "support": prof["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n    context_rule_id = 1\n    for rhs in TARGET_CANDIDATE_COLUMNS:\n        if rhs not in df.columns:\n            continue\n        for lhs in lhs_candidates:\n            if lhs == rhs:\n                continue\n            sub = norm_df[[lhs, rhs]].dropna()\n            if len(sub) < SOFT_FD_MIN_GROUP_SIZE:\n                continue\n            grouped = sub.groupby(lhs)[rhs]\n            majority_map = {}\n            total_support = 0\n            for lhs_val, grp in grouped:\n                if len(grp) < SOFT_FD_MIN_GROUP_SIZE:\n                    continue\n                cnt = Counter(grp.tolist())\n                maj_val, maj_cnt = cnt.most_common(1)[0]\n                ratio = maj_cnt / len(grp)\n                if ratio >= SOFT_FD_CONFIDENCE_THRESHOLD:\n                    majority_map[lhs_val] = {"dominant_value": maj_val, "group_size": len(grp), "ratio": round(ratio, 6)}\n                    total_support += len(grp)\n            if majority_map:\n                rules.append({\n                    "rule_id": f"CAND_CTXDOM_{context_rule_id}",\n                    "rule_type": "dominant_value_by_context",\n                    "lhs": [lhs],\n                    "rhs": rhs,\n                    "description": f"context dominant: {lhs} -> dominant {rhs}",\n                    "mapping_size": len(majority_map),\n                    "majority_map": majority_map,\n                    "confidence": 0.85,\n                    "support": total_support,\n                    "usage_role": "candidate_generation_rule",\n                })\n                context_rule_id += 1\n\n    if ENABLE_RARE_VALUE_RULE:\n        for col, prof in profiles.items():\n            if col not in TARGET_CANDIDATE_COLUMNS or col in SKIP_RARE_VALUE_COLUMNS:\n                continue\n            counter = prof["value_counter"]\n            rare_values = [v for v, c in counter.items() if c <= RARE_VALUE_MAX_FREQ]\n            if rare_values:\n                rules.append({\n                    "rule_id": f"CAND_RAREVAL_{rule_id}",\n                    "rule_type": "rare_value",\n                    "column": col,\n                    "description": f"rare values in {col} may be suspicious",\n                    "rare_values": rare_values[:5000],\n                    "confidence": 0.6,\n                    "support": sum(counter[v] for v in rare_values),\n                    "usage_role": "candidate_generation_rule",\n                })\n                rule_id += 1\n\n    if ENABLE_RARE_PATTERN_RULE:\n        for col, prof in profiles.items():\n            if col not in TARGET_CANDIDATE_COLUMNS or col in SKIP_RARE_PATTERN_COLUMNS:\n                continue\n            top_patterns = prof.get("top_patterns", [])\n            rare_patterns = [x["pattern"] for x in top_patterns if x["ratio"] <= RARE_PATTERN_MAX_RATIO]\n            if rare_patterns:\n                rules.append({\n                    "rule_id": f"CAND_RAREPAT_{rule_id}",\n                    "rule_type": "rare_pattern",\n                    "column": col,\n                    "description": f"rare patterns in {col} may be suspicious",\n                    "rare_patterns": rare_patterns,\n                    "confidence": 0.6,\n                    "support": prof["non_null_count"],\n                    "usage_role": "candidate_generation_rule",\n                })\n                rule_id += 1\n\n    for col in HIGH_RISK_MISSING_COLUMNS:\n        if col not in profiles:\n            continue\n        prof = profiles[col]\n        rules.append({\n            "rule_id": f"CAND_HRMISS_{rule_id}",\n            "rule_type": "high_risk_missing",\n            "column": col,\n            "description": f"{col} missing values are suspicious in candidate generation",\n            "confidence": 0.8,\n            "support": prof["non_null_count"],\n            "usage_role": "candidate_generation_rule",\n        })\n        rule_id += 1\n\n    if {"brewery_name", "city"}.issubset(df.columns):\n        rules.append({\n            "rule_id": f"CAND_PAIR_{rule_id}",\n            "rule_type": "paired_missing_consistency",\n            "columns": ["brewery_name", "city"],\n            "description": "brewery_name and city should usually co-occur",\n            "confidence": 0.8,\n            "support": len(df),\n            "usage_role": "candidate_generation_rule",\n        })\n        rule_id += 1\n\n    if {"brewery_name", "state"}.issubset(df.columns):\n        rules.append({\n            "rule_id": f"CAND_PAIR_{rule_id}",\n            "rule_type": "paired_missing_consistency",\n            "columns": ["brewery_name", "state"],\n            "description": "brewery_name and state should usually co-occur",\n            "confidence": 0.8,\n            "support": len(df),\n            "usage_role": "candidate_generation_rule",\n        })\n        rule_id += 1\n\n    rules.extend(build_pair_context_rules(df))\n    rules.extend(build_numeric_window_rules(df))\n    return rules\n\n\ndef assign_rule_priority(rule):\n    if rule.get("usage_role", "candidate_generation_rule") == "candidate_generation_rule":\n        if rule.get("confidence", 0.0) >= 0.85 and rule.get("support", 0) >= 20:\n            return "medium"\n        return "low"\n    return "medium"\n\n\ndef enrich_rules_with_priority(rule_groups):\n    new_groups = {}\n    for group_name, rules in rule_groups.items():\n        enriched = []\n        for r in rules:\n            r2 = dict(r)\n            r2["priority"] = assign_rule_priority(r2)\n            enriched.append(r2)\n        new_groups[group_name] = enriched\n    return new_groups\n\n\ndef build_rule_pool(input_csv, output_json):\n    df = pd.read_csv(input_csv, dtype=str)\n    df = maybe_drop_unnamed_columns(df)\n    for col in df.columns:\n        df[col] = normalize_series(df[col])\n\n    profiles = analyze_columns(df)\n    schema_rules = build_schema_rules(df, profiles)\n    fd_rules = build_fd_rules(df, profiles)\n    soft_fd_rules = build_soft_fd_rules(df, profiles)\n    candidate_rules = build_candidate_generation_rules(df, profiles)\n\n    rule_groups = {\n        "schema_rules": schema_rules,\n        "fd_rules": fd_rules,\n        "soft_fd_rules": soft_fd_rules,\n        "candidate_rules": candidate_rules,\n    }\n    rule_groups = enrich_rules_with_priority(rule_groups)\n\n    rule_pool = {\n        "metadata": {\n            "source_file": input_csv,\n            "row_count": int(len(df)),\n            "column_count": int(len(df.columns)),\n            "design_goal": "high_recall_candidate_generation",\n            "notes": [\n                "candidate inclusion is determined only by violating rules in this pool",\n                "candidate targets focus on non-id beer attributes; index/id/brewery_id mainly serve as context",\n                "recall is boosted mainly by brewery consistency rules and canonical-format rules on ounces/abv/city",\n                "beer_name and brewery_name skip rare/global-dominant heuristics to reduce false positives",\n            ],\n        },\n        "column_profiles": profiles,\n        "rules": rule_groups,\n    }\n\n    with open(output_json, "w", encoding="utf-8") as f:\n        json.dump(rule_pool, f, ensure_ascii=False, indent=2)\n\n    print(f"[OK] Rule pool saved to: {output_json}")\n    print(f"Schema rules: {len(schema_rules)}")\n    print(f"FD rules: {len(fd_rules)}")\n    print(f"Soft FD rules: {len(soft_fd_rules)}")\n    print(f"Candidate generation rules: {len(candidate_rules)}")\n\n\nif __name__ == "__main__":\n    build_rule_pool(INPUT_CSV, OUTPUT_JSON)\n',
    'rayyan': 'import json\nimport math\nimport re\nfrom collections import Counter\nfrom itertools import combinations\nfrom typing import Dict, List, Any, Optional\n\nimport pandas as pd\n\nINPUT_CSV = "/mnt/mydata/dq/projects/Splittree/rayyan/rayyan_dirty.csv"\nOUTPUT_JSON = "rule_pool_rayyan.json"\n\nMISSING_TOKENS = {\n    "", "empty", "null", "none", "nan", "na", "n/a", "missing", "unk",\n    "not available", "contact airline"\n}\n\nNUMERIC_RATIO_THRESHOLD = 0.90\nENUM_UNIQUE_THRESHOLD = 50\nENUM_RATIO_THRESHOLD = 0.08\n\nID_LIKE_UNIQUE_RATIO_THRESHOLD = 0.98\nCODE_LIKE_AVG_LEN_THRESHOLD = 20\nCODE_LIKE_DOMINANT_PATTERN_THRESHOLD = 0.70\nDOMINANT_PATTERN_THRESHOLD = 0.70\nDOMINANT_TYPO_MIN_RATIO = 0.50\n\nMAX_LHS_SIZE = 2\nFD_CONFIDENCE_THRESHOLD = 0.98\nMIN_SUPPORT_ROWS = 5\n\nSOFT_FD_CONFIDENCE_THRESHOLD = 0.80\nSOFT_FD_MIN_GROUP_SIZE = 3\nPAIR_CONTEXT_MIN_RATIO = 0.70\nPAIR_CONTEXT_MIN_GROUP_SIZE = 2\n\nHIGH_CARDINALITY_RATIO_FOR_LHS = 0.95\nALLOW_INDEX_COLUMN = False\nSKIP_SCHEMA_FOR_ID_LIKE = True\n\nTARGET_CANDIDATE_COLUMNS = {\n    "article_language",\n    "journal_title",\n    "jounral_abbreviation",\n    "journal_issn",\n    "article_jvolumn",\n    "article_jissue",\n    "article_jcreated_at",\n    "article_pagination",\n    "author_list",\n}\nHIGH_RISK_MISSING_COLUMNS = {\n    "article_language",\n    "journal_title",\n    "jounral_abbreviation",\n    "journal_issn",\n    "article_jcreated_at",\n    "author_list",\n}\n\nENABLE_RARE_VALUE_RULE = True\nRARE_VALUE_MAX_FREQ = 2\nENABLE_RARE_PATTERN_RULE = True\nRARE_PATTERN_MAX_RATIO = 0.02\n\n# 更激进地限制容易制造误报的列\nSKIP_RARE_VALUE_COLUMNS = {\n    "article_title", "author_list", "journal_title",\n    "jounral_abbreviation", "article_pagination",\n    "article_jvolumn", "article_jissue", "article_language",\n    # 关键：article_jcreated_at 不再靠 rare_value 进候选，\n    # 这个列改由专门的日期错位规则负责召回\n    "article_jcreated_at",\n}\nSKIP_RARE_PATTERN_COLUMNS = {\n    "article_title", "author_list", "article_language", "journal_issn"\n}\nSKIP_GLOBAL_DOMINANT_COLUMNS = {\n    "article_title", "author_list", "journal_title",\n    "jounral_abbreviation", "article_pagination"\n}\n# 不对这些列加 generic dominant-pattern 规则，避免误报\nSKIP_GENERIC_PATTERN_COLUMNS = {"article_language", "journal_issn", "article_jissue", "article_jvolumn"}\n\nLANG_CANONICAL_MAP = {\n    "eng": "eng",\n    "english": "eng",\n    "english; abstract language:english": "eng",\n    "en": "eng",\n    "pol": "pol",\n    "polish": "pol",\n    "fre": "fre",\n    "french": "fre",\n    "ger": "ger",\n    "german": "ger",\n    "spa": "spa",\n    "spanish": "spa",\n}\n\nMOJIBAKE_CHARS = {"�", "��", "\\ufffd"}\n\n\ndef normalize_value(x):\n    if pd.isna(x):\n        return None\n    s = str(x).strip()\n    if s.lower() in MISSING_TOKENS:\n        return None\n    return s.lower()\n\n\ndef normalize_series(s):\n    return s.map(normalize_value)\n\n\ndef maybe_drop_unnamed_columns(df):\n    keep_cols = [c for c in df.columns if not str(c).lower().startswith("unnamed:")]\n    return df[keep_cols].copy()\n\n\ndef detect_basic_pattern(value):\n    if value is None:\n        return "NULL"\n    parts, prev_type, cnt = [], None, 0\n    for ch in value:\n        if ch.isdigit():\n            cur = "D"\n        elif ch.isalpha():\n            cur = "L"\n        elif ch in {" ", "-", "_", "/", ".", ",", "(", ")", "%", ":", ";", "&", "\'", "+", "[", "]", "{", "}", \'"\'}:\n            cur = "S"\n        else:\n            cur = "X"\n        if cur == prev_type:\n            cnt += 1\n        else:\n            if prev_type is not None:\n                parts.append(f"{prev_type}{cnt}")\n            prev_type = cur\n            cnt = 1\n    if prev_type is not None:\n        parts.append(f"{prev_type}{cnt}")\n    return "".join(parts)\n\n\ndef try_parse_numeric(series):\n    cleaned = series.dropna().astype(str).str.replace(",", "", regex=False).str.replace("%", "", regex=False)\n    numeric = pd.to_numeric(cleaned, errors="coerce")\n    success_ratio = numeric.notna().mean() if len(cleaned) > 0 else 0.0\n    return numeric, success_ratio\n\n\ndef shannon_entropy(series):\n    vals = series.dropna().tolist()\n    if not vals:\n        return 0.0\n    cnt = Counter(vals)\n    total = len(vals)\n    ent = 0.0\n    for c in cnt.values():\n        p = c / total\n        ent -= p * math.log2(p)\n    return ent\n\n\ndef value_frequency_dict(series, topk=20):\n    cnt = Counter(series.dropna().tolist())\n    total = sum(cnt.values()) if cnt else 0\n    out = []\n    for k, v in cnt.most_common(topk):\n        out.append({"value": k, "count": v, "ratio": round(v / total, 6) if total > 0 else 0.0})\n    return out\n\n\ndef canonicalize_language(s: Optional[str]) -> Optional[str]:\n    if s is None:\n        return None\n    return LANG_CANONICAL_MAP.get(str(s).strip().lower())\n\n\ndef extract_issn_digits(s: Optional[str]) -> Optional[str]:\n    if s is None:\n        return None\n    m = re.search(r\'(\\d{4})[- ]?(\\d{3}[\\dx])\', str(s).strip().lower())\n    if not m:\n        return None\n    return f"{m.group(1)}-{m.group(2)}"\n\n\ndef canonicalize_volume_issue(s: Optional[str]) -> Optional[str]:\n    if s is None:\n        return None\n    txt = str(s).strip().lower()\n    m = re.search(r\'(\\d+)\', txt)\n    if not m:\n        return None\n    return str(int(m.group(1)))\n\n\ndef normalize_date_like(s: Optional[str]) -> Optional[str]:\n    if s is None:\n        return None\n    txt = str(s).strip().lower()\n    txt = re.sub(r\'\\s+\', \'\', txt)\n\n    m = re.match(r\'^(\\d{1,2})/(\\d{1,2})/(\\d{2,4})$\', txt)\n    if m:\n        mm, dd, yy = int(m.group(1)), int(m.group(2)), m.group(3)\n        yy_i = int(yy)\n        if len(yy) == 2:\n            yy_i = 1900 + yy_i if yy_i >= 30 else 2000 + yy_i\n        if 1 <= mm <= 12 and 1 <= dd <= 31:\n            return f"{yy_i:04d}-{mm:02d}-{dd:02d}"\n\n    m = re.match(r\'^(\\d{4})-(\\d{1,2})-(\\d{1,2})$\', txt)\n    if m:\n        yy_i, mm, dd = int(m.group(1)), int(m.group(2)), int(m.group(3))\n        if 1 <= mm <= 12 and 1 <= dd <= 31:\n            return f"{yy_i:04d}-{mm:02d}-{dd:02d}"\n    return None\n\n\ndef split_date_components(s: Optional[str]):\n    if s is None:\n        return None\n    txt = str(s).strip().lower()\n    txt = re.sub(r\'\\s+\', \'\', txt)\n    m = re.match(r\'^(\\d{1,2})/(\\d{1,2})/(\\d{2,4})$\', txt)\n    if not m:\n        return None\n    a, b, c = m.group(1), m.group(2), m.group(3)\n    return int(a), int(b), c\n\n\ndef generate_date_permutations(s: Optional[str]):\n    """\n    保留原先较宽松的候选生成。\n    """\n    comp = split_date_components(s)\n    if comp is None:\n        return []\n    a, b, c = comp\n    perms = []\n    candidates = [\n        (1, 3, 2),  # m/y/d 近似映射后再规整\n        (2, 3, 1),  # d/y/m\n        (2, 1, 3),  # d/m/y\n    ]\n    arr = [str(a), str(b), str(c)]\n    for idxs in candidates:\n        mm_raw, dd_raw, yy_raw = arr[idxs[0] - 1], arr[idxs[1] - 1], arr[idxs[2] - 1]\n        try:\n            mm = int(mm_raw)\n            dd = int(dd_raw)\n            yy_i = int(yy_raw)\n        except Exception:\n            continue\n        if len(yy_raw) == 2:\n            yy_i = 1900 + yy_i if yy_i >= 30 else 2000 + yy_i\n        if 1 <= mm <= 12 and 1 <= dd <= 31:\n            perms.append(f"{yy_i:04d}-{mm:02d}-{dd:02d}")\n    return list(dict.fromkeys(perms))\n\n\ndef generate_ymd_swap_candidate(s: Optional[str]) -> Optional[str]:\n    """\n    专门针对当前 rayyan 中最常见的错位模式：\n    dirty 常表现为 YY/M/D 或 D/M/YY 混写成 a/b/c，\n    最终想恢复成更像 M/D/YY 的 clean 形式。\n\n    经验上，很多漏错像：\n    4/2/15 -> 2/15/04\n    1/1/13 -> 1/13/01\n    3/1/14 -> 1/14/03\n\n    因此这里重点尝试：\n      a/b/c  ->  b/c/a\n    然后再规范化成 yyyy-mm-dd。\n    """\n    comp = split_date_components(s)\n    if comp is None:\n        return None\n\n    a, b, c = comp\n    a_str = str(a)\n    b_str = str(b)\n    c_str = str(c)\n\n    try:\n        mm = int(b_str)\n        dd = int(c_str)\n        yy_i = int(a_str)\n    except Exception:\n        return None\n\n    if len(a_str) <= 2:\n        yy_i = 1900 + yy_i if yy_i >= 30 else 2000 + yy_i\n\n    if 1 <= mm <= 12 and 1 <= dd <= 31:\n        return f"{yy_i:04d}-{mm:02d}-{dd:02d}"\n    return None\n\n\ndef canonicalize_pagination(s: Optional[str]) -> Optional[str]:\n    if s is None:\n        return None\n    txt = str(s).strip().lower()\n    m = re.search(r\'(\\d+)\\s*-\\s*(\\d+)\', txt)\n    if m:\n        return f"{int(m.group(1))}-{int(m.group(2))}"\n    m = re.search(r\'(\\d+)\\s*-\\s*$\', txt)\n    if m:\n        return str(int(m.group(1)))\n    return None\n\n\ndef is_index_like_column(series):\n    s = series.dropna()\n    if len(s) == 0:\n        return False\n    numeric = pd.to_numeric(s, errors="coerce")\n    if numeric.notna().mean() < 0.95:\n        return False\n    unique_ratio = s.nunique() / len(s)\n    return unique_ratio > 0.98\n\n\ndef is_id_like_column(non_null, unique_ratio, numeric_ratio, avg_len):\n    if len(non_null) == 0:\n        return False\n    if unique_ratio >= ID_LIKE_UNIQUE_RATIO_THRESHOLD and avg_len <= CODE_LIKE_AVG_LEN_THRESHOLD:\n        return True\n    if unique_ratio >= ID_LIKE_UNIQUE_RATIO_THRESHOLD and numeric_ratio >= NUMERIC_RATIO_THRESHOLD:\n        return True\n    return False\n\n\ndef is_code_like_column(non_null, unique_ratio, numeric_ratio, avg_len, top_patterns):\n    if len(non_null) == 0:\n        return False\n    dominant_ratio = top_patterns[0]["ratio"] if top_patterns else 0.0\n    if avg_len <= CODE_LIKE_AVG_LEN_THRESHOLD and dominant_ratio >= CODE_LIKE_DOMINANT_PATTERN_THRESHOLD:\n        if unique_ratio > ENUM_RATIO_THRESHOLD:\n            return True\n    if numeric_ratio >= 0.95 and avg_len <= 15 and unique_ratio < ID_LIKE_UNIQUE_RATIO_THRESHOLD:\n        return True\n    return False\n\n\ndef calc_fd_confidence_and_support(df, lhs_cols, rhs_col):\n    sub = df[lhs_cols + [rhs_col]].dropna()\n    support = len(sub)\n    if support < MIN_SUPPORT_ROWS:\n        return 0.0, support\n    grouped = sub.groupby(lhs_cols, dropna=True)[rhs_col]\n    majority_sum = 0\n    for _, grp in grouped:\n        cnt = Counter(grp.tolist())\n        majority_sum += cnt.most_common(1)[0][1]\n    confidence = majority_sum / support if support > 0 else 0.0\n    return round(confidence, 6), int(support)\n\n\ndef calc_soft_fd_confidence_and_support(df, lhs_cols, rhs_col):\n    sub = df[lhs_cols + [rhs_col]].dropna()\n    support = len(sub)\n    if support < SOFT_FD_MIN_GROUP_SIZE:\n        return 0.0, support\n    grouped = sub.groupby(lhs_cols, dropna=True)[rhs_col]\n    majority_sum = 0\n    for _, grp in grouped:\n        if len(grp) < SOFT_FD_MIN_GROUP_SIZE:\n            continue\n        cnt = Counter(grp.tolist())\n        majority_sum += cnt.most_common(1)[0][1]\n    confidence = majority_sum / support if support > 0 else 0.0\n    return round(confidence, 6), int(support)\n\n\ndef calc_not_null_confidence_and_support(series):\n    total = len(series)\n    if total == 0:\n        return 0.0, 0\n    non_null = series.notna().sum()\n    return round(non_null / total, 6), int(total)\n\n\ndef calc_pattern_confidence_and_support(series, dominant_pattern):\n    non_null = series.dropna()\n    support = len(non_null)\n    if support == 0:\n        return 0.0, 0\n    pats = non_null.map(detect_basic_pattern)\n    ok = (pats == dominant_pattern).sum()\n    return round(ok / support, 6), int(support)\n\n\ndef build_date_value_distribution(series):\n    canon = series.dropna().map(normalize_date_like).dropna()\n    year_counter = Counter([x[:4] for x in canon if len(x) >= 4])\n    md_counter = Counter([x[5:] for x in canon if len(x) >= 10])\n    return {\n        "canonical_count": int(len(canon)),\n        "top_years": dict(year_counter.most_common(20)),\n        "top_month_day": dict(md_counter.most_common(50)),\n    }\n\n\ndef analyze_columns(df):\n    profiles = {}\n    n = len(df)\n    for col in df.columns:\n        s = normalize_series(df[col])\n        non_null = s.dropna()\n        missing_rate = 1.0 - (len(non_null) / n if n > 0 else 0.0)\n        unique_count = non_null.nunique()\n        unique_ratio = unique_count / len(non_null) if len(non_null) > 0 else 0.0\n        numeric_vals, numeric_ratio = try_parse_numeric(non_null)\n        patterns = non_null.map(detect_basic_pattern)\n        pattern_counter = Counter(patterns.tolist())\n        total_patterns = sum(pattern_counter.values())\n        top_patterns = [{"pattern": p, "count": c, "ratio": round(c / total_patterns, 6)} for p, c in pattern_counter.most_common(10)]\n        lengths = non_null.map(lambda x: len(str(x)))\n        avg_len = float(lengths.mean()) if len(lengths) > 0 else 0.0\n        profile = {\n            "column": col,\n            "missing_rate": round(missing_rate, 6),\n            "non_null_count": int(len(non_null)),\n            "unique_count": int(unique_count),\n            "unique_ratio": round(unique_ratio, 6),\n            "numeric_parse_ratio": round(float(numeric_ratio), 6),\n            "entropy": round(shannon_entropy(non_null), 6),\n            "detected_type": None,\n            "semantic_type": None,\n            "index_like": is_index_like_column(non_null),\n            "avg_length": round(avg_len, 6),\n            "top_values": value_frequency_dict(non_null, topk=20),\n            "top_patterns": top_patterns,\n            "value_counter": Counter(non_null.tolist()),\n        }\n        if col == "article_jcreated_at":\n            profile["date_distribution"] = build_date_value_distribution(non_null)\n        if numeric_ratio >= NUMERIC_RATIO_THRESHOLD:\n            profile["detected_type"] = "numeric"\n        else:\n            if unique_count <= ENUM_UNIQUE_THRESHOLD or unique_ratio <= ENUM_RATIO_THRESHOLD:\n                profile["detected_type"] = "categorical"\n            else:\n                profile["detected_type"] = "text"\n\n        if profile["index_like"]:\n            profile["semantic_type"] = "id_like"\n        elif is_id_like_column(non_null, unique_ratio, numeric_ratio, avg_len):\n            profile["semantic_type"] = "id_like"\n        elif is_code_like_column(non_null, unique_ratio, numeric_ratio, avg_len, top_patterns):\n            profile["semantic_type"] = "code_like"\n        elif profile["detected_type"] == "numeric":\n            profile["semantic_type"] = "numeric"\n        elif profile["detected_type"] == "categorical":\n            profile["semantic_type"] = "categorical"\n        else:\n            profile["semantic_type"] = "text"\n        profiles[col] = profile\n    return profiles\n\n\ndef build_schema_rules(df, profiles):\n    rules = []\n    rule_id = 1\n    for col, info in profiles.items():\n        if col not in TARGET_CANDIDATE_COLUMNS:\n            continue\n\n        series = normalize_series(df[col])\n\n        not_null_threshold = 0.55\n        if col in {"journal_title", "article_language", "article_jcreated_at", "author_list"}:\n            not_null_threshold = 0.70\n\n        if info["missing_rate"] <= not_null_threshold:\n            confidence, support = calc_not_null_confidence_and_support(series)\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "not_null",\n                "column": col,\n                "description": f"{col} should not be null",\n                "confidence": confidence,\n                "support": support,\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n        if len(info["top_patterns"]) > 0 and col not in SKIP_GENERIC_PATTERN_COLUMNS:\n            main_pattern = info["top_patterns"][0]\n            if main_pattern["ratio"] >= DOMINANT_PATTERN_THRESHOLD:\n                confidence, support = calc_pattern_confidence_and_support(series, main_pattern["pattern"])\n                rules.append({\n                    "rule_id": f"SCHEMA_{rule_id}",\n                    "rule_type": "pattern",\n                    "column": col,\n                    "description": f"{col} should mostly follow the dominant pattern",\n                    "pattern": main_pattern["pattern"],\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "strong_rule",\n                })\n                rule_id += 1\n\n        if col == "journal_issn":\n            for rtype, regex, conf in [\n                ("issn_format", r"^\\d{4}-\\d{3}[\\dx](\\s*\\(print\\))?$", 0.82),\n                ("issn_loose_format", r".*\\d{4}[- ]?\\d{3}[\\dx].*", 0.78),\n            ]:\n                rules.append({\n                    "rule_id": f"SCHEMA_{rule_id}",\n                    "rule_type": rtype,\n                    "column": col,\n                    "description": f"{col} regex check {rtype}",\n                    "regex": regex,\n                    "confidence": conf,\n                    "support": info["non_null_count"],\n                    "usage_role": "candidate_generation_rule",\n                })\n                rule_id += 1\n\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "issn_canonical_format",\n                "column": col,\n                "description": "journal_issn should usually use canonical xxxx-xxxx form",\n                "confidence": 0.90,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n        if col == "article_language":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "language_canonical_format",\n                "column": col,\n                "description": "article_language should use canonical short code (e.g., eng)",\n                "confidence": 0.88,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n        if col == "article_jcreated_at":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "date_like_format",\n                "column": col,\n                "description": "article_jcreated_at should usually be parseable as a date",\n                "confidence": 0.82,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n            # 保留原先较宽松的重排可疑规则\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "date_component_permutation_suspicious",\n                "column": col,\n                "description": "article_jcreated_at may have month/day/year component permutation",\n                "confidence": 0.86,\n                "support": info.get("date_distribution", {}).get("canonical_count", 0),\n                "usage_role": "candidate_generation_rule",\n                "date_distribution": info.get("date_distribution", {}),\n            })\n            rule_id += 1\n\n            # 新增：专门针对当前数据中最常见的 YY/M/D -> M/D/YY 错位模式\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "date_ymd_swap_suspicious",\n                "column": col,\n                "description": "article_jcreated_at may follow a strong YY/M/D -> M/D/YY swap pattern",\n                "confidence": 0.94,\n                "support": info.get("date_distribution", {}).get("canonical_count", 0),\n                "usage_role": "candidate_generation_rule",\n                "date_distribution": info.get("date_distribution", {}),\n            })\n            rule_id += 1\n\n        if col in {"article_jvolumn", "article_jissue"}:\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "volume_issue_numeric_format",\n                "column": col,\n                "description": f"{col} should usually be numeric-like",\n                "regex": r"^\\d+$",\n                "confidence": 0.82,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n        if col == "article_pagination":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "pagination_format",\n                "column": col,\n                "description": "article_pagination should usually look like page ranges such as 1187-9 or 43-49",\n                "regex": r"^(\\d+(-\\d+)?)(\\s+st\\s+-.*)?$",\n                "confidence": 0.75,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n        if col == "author_list":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "author_list_braced_format",\n                "column": col,\n                "description": "author_list should usually be a braced quoted list",\n                "regex": r\'^\\{.*\\}$\',\n                "confidence": 0.78,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "author_list_encoding_corruption",\n                "column": col,\n                "description": "author_list should not contain mojibake / replacement characters",\n                "confidence": 0.92,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n    return rules\n\n\ndef select_fd_lhs_candidates(profiles):\n    candidates = []\n    for col, info in profiles.items():\n        if (not ALLOW_INDEX_COLUMN) and info.get("index_like", False):\n            continue\n        if info["unique_ratio"] >= HIGH_CARDINALITY_RATIO_FOR_LHS:\n            continue\n        candidates.append(col)\n    return candidates\n\n\ndef build_fd_rules(df, profiles):\n    rules = []\n    rule_id = 1\n    cols = list(df.columns)\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in cols})\n\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n    rhs_candidates = [c for c in TARGET_CANDIDATE_COLUMNS if c in cols]\n\n    lhs_sets = []\n    for k in range(1, MAX_LHS_SIZE + 1):\n        lhs_sets.extend(list(combinations(lhs_candidates, k)))\n\n    for lhs in lhs_sets:\n        for rhs in rhs_candidates:\n            if rhs in lhs:\n                continue\n            confidence, support = calc_fd_confidence_and_support(norm_df, list(lhs), rhs)\n            if support < MIN_SUPPORT_ROWS:\n                continue\n            if confidence >= FD_CONFIDENCE_THRESHOLD:\n                rules.append({\n                    "rule_id": f"FD_{rule_id}",\n                    "rule_type": "functional_dependency",\n                    "lhs": list(lhs),\n                    "rhs": rhs,\n                    "description": f"{\', \'.join(lhs)} -> {rhs}",\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "strong_rule",\n                })\n                rule_id += 1\n\n    dedup = {(tuple(sorted(r["lhs"])), r["rhs"]): r for r in rules}\n    return list(dedup.values())\n\n\ndef build_soft_fd_rules(df, profiles):\n    rules = []\n    rule_id = 1\n    cols = list(df.columns)\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in cols})\n\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n    rhs_candidates = [c for c in TARGET_CANDIDATE_COLUMNS if c in cols]\n\n    lhs_sets = []\n    for k in range(1, MAX_LHS_SIZE + 1):\n        lhs_sets.extend(list(combinations(lhs_candidates, k)))\n\n    for lhs in lhs_sets:\n        for rhs in rhs_candidates:\n            if rhs in lhs:\n                continue\n            confidence, support = calc_soft_fd_confidence_and_support(norm_df, list(lhs), rhs)\n            if support < SOFT_FD_MIN_GROUP_SIZE:\n                continue\n            if SOFT_FD_CONFIDENCE_THRESHOLD <= confidence < FD_CONFIDENCE_THRESHOLD:\n                rules.append({\n                    "rule_id": f"CAND_SOFTFD_{rule_id}",\n                    "rule_type": "soft_functional_dependency",\n                    "lhs": list(lhs),\n                    "rhs": rhs,\n                    "description": f"soft FD: {\', \'.join(lhs)} -> {rhs}",\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "candidate_generation_rule",\n                })\n                rule_id += 1\n    return rules\n\n\ndef build_pair_context_rules(df):\n    rules = []\n    rule_id = 1\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in df.columns})\n\n    pair_specs = [\n        (["journal_title"], "jounral_abbreviation"),\n        (["jounral_abbreviation"], "journal_title"),\n        (["journal_title"], "journal_issn"),\n        (["journal_issn"], "journal_title"),\n        (["journal_issn"], "jounral_abbreviation"),\n        (["journal_title", "journal_issn"], "jounral_abbreviation"),\n        (["journal_title", "jounral_abbreviation"], "journal_issn"),\n    ]\n\n    for lhs, rhs in pair_specs:\n        if any(c not in norm_df.columns for c in lhs + [rhs]):\n            continue\n        sub = norm_df[lhs + [rhs]].dropna()\n        if len(sub) < PAIR_CONTEXT_MIN_GROUP_SIZE:\n            continue\n        grouped = sub.groupby(lhs, dropna=True)[rhs]\n        majority_map = {}\n        total_support = 0\n        for key, grp in grouped:\n            if len(grp) < PAIR_CONTEXT_MIN_GROUP_SIZE:\n                continue\n            cnt = Counter(grp.tolist())\n            maj_val, maj_cnt = cnt.most_common(1)[0]\n            ratio = maj_cnt / len(grp)\n            if ratio >= PAIR_CONTEXT_MIN_RATIO:\n                if not isinstance(key, tuple):\n                    key = (key,)\n                majority_map["||".join(map(str, key))] = {\n                    "dominant_value": maj_val,\n                    "group_size": len(grp),\n                    "ratio": round(ratio, 6)\n                }\n                total_support += len(grp)\n        if majority_map:\n            rules.append({\n                "rule_id": f"CAND_PAIRCTX_{rule_id}",\n                "rule_type": "dominant_value_by_context_pair" if len(lhs) == 2 else "dominant_value_by_context",\n                "lhs": lhs,\n                "rhs": rhs,\n                "description": f"context dominant: {\', \'.join(lhs)} -> {rhs}",\n                "mapping_size": len(majority_map),\n                "majority_map": majority_map,\n                "confidence": 0.84,\n                "support": total_support,\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n    return rules\n\n\ndef build_candidate_generation_rules(df, profiles):\n    rules = []\n    rule_id = 1\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in df.columns})\n\n    for col, prof in profiles.items():\n        if col not in TARGET_CANDIDATE_COLUMNS or col in SKIP_GLOBAL_DOMINANT_COLUMNS:\n            continue\n        top_values = prof.get("top_values", [])\n        if not top_values:\n            continue\n        top1 = top_values[0]\n        if top1["ratio"] >= DOMINANT_TYPO_MIN_RATIO:\n            rules.append({\n                "rule_id": f"CAND_GDOM_{rule_id}",\n                "rule_type": "global_dominant_value",\n                "column": col,\n                "description": f"global dominant value for {col}",\n                "dominant_value": top1["value"],\n                "dominant_count": top1["count"],\n                "dominant_ratio": top1["ratio"],\n                "confidence": round(top1["ratio"], 6),\n                "support": prof["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n    context_rule_id = 1\n    for rhs in TARGET_CANDIDATE_COLUMNS:\n        if rhs not in df.columns:\n            continue\n        for lhs in lhs_candidates:\n            if lhs == rhs:\n                continue\n            sub = norm_df[[lhs, rhs]].dropna()\n            if len(sub) < SOFT_FD_MIN_GROUP_SIZE:\n                continue\n            grouped = sub.groupby(lhs)[rhs]\n            majority_map = {}\n            total_support = 0\n            for lhs_val, grp in grouped:\n                if len(grp) < SOFT_FD_MIN_GROUP_SIZE:\n                    continue\n                cnt = Counter(grp.tolist())\n                maj_val, maj_cnt = cnt.most_common(1)[0]\n                ratio = maj_cnt / len(grp)\n                if ratio >= SOFT_FD_CONFIDENCE_THRESHOLD:\n                    majority_map[lhs_val] = {\n                        "dominant_value": maj_val,\n                        "group_size": len(grp),\n                        "ratio": round(ratio, 6)\n                    }\n                    total_support += len(grp)\n            if majority_map:\n                rules.append({\n                    "rule_id": f"CAND_CTXDOM_{context_rule_id}",\n                    "rule_type": "dominant_value_by_context",\n                    "lhs": [lhs],\n                    "rhs": rhs,\n                    "description": f"context dominant: {lhs} -> dominant {rhs}",\n                    "mapping_size": len(majority_map),\n                    "majority_map": majority_map,\n                    "confidence": 0.85,\n                    "support": total_support,\n                    "usage_role": "candidate_generation_rule",\n                })\n                context_rule_id += 1\n\n    if ENABLE_RARE_VALUE_RULE:\n        for col, prof in profiles.items():\n            if col not in TARGET_CANDIDATE_COLUMNS or col in SKIP_RARE_VALUE_COLUMNS:\n                continue\n            counter = prof["value_counter"]\n            rare_values = [v for v, c in counter.items() if c <= RARE_VALUE_MAX_FREQ]\n            if rare_values:\n                rules.append({\n                    "rule_id": f"CAND_RAREVAL_{rule_id}",\n                    "rule_type": "rare_value",\n                    "column": col,\n                    "description": f"rare values in {col} may be suspicious",\n                    "rare_values": rare_values[:5000],\n                    "confidence": 0.6,\n                    "support": sum(counter[v] for v in rare_values),\n                    "usage_role": "candidate_generation_rule",\n                })\n                rule_id += 1\n\n    if ENABLE_RARE_PATTERN_RULE:\n        for col, prof in profiles.items():\n            if col not in TARGET_CANDIDATE_COLUMNS or col in SKIP_RARE_PATTERN_COLUMNS:\n                continue\n            top_patterns = prof.get("top_patterns", [])\n            rare_patterns = [x["pattern"] for x in top_patterns if x["ratio"] <= RARE_PATTERN_MAX_RATIO]\n            if rare_patterns:\n                rules.append({\n                    "rule_id": f"CAND_RAREPAT_{rule_id}",\n                    "rule_type": "rare_pattern",\n                    "column": col,\n                    "description": f"rare patterns in {col} may be suspicious",\n                    "rare_patterns": rare_patterns,\n                    "confidence": 0.6,\n                    "support": prof["non_null_count"],\n                    "usage_role": "candidate_generation_rule",\n                })\n                rule_id += 1\n\n    for col in HIGH_RISK_MISSING_COLUMNS:\n        if col not in profiles:\n            continue\n        prof = profiles[col]\n        rules.append({\n            "rule_id": f"CAND_HRMISS_{rule_id}",\n            "rule_type": "high_risk_missing",\n            "column": col,\n            "description": f"{col} missing values are suspicious in candidate generation",\n            "confidence": 0.8,\n            "support": prof["non_null_count"],\n            "usage_role": "candidate_generation_rule",\n        })\n        rule_id += 1\n\n    for a, b in [\n        ("journal_title", "jounral_abbreviation"),\n        ("journal_title", "journal_issn"),\n        ("article_jvolumn", "article_jissue"),\n    ]:\n        if a in df.columns and b in df.columns:\n            rules.append({\n                "rule_id": f"CAND_PAIR_{rule_id}",\n                "rule_type": "paired_missing_consistency",\n                "columns": [a, b],\n                "description": f"{a} and {b} should usually co-occur",\n                "confidence": 0.8,\n                "support": len(df),\n                "usage_role": "candidate_generation_rule",\n            })\n            rule_id += 1\n\n    rules.extend(build_pair_context_rules(df))\n    return rules\n\n\ndef assign_rule_priority(rule):\n    rtype = rule.get("rule_type")\n    if rtype in {\n        "date_component_permutation_suspicious",\n        "date_ymd_swap_suspicious",\n        "author_list_encoding_corruption",\n    }:\n        return "medium"\n\n    if rule.get("usage_role", "candidate_generation_rule") == "candidate_generation_rule":\n        if rule.get("confidence", 0.0) >= 0.85 and rule.get("support", 0) >= 20:\n            return "medium"\n        return "low"\n    return "medium"\n\n\ndef enrich_rules_with_priority(rule_groups):\n    new_groups = {}\n    for group_name, rules in rule_groups.items():\n        enriched = []\n        for r in rules:\n            r2 = dict(r)\n            r2["priority"] = assign_rule_priority(r2)\n            enriched.append(r2)\n        new_groups[group_name] = enriched\n    return new_groups\n\n\ndef build_rule_pool(input_csv, output_json):\n    df = pd.read_csv(input_csv, dtype=str)\n    df = maybe_drop_unnamed_columns(df)\n    for col in df.columns:\n        df[col] = normalize_series(df[col])\n\n    profiles = analyze_columns(df)\n    schema_rules = build_schema_rules(df, profiles)\n    fd_rules = build_fd_rules(df, profiles)\n    soft_fd_rules = build_soft_fd_rules(df, profiles)\n    candidate_rules = build_candidate_generation_rules(df, profiles)\n\n    rule_groups = {\n        "schema_rules": schema_rules,\n        "fd_rules": fd_rules,\n        "soft_fd_rules": soft_fd_rules,\n        "candidate_rules": candidate_rules\n    }\n    rule_groups = enrich_rules_with_priority(rule_groups)\n\n    rule_pool = {\n        "metadata": {\n            "source_file": input_csv,\n            "row_count": int(len(df)),\n            "column_count": int(len(df.columns)),\n            "design_goal": "high_recall_candidate_generation",\n            "notes": [\n                "candidate inclusion is determined only by violating rules in this pool",\n                "candidate targets focus on bibliographic metadata fields; index/id mainly serve as context",\n                "recall is boosted mainly by journal consistency rules, date-permutation suspicion, date YY/M/D swap suspicion, author-list encoding corruption, and paired metadata rules",\n                "article_jcreated_at no longer relies on rare_value; dedicated date swap rules are used instead",\n                "rare_value and generic pattern are weakened on long-tail bibliographic fields to reduce false positives",\n            ],\n        },\n        "column_profiles": profiles,\n        "rules": rule_groups,\n    }\n\n    with open(output_json, "w", encoding="utf-8") as f:\n        json.dump(rule_pool, f, ensure_ascii=False, indent=2)\n\n    print(f"[OK] Rule pool saved to: {output_json}")\n    print(f"Schema rules: {len(schema_rules)}")\n    print(f"FD rules: {len(fd_rules)}")\n    print(f"Soft FD rules: {len(soft_fd_rules)}")\n    print(f"Candidate generation rules: {len(candidate_rules)}")\n\n\nif __name__ == "__main__":\n    build_rule_pool(INPUT_CSV, OUTPUT_JSON)\n',
    'adult': 'import json\nimport math\nimport re\nfrom collections import Counter\nfrom itertools import combinations\nfrom typing import Dict, List, Any, Optional, Tuple\n\nimport pandas as pd\n\n\n# ============================================================\n# 1. 用户配置区\n# ============================================================\n\nINPUT_CSV = "/mnt/mydata/dq/projects/Splittree/adult/adult_dirty.csv"\nOUTPUT_JSON = "rule_pool_adult.json"\n\nMISSING_TOKENS = {\n    "", "empty", "null", "none", "nan", "na", "n/a", "missing", "unk",\n    "unknown", "?", "not available", "contact airline"\n}\n\nNUMERIC_RATIO_THRESHOLD = 0.90\nENUM_UNIQUE_THRESHOLD = 80\nENUM_RATIO_THRESHOLD = 0.10\n\nID_LIKE_UNIQUE_RATIO_THRESHOLD = 0.98\nCODE_LIKE_AVG_LEN_THRESHOLD = 20\nCODE_LIKE_DOMINANT_PATTERN_THRESHOLD = 0.70\nDOMINANT_PATTERN_THRESHOLD = 0.70\nDOMINANT_TYPO_MIN_RATIO = 0.50\n\nMAX_LHS_SIZE = 2\nFD_CONFIDENCE_THRESHOLD = 0.98\nMIN_SUPPORT_ROWS = 5\n\nSOFT_FD_CONFIDENCE_THRESHOLD = 0.80\nSOFT_FD_MIN_GROUP_SIZE = 3\nPAIR_CONTEXT_MIN_RATIO = 0.70\nPAIR_CONTEXT_MIN_GROUP_SIZE = 2\n\nHIGH_CARDINALITY_RATIO_FOR_LHS = 0.95\nALLOW_INDEX_COLUMN = False\nSKIP_SCHEMA_FOR_ID_LIKE = True\n\n# ------------------------------------------------------------\n# adult 数据集字段\n# ------------------------------------------------------------\nADULT_COLUMNS = [\n    "age",\n    "workclass",\n    "education",\n    "maritalstatus",\n    "occupation",\n    "relationship",\n    "race",\n    "sex",\n    "hoursperweek",\n    "country",\n    "income",\n]\n\n# ------------------------------------------------------------\n# Adult v2 候选生成策略\n# ------------------------------------------------------------\n# 当前评估显示真实错误主要集中在 sex / relationship / 少量 education。\n# 因此：\n# 1) PRIMARY_TARGET_COLUMNS 是主要被检测列；\n# 2) CONTEXT_ONLY_COLUMNS 主要作为上下文证据，不再由 rare/global/context-dominant 等弱规则大规模进入候选；\n# 3) context-only 列只有 domain / format 这类强规则触发时才建议进入候选。\nPRIMARY_TARGET_COLUMNS = {\n    "sex",\n    "relationship",\n    "education",\n}\n\nCONTEXT_ONLY_COLUMNS = {\n    "age",\n    "workclass",\n    "maritalstatus",\n    "occupation",\n    "race",\n    "hoursperweek",\n    "country",\n    "income",\n}\n\nSCHEMA_RULE_COLUMNS = set(ADULT_COLUMNS)\nTARGET_CANDIDATE_COLUMNS = set(PRIMARY_TARGET_COLUMNS)\nHIGH_RISK_MISSING_COLUMNS = set(PRIMARY_TARGET_COLUMNS)\n\nRELATIONSHIP_SPOUSE_VALUES = {"Husband", "Wife"}\nNON_MARRIED_STATUS_FOR_SPOUSE = {"Never-married", "Divorced", "Separated", "Widowed"}\n\n# 只为 relationship 生成少量高价值上下文 dominant 规则，不再全列泛化。\nRELATIONSHIP_CONTEXT_LHS_SPECS = [\n    ["age", "maritalstatus", "sex"],\n    ["education", "maritalstatus", "sex"],\n    ["workclass", "maritalstatus", "sex"],\n    ["age", "education", "maritalstatus"],\n]\nRELATIONSHIP_CONTEXT_MIN_GROUP_SIZE = 20\nRELATIONSHIP_CONTEXT_MIN_RATIO = 0.75\nRELATIONSHIP_CONTEXT_TRIGGER_VALUES = sorted(list(RELATIONSHIP_SPOUSE_VALUES))\n\n# 普通弱规则整体关闭/强跳过，避免 age/income/race/country/workclass 等正常值被海量打入候选。\nENABLE_RARE_VALUE_RULE = False\nRARE_VALUE_MAX_FREQ = 2\nSKIP_RARE_VALUE_COLUMNS = set(ADULT_COLUMNS)\n\nENABLE_RARE_PATTERN_RULE = False\nRARE_PATTERN_MAX_RATIO = 0.02\nSKIP_RARE_PATTERN_COLUMNS = set(ADULT_COLUMNS)\n\n# 全部关闭 global dominant：Adult 中 Private / United-States / LessThan50K / Male 等多数类会制造大量 FP。\nSKIP_GLOBAL_DOMINANT_COLUMNS = set(ADULT_COLUMNS)\n\n# 不对这些列加 generic pattern 规则，改用专门 schema/domain/range 规则。\nSKIP_GENERIC_PATTERN_COLUMNS = set(ADULT_COLUMNS)\n\n# FD/soft-FD 只允许指向 primary target，避免把 age/income/race/country 等上下文列打成候选。\nFD_RHS_CANDIDATE_COLUMNS = set(PRIMARY_TARGET_COLUMNS)\nEXTRA_SKIP_FD_LHS_COLUMNS = set()\n\n# ------------------------------------------------------------\n# Adult 专属 domain\n# ------------------------------------------------------------\nVALID_AGE_BUCKETS = {\n    "<18", "18-21", "22-25", "26-30", "31-35", "36-40", "41-45",\n    "46-50", "51-55", "56-60", "61-65", "66-70", ">70"\n}\n\nVALID_WORKCLASS = {\n    "Private", "Self-emp-not-inc", "Self-emp-inc", "Federal-gov",\n    "Local-gov", "State-gov", "Without-pay", "Never-worked"\n}\n\nVALID_EDUCATION = {\n    "Preschool", "1st-4th", "5th-6th", "7th-8th", "9th", "10th",\n    "11th", "12th", "HS-grad", "Some-college", "Assoc-voc",\n    "Assoc-acdm", "Bachelors", "Masters", "Prof-school", "Doctorate"\n}\n\nVALID_MARITALSTATUS = {\n    "Married-civ-spouse", "Divorced", "Never-married", "Separated",\n    "Widowed", "Married-spouse-absent", "Married-AF-spouse"\n}\n\nVALID_OCCUPATION = {\n    "Tech-support", "Craft-repair", "Other-service", "Sales",\n    "Exec-managerial", "Prof-specialty", "Handlers-cleaners",\n    "Machine-op-inspct", "Adm-clerical", "Farming-fishing",\n    "Transport-moving", "Priv-house-serv", "Protective-serv",\n    "Armed-Forces"\n}\n\nVALID_RELATIONSHIP = {\n    "Wife", "Own-child", "Husband", "Not-in-family",\n    "Other-relative", "Unmarried"\n}\n\nVALID_RACE = {\n    "White", "Black", "Asian-Pac-Islander", "Amer-Indian-Eskimo", "Other"\n}\n\nVALID_SEX = {"Male", "Female"}\n\nVALID_INCOME = {"LessThan50K", "MoreThan50K", "<=50K", ">50K", "<50K", ">=50K"}\n\nVALID_COUNTRY = {\n    "United-States", "Cambodia", "England", "Puerto-Rico", "Canada",\n    "Germany", "Outlying-US(Guam-USVI-etc)", "India", "Japan",\n    "Greece", "South", "China", "Cuba", "Iran", "Honduras",\n    "Philippines", "Italy", "Poland", "Jamaica", "Vietnam",\n    "Mexico", "Portugal", "Ireland", "France", "Dominican-Republic",\n    "Laos", "Ecuador", "Taiwan", "Haiti", "Columbia", "Hungary",\n    "Guatemala", "Nicaragua", "Scotland", "Thailand", "Yugoslavia",\n    "El-Salvador", "Trinadad&Tobago", "Peru", "Hong", "Holand-Netherlands"\n}\n\nEDUCATION_ORDER = {\n    "Preschool": 0,\n    "1st-4th": 1,\n    "5th-6th": 2,\n    "7th-8th": 3,\n    "9th": 4,\n    "10th": 5,\n    "11th": 6,\n    "12th": 7,\n    "HS-grad": 8,\n    "Some-college": 9,\n    "Assoc-voc": 10,\n    "Assoc-acdm": 10,\n    "Bachelors": 11,\n    "Masters": 12,\n    "Prof-school": 13,\n    "Doctorate": 14,\n}\n\n\n# ============================================================\n# 2. 基础函数\n# ============================================================\n\ndef normalize_value(x):\n    if pd.isna(x):\n        return None\n    s = str(x).strip()\n    if s.lower() in MISSING_TOKENS:\n        return None\n    return s\n\n\ndef normalize_series(s):\n    return s.map(normalize_value)\n\n\ndef maybe_drop_unnamed_columns(df):\n    keep_cols = [c for c in df.columns if not str(c).lower().startswith("unnamed:")]\n    return df[keep_cols].copy()\n\n\ndef detect_basic_pattern(value):\n    if value is None:\n        return "NULL"\n    parts, prev_type, cnt = [], None, 0\n    for ch in str(value):\n        if ch.isdigit():\n            cur = "D"\n        elif ch.isalpha():\n            cur = "L"\n        elif ch in {" ", "-", "_", "/", ".", ",", "(", ")", "%", ":", ";", "&", "\'", "+", "<", ">"}:\n            cur = "S"\n        else:\n            cur = "X"\n        if cur == prev_type:\n            cnt += 1\n        else:\n            if prev_type is not None:\n                parts.append(f"{prev_type}{cnt}")\n            prev_type = cur\n            cnt = 1\n    if prev_type is not None:\n        parts.append(f"{prev_type}{cnt}")\n    return "".join(parts)\n\n\ndef try_parse_numeric(series):\n    cleaned = series.dropna().astype(str).str.replace(",", "", regex=False).str.replace("%", "", regex=False)\n    numeric = pd.to_numeric(cleaned, errors="coerce")\n    success_ratio = numeric.notna().mean() if len(cleaned) > 0 else 0.0\n    return numeric, success_ratio\n\n\ndef parse_int_like(x: Optional[str]) -> Optional[int]:\n    if x is None:\n        return None\n    s = str(x).strip().replace(",", "")\n    if re.fullmatch(r"[+-]?\\d+(\\.0+)?", s):\n        try:\n            return int(float(s))\n        except Exception:\n            return None\n    return None\n\n\ndef parse_age_bucket(value: Optional[str]) -> Tuple[Optional[int], Optional[int]]:\n    if value is None:\n        return None, None\n    s = str(value).strip()\n    m = re.fullmatch(r"<\\s*(\\d+)", s)\n    if m:\n        return 0, int(m.group(1)) - 1\n    m = re.fullmatch(r">\\s*(\\d+)", s)\n    if m:\n        return int(m.group(1)) + 1, None\n    m = re.fullmatch(r"(\\d+)\\s*-\\s*(\\d+)", s)\n    if m:\n        a, b = int(m.group(1)), int(m.group(2))\n        return min(a, b), max(a, b)\n    n = parse_int_like(s)\n    if n is not None:\n        return n, n\n    return None, None\n\n\ndef parse_hours_value(value: Optional[str]) -> Tuple[Optional[float], Optional[float]]:\n    if value is None:\n        return None, None\n    s = str(value).strip()\n    m = re.fullmatch(r"(\\d+)\\s*-\\s*(\\d+)", s)\n    if m:\n        a, b = float(m.group(1)), float(m.group(2))\n        return min(a, b), max(a, b)\n    n = parse_int_like(s)\n    if n is not None:\n        return float(n), float(n)\n    return None, None\n\n\ndef canonical_income(value: Optional[str]) -> Optional[str]:\n    if value is None:\n        return None\n    s = str(value).strip()\n    if s in {"LessThan50K", "<=50K", "<50K"}:\n        return "LessThan50K"\n    if s in {"MoreThan50K", ">50K", ">=50K"}:\n        return "MoreThan50K"\n    return None\n\n\ndef shannon_entropy(series):\n    vals = series.dropna().tolist()\n    if not vals:\n        return 0.0\n    cnt = Counter(vals)\n    total = len(vals)\n    ent = 0.0\n    for c in cnt.values():\n        p = c / total\n        ent -= p * math.log2(p)\n    return ent\n\n\ndef value_frequency_dict(series, topk=20):\n    cnt = Counter(series.dropna().tolist())\n    total = sum(cnt.values()) if cnt else 0\n    out = []\n    for k, v in cnt.most_common(topk):\n        out.append({"value": k, "count": v, "ratio": round(v / total, 6) if total > 0 else 0.0})\n    return out\n\n\ndef is_index_like_column(series):\n    s = series.dropna()\n    if len(s) == 0:\n        return False\n    numeric = pd.to_numeric(s, errors="coerce")\n    if numeric.notna().mean() < 0.95:\n        return False\n    unique_ratio = s.nunique() / len(s)\n    return unique_ratio > 0.98\n\n\ndef is_id_like_column(non_null, unique_ratio, numeric_ratio, avg_len):\n    if len(non_null) == 0:\n        return False\n    if unique_ratio >= ID_LIKE_UNIQUE_RATIO_THRESHOLD and avg_len <= CODE_LIKE_AVG_LEN_THRESHOLD:\n        return True\n    if unique_ratio >= ID_LIKE_UNIQUE_RATIO_THRESHOLD and numeric_ratio >= NUMERIC_RATIO_THRESHOLD:\n        return True\n    return False\n\n\ndef is_code_like_column(non_null, unique_ratio, numeric_ratio, avg_len, top_patterns):\n    if len(non_null) == 0:\n        return False\n    dominant_ratio = top_patterns[0]["ratio"] if top_patterns else 0.0\n    if avg_len <= CODE_LIKE_AVG_LEN_THRESHOLD and dominant_ratio >= CODE_LIKE_DOMINANT_PATTERN_THRESHOLD:\n        if unique_ratio > ENUM_RATIO_THRESHOLD:\n            return True\n    if numeric_ratio >= 0.95 and avg_len <= 15 and unique_ratio < ID_LIKE_UNIQUE_RATIO_THRESHOLD:\n        return True\n    return False\n\n\n# ============================================================\n# 3. 规则统计函数\n# ============================================================\n\ndef calc_fd_confidence_and_support(df, lhs_cols, rhs_col):\n    sub = df[lhs_cols + [rhs_col]].dropna()\n    support = len(sub)\n    if support < MIN_SUPPORT_ROWS:\n        return 0.0, support\n    grouped = sub.groupby(lhs_cols, dropna=True)[rhs_col]\n    majority_sum = 0\n    for _, grp in grouped:\n        cnt = Counter(grp.tolist())\n        majority_sum += cnt.most_common(1)[0][1]\n    confidence = majority_sum / support if support > 0 else 0.0\n    return round(confidence, 6), int(support)\n\n\ndef calc_soft_fd_confidence_and_support(df, lhs_cols, rhs_col):\n    sub = df[lhs_cols + [rhs_col]].dropna()\n    support = len(sub)\n    if support < SOFT_FD_MIN_GROUP_SIZE:\n        return 0.0, support\n    grouped = sub.groupby(lhs_cols, dropna=True)[rhs_col]\n    majority_sum = 0\n    used_support = 0\n    for _, grp in grouped:\n        if len(grp) < SOFT_FD_MIN_GROUP_SIZE:\n            continue\n        cnt = Counter(grp.tolist())\n        majority_sum += cnt.most_common(1)[0][1]\n        used_support += len(grp)\n    confidence = majority_sum / used_support if used_support > 0 else 0.0\n    return round(confidence, 6), int(used_support)\n\n\ndef calc_not_null_confidence_and_support(series):\n    total = len(series)\n    if total == 0:\n        return 0.0, 0\n    non_null = series.notna().sum()\n    return round(non_null / total, 6), int(total)\n\n\ndef calc_pattern_confidence_and_support(series, dominant_pattern):\n    non_null = series.dropna()\n    support = len(non_null)\n    if support == 0:\n        return 0.0, 0\n    pats = non_null.map(detect_basic_pattern)\n    ok = (pats == dominant_pattern).sum()\n    return round(ok / support, 6), int(support)\n\n\n# ============================================================\n# 4. 列画像\n# ============================================================\n\ndef analyze_columns(df):\n    profiles = {}\n    n = len(df)\n\n    for col in df.columns:\n        s = normalize_series(df[col])\n        non_null = s.dropna()\n        missing_rate = 1.0 - (len(non_null) / n if n > 0 else 0.0)\n        unique_count = non_null.nunique()\n        unique_ratio = unique_count / len(non_null) if len(non_null) > 0 else 0.0\n        numeric_vals, numeric_ratio = try_parse_numeric(non_null)\n\n        patterns = non_null.map(detect_basic_pattern)\n        pattern_counter = Counter(patterns.tolist())\n        total_patterns = sum(pattern_counter.values())\n        top_patterns = [\n            {"pattern": p, "count": c, "ratio": round(c / total_patterns, 6)}\n            for p, c in pattern_counter.most_common(10)\n        ]\n\n        lengths = non_null.map(lambda x: len(str(x)))\n        avg_len = float(lengths.mean()) if len(lengths) > 0 else 0.0\n\n        profile = {\n            "column": col,\n            "missing_rate": round(missing_rate, 6),\n            "non_null_count": int(len(non_null)),\n            "unique_count": int(unique_count),\n            "unique_ratio": round(unique_ratio, 6),\n            "numeric_parse_ratio": round(float(numeric_ratio), 6),\n            "entropy": round(shannon_entropy(non_null), 6),\n            "detected_type": None,\n            "semantic_type": None,\n            "index_like": is_index_like_column(non_null),\n            "avg_length": round(avg_len, 6),\n            "top_values": value_frequency_dict(non_null, topk=20),\n            "top_patterns": top_patterns,\n            "value_counter": Counter(non_null.tolist()),\n        }\n\n        if col == "age":\n            profile["detected_type"] = "categorical"\n            profile["semantic_type"] = "age_bucket"\n        elif col == "hoursperweek":\n            profile["detected_type"] = "numeric_or_range"\n            profile["semantic_type"] = "hours_range"\n        elif col in {\n            "workclass", "education", "maritalstatus", "occupation", "relationship",\n            "race", "sex", "country", "income"\n        }:\n            profile["detected_type"] = "categorical"\n            profile["semantic_type"] = f"{col}_category"\n        elif numeric_ratio >= NUMERIC_RATIO_THRESHOLD:\n            profile["detected_type"] = "numeric"\n            profile["semantic_type"] = "numeric"\n        else:\n            if unique_count <= ENUM_UNIQUE_THRESHOLD or unique_ratio <= ENUM_RATIO_THRESHOLD:\n                profile["detected_type"] = "categorical"\n            else:\n                profile["detected_type"] = "text"\n\n            if profile["index_like"]:\n                profile["semantic_type"] = "id_like"\n            elif is_id_like_column(non_null, unique_ratio, numeric_ratio, avg_len):\n                profile["semantic_type"] = "id_like"\n            elif is_code_like_column(non_null, unique_ratio, numeric_ratio, avg_len, top_patterns):\n                profile["semantic_type"] = "code_like"\n            elif profile["detected_type"] == "numeric":\n                profile["semantic_type"] = "numeric"\n            elif profile["detected_type"] == "categorical":\n                profile["semantic_type"] = "categorical"\n            else:\n                profile["semantic_type"] = "text"\n\n        profiles[col] = profile\n\n    return profiles\n\n\n# ============================================================\n# 5. schema/domain rules\n# ============================================================\n\ndef build_schema_rules(df, profiles):\n    rules = []\n    rule_id = 1\n\n    domain_specs = {\n        "workclass": VALID_WORKCLASS,\n        "education": VALID_EDUCATION,\n        "maritalstatus": VALID_MARITALSTATUS,\n        "occupation": VALID_OCCUPATION,\n        "relationship": VALID_RELATIONSHIP,\n        "race": VALID_RACE,\n        "sex": VALID_SEX,\n        "country": VALID_COUNTRY,\n        "income": VALID_INCOME,\n    }\n\n    for col, info in profiles.items():\n        if col not in SCHEMA_RULE_COLUMNS:\n            continue\n\n        series = normalize_series(df[col])\n\n        # 只对 primary target 使用 not_null 候选规则，避免上下文列缺失造成海量 FP。\n        if col in HIGH_RISK_MISSING_COLUMNS:\n            not_null_threshold = 0.80\n            if col in {"sex", "relationship"}:\n                not_null_threshold = 0.90\n\n            if info["missing_rate"] <= not_null_threshold:\n                confidence, support = calc_not_null_confidence_and_support(series)\n                rules.append({\n                    "rule_id": f"SCHEMA_{rule_id}",\n                    "rule_type": "not_null",\n                    "column": col,\n                    "description": f"{col} should not be null",\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "candidate_generation_rule",\n                    "target_scope": "primary_target",\n                })\n                rule_id += 1\n\n        # adult 专属强格式 / domain 规则。context-only 列保留这些规则，是为了只捕捉明显非法值，\n        # 但不再让 weak statistical rules 把它们大量放入候选。\n        if col == "age":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "age_bucket_format",\n                "column": col,\n                "description": "age should be a bucket such as <18, 18-21, 22-25, ..., >70",\n                "valid_values": sorted(list(VALID_AGE_BUCKETS)),\n                "regex": r"^(<\\s*\\d+|>\\s*\\d+|\\d+\\s*-\\s*\\d+|\\d+)$",\n                "confidence": 0.92,\n                "support": info["non_null_count"],\n                "usage_role": "strong_rule",\n                "target_scope": "context_only_format_guard",\n            })\n            rule_id += 1\n\n        if col == "hoursperweek":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "hours_per_week_format_range",\n                "column": col,\n                "description": "hoursperweek should be numeric or a numeric range and broadly within 0..120",\n                "lower_bound": 0,\n                "upper_bound": 120,\n                "regex": r"^(\\d+|\\d+\\s*-\\s*\\d+)$",\n                "confidence": 0.90,\n                "support": info["non_null_count"],\n                "usage_role": "strong_rule",\n                "target_scope": "context_only_format_guard",\n            })\n            rule_id += 1\n\n        if col in domain_specs:\n            target_scope = "primary_target" if col in PRIMARY_TARGET_COLUMNS else "context_only_domain_guard"\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": f"{col}_domain",\n                "column": col,\n                "description": f"{col} should be in a known adult domain",\n                "valid_values": sorted(list(domain_specs[col])),\n                "confidence": 0.94 if col in PRIMARY_TARGET_COLUMNS else 0.90,\n                "support": info["non_null_count"],\n                "usage_role": "strong_rule",\n                "target_scope": target_scope,\n            })\n            rule_id += 1\n\n        if col == "income":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "income_canonical_format",\n                "column": col,\n                "description": "income should canonicalize to LessThan50K or MoreThan50K",\n                "confidence": 0.92,\n                "support": info["non_null_count"],\n                "usage_role": "strong_rule",\n                "target_scope": "context_only_format_guard",\n            })\n            rule_id += 1\n\n    return rules\n\n\n# ============================================================\n# 6. FD / soft FD\n# ============================================================\n\ndef select_fd_lhs_candidates(profiles):\n    candidates = []\n    for col, info in profiles.items():\n        if col in EXTRA_SKIP_FD_LHS_COLUMNS:\n            continue\n        if (not ALLOW_INDEX_COLUMN) and info.get("index_like", False):\n            continue\n        if info["unique_ratio"] >= HIGH_CARDINALITY_RATIO_FOR_LHS:\n            continue\n        candidates.append(col)\n    return candidates\n\n\ndef build_fd_rules(df, profiles):\n    rules = []\n    rule_id = 1\n\n    cols = list(df.columns)\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in cols})\n\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n    rhs_candidates = [c for c in FD_RHS_CANDIDATE_COLUMNS if c in cols]\n\n    lhs_sets = []\n    for k in range(1, MAX_LHS_SIZE + 1):\n        lhs_sets.extend(list(combinations(lhs_candidates, k)))\n\n    for lhs in lhs_sets:\n        for rhs in rhs_candidates:\n            if rhs in lhs:\n                continue\n\n            confidence, support = calc_fd_confidence_and_support(norm_df, list(lhs), rhs)\n            if support < MIN_SUPPORT_ROWS:\n                continue\n\n            if confidence >= FD_CONFIDENCE_THRESHOLD:\n                rules.append({\n                    "rule_id": f"FD_{rule_id}",\n                    "rule_type": "functional_dependency",\n                    "lhs": list(lhs),\n                    "rhs": rhs,\n                    "description": f"{\', \'.join(lhs)} -> {rhs}",\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "strong_rule",\n                })\n                rule_id += 1\n\n    dedup = {(tuple(sorted(r["lhs"])), r["rhs"]): r for r in rules}\n    return list(dedup.values())\n\n\ndef build_soft_fd_rules(df, profiles):\n    rules = []\n    rule_id = 1\n\n    cols = list(df.columns)\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in cols})\n\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n    rhs_candidates = [c for c in FD_RHS_CANDIDATE_COLUMNS if c in cols]\n\n    lhs_sets = []\n    for k in range(1, MAX_LHS_SIZE + 1):\n        lhs_sets.extend(list(combinations(lhs_candidates, k)))\n\n    for lhs in lhs_sets:\n        for rhs in rhs_candidates:\n            if rhs in lhs:\n                continue\n\n            confidence, support = calc_soft_fd_confidence_and_support(norm_df, list(lhs), rhs)\n            if support < SOFT_FD_MIN_GROUP_SIZE:\n                continue\n\n            if SOFT_FD_CONFIDENCE_THRESHOLD <= confidence < FD_CONFIDENCE_THRESHOLD:\n                rules.append({\n                    "rule_id": f"CAND_SOFTFD_{rule_id}",\n                    "rule_type": "soft_functional_dependency",\n                    "lhs": list(lhs),\n                    "rhs": rhs,\n                    "description": f"soft FD: {\', \'.join(lhs)} -> {rhs}",\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "candidate_generation_rule",\n                })\n                rule_id += 1\n\n    return rules\n\n\n# ============================================================\n# 7. adult context / consistency rules\n# ============================================================\n\ndef build_pair_context_rules(df):\n    """Build only high-value relationship context rules.\n\n    原版本会为很多列建立 context dominant 规则，导致 age/income/race/country/workclass 等上下文列\n    被大量误纳入候选。Adult v2 只构造 relationship 的多字段上下文规则，并且在 shrink 阶段应只对\n    observed relationship in {Husband, Wife} 触发，用于召回当前最主要的 relationship 错误模式。\n    """\n    rules = []\n    rule_id = 1\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in df.columns})\n\n    rhs = "relationship"\n    if rhs not in norm_df.columns:\n        return rules\n\n    for lhs in RELATIONSHIP_CONTEXT_LHS_SPECS:\n        if any(c not in norm_df.columns for c in lhs + [rhs]):\n            continue\n\n        sub = norm_df[lhs + [rhs]].dropna()\n        if len(sub) < RELATIONSHIP_CONTEXT_MIN_GROUP_SIZE:\n            continue\n\n        grouped = sub.groupby(lhs, dropna=True)[rhs]\n        majority_map = {}\n        total_support = 0\n\n        for key, grp in grouped:\n            if len(grp) < RELATIONSHIP_CONTEXT_MIN_GROUP_SIZE:\n                continue\n\n            cnt = Counter(grp.tolist())\n            maj_val, maj_cnt = cnt.most_common(1)[0]\n            ratio = maj_cnt / len(grp)\n\n            if ratio >= RELATIONSHIP_CONTEXT_MIN_RATIO:\n                if not isinstance(key, tuple):\n                    key = (key,)\n                majority_map["||".join(map(str, key))] = {\n                    "dominant_value": maj_val,\n                    "group_size": len(grp),\n                    "ratio": round(ratio, 6),\n                }\n                total_support += len(grp)\n\n        if majority_map:\n            rules.append({\n                "rule_id": f"CAND_RELCTX_{rule_id}",\n                "rule_type": "relationship_context_dominant",\n                "lhs": lhs,\n                "rhs": rhs,\n                "target_column": rhs,\n                "description": f"relationship context dominant: {\', \'.join(lhs)} -> relationship",\n                "mapping_size": len(majority_map),\n                "majority_map": majority_map,\n                "confidence": 0.86,\n                "support": total_support,\n                "usage_role": "candidate_generation_rule",\n                "priority": "medium",\n                "only_trigger_observed_values": RELATIONSHIP_CONTEXT_TRIGGER_VALUES,\n                "min_group_size": RELATIONSHIP_CONTEXT_MIN_GROUP_SIZE,\n                "min_ratio": RELATIONSHIP_CONTEXT_MIN_RATIO,\n            })\n            rule_id += 1\n\n    return rules\n\n\ndef build_adult_consistency_rules(df, profiles):\n    """Build attribution-aware Adult consistency rules.\n\n    关键变化：relationship 与 maritalstatus/age/sex 冲突时，优先将候选归因到 relationship，\n    而不是把 age/maritalstatus/sex 都打成候选。\n    """\n    rules = []\n    rule_id = 1\n\n    if {"maritalstatus", "relationship"}.issubset(df.columns):\n        rules.append({\n            "rule_id": f"CAND_RELATTR_{rule_id}",\n            "rule_type": "relationship_marital_spouse_conflict",\n            "columns": ["maritalstatus", "relationship"],\n            "target_column": "relationship",\n            "description": "If relationship is Husband/Wife while maritalstatus is non-married, attribute the suspicious cell to relationship.",\n            "spouse_values": sorted(list(RELATIONSHIP_SPOUSE_VALUES)),\n            "conflicting_maritalstatus": sorted(list(NON_MARRIED_STATUS_FOR_SPOUSE)),\n            "confidence": 0.94,\n            "support": len(df),\n            "usage_role": "strong_rule",\n            "priority": "high",\n        })\n        rule_id += 1\n\n    if {"age", "relationship"}.issubset(df.columns):\n        rules.append({\n            "rule_id": f"CAND_RELATTR_{rule_id}",\n            "rule_type": "relationship_age_spouse_conflict",\n            "columns": ["age", "relationship"],\n            "target_column": "relationship",\n            "description": "If a very young age bucket co-occurs with Husband/Wife, attribute the suspicious cell to relationship.",\n            "spouse_values": sorted(list(RELATIONSHIP_SPOUSE_VALUES)),\n            "max_age_upper_for_conflict": 17,\n            "confidence": 0.90,\n            "support": len(df),\n            "usage_role": "strong_rule",\n            "priority": "high",\n        })\n        rule_id += 1\n\n    if {"sex", "relationship"}.issubset(df.columns):\n        rules.append({\n            "rule_id": f"CAND_RELATTR_{rule_id}",\n            "rule_type": "relationship_sex_spouse_conflict",\n            "columns": ["sex", "relationship"],\n            "target_column": "relationship",\n            "description": "If relationship Husband/Wife conflicts with a valid sex value, attribute the suspicious cell to relationship; invalid sex itself should be handled by sex_domain.",\n            "expected_by_relationship": {"Husband": "Male", "Wife": "Female"},\n            "confidence": 0.88,\n            "support": len(df),\n            "usage_role": "candidate_generation_rule",\n            "priority": "medium",\n        })\n        rule_id += 1\n\n    if {"age", "education"}.issubset(df.columns):\n        rules.append({\n            "rule_id": f"CAND_RELATTR_{rule_id}",\n            "rule_type": "education_age_extreme_conflict",\n            "columns": ["age", "education"],\n            "target_column": "education",\n            "description": "Very young age buckets should not have extremely high education levels; attribute the suspicious cell to education.",\n            "education_order": EDUCATION_ORDER,\n            "min_extreme_education_order": EDUCATION_ORDER["Bachelors"],\n            "max_age_upper_for_conflict": 17,\n            "confidence": 0.86,\n            "support": len(df),\n            "usage_role": "candidate_generation_rule",\n            "priority": "medium",\n        })\n        rule_id += 1\n\n    return rules\n\n\ndef build_candidate_generation_rules(df, profiles):\n    rules = []\n    rule_id = 1\n\n    # Adult v2: 不再生成 global_dominant / rare_value / rare_pattern / generic context dominant。\n    # 当前评估表明这些弱统计规则会把 age/income/race/country/workclass 等上下文列大规模误纳入候选。\n\n    # high risk missing: only primary targets\n    for col in HIGH_RISK_MISSING_COLUMNS:\n        if col not in profiles:\n            continue\n        prof = profiles[col]\n        rules.append({\n            "rule_id": f"CAND_HRMISS_{rule_id}",\n            "rule_type": "high_risk_missing",\n            "column": col,\n            "target_column": col,\n            "description": f"{col} missing values are suspicious in candidate generation",\n            "confidence": 0.82,\n            "support": prof["non_null_count"],\n            "usage_role": "candidate_generation_rule",\n            "priority": "medium",\n            "target_scope": "primary_target",\n        })\n        rule_id += 1\n\n    # 只保留与 relationship 主错误模式相关的多字段上下文规则，和显式 attribution consistency rules。\n    rules.extend(build_pair_context_rules(df))\n    rules.extend(build_adult_consistency_rules(df, profiles))\n\n    return rules\n\n\n# ============================================================\n# 8. priority\n# ============================================================\n\ndef assign_rule_priority(rule):\n    rtype = rule.get("rule_type", "")\n\n    if rtype in {\n        "sex_domain",\n        "relationship_domain",\n        "education_domain",\n        "relationship_marital_spouse_conflict",\n        "relationship_age_spouse_conflict",\n    }:\n        return "high"\n\n    if rtype in {\n        "age_bucket_format",\n        "hours_per_week_format_range",\n        "workclass_domain",\n        "maritalstatus_domain",\n        "occupation_domain",\n        "race_domain",\n        "country_domain",\n        "income_domain",\n        "income_canonical_format",\n        "relationship_sex_spouse_conflict",\n        "education_age_extreme_conflict",\n        "relationship_context_dominant",\n        "high_risk_missing",\n    }:\n        return "medium"\n\n    if rtype in {\n        "functional_dependency",\n        "soft_functional_dependency",\n    }:\n        # FD/soft-FD 只作为证据，优先级不宜过高，避免把上下文统计相关性当作强规则。\n        return "low"\n\n    if rule.get("usage_role", "candidate_generation_rule") == "candidate_generation_rule":\n        if rule.get("confidence", 0.0) >= 0.90 and rule.get("support", 0) >= 20:\n            return "medium"\n        return "low"\n\n    return "medium"\n\n\ndef enrich_rules_with_priority(rule_groups):\n    new_groups = {}\n    for group_name, rules in rule_groups.items():\n        enriched = []\n        for r in rules:\n            r2 = dict(r)\n            r2["priority"] = assign_rule_priority(r2)\n            enriched.append(r2)\n        new_groups[group_name] = enriched\n    return new_groups\n\n\n# ============================================================\n# 9. 主流程\n# ============================================================\n\ndef build_rule_pool(input_csv, output_json):\n    df = pd.read_csv(input_csv, dtype=str)\n    df = maybe_drop_unnamed_columns(df)\n\n    for col in df.columns:\n        df[col] = normalize_series(df[col])\n\n    profiles = analyze_columns(df)\n    schema_rules = build_schema_rules(df, profiles)\n    fd_rules = build_fd_rules(df, profiles)\n    soft_fd_rules = build_soft_fd_rules(df, profiles)\n    candidate_rules = build_candidate_generation_rules(df, profiles)\n\n    rule_groups = {\n        "schema_rules": schema_rules,\n        "fd_rules": fd_rules,\n        "soft_fd_rules": soft_fd_rules,\n        "candidate_rules": candidate_rules,\n    }\n    rule_groups = enrich_rules_with_priority(rule_groups)\n\n    rule_pool = {\n        "metadata": {\n            "source_file": input_csv,\n            "row_count": int(len(df)),\n            "column_count": int(len(df.columns)),\n            "design_goal": "high_recall_candidate_generation_for_adult",\n            "target_candidate_columns": sorted(list(TARGET_CANDIDATE_COLUMNS)),\n            "primary_target_columns": sorted(list(PRIMARY_TARGET_COLUMNS)),\n            "context_only_columns": sorted(list(CONTEXT_ONLY_COLUMNS)),\n            "notes": [\n                "candidate inclusion is determined only by violating rules in this pool",\n                "adult v2 focuses candidate generation on sex, relationship, and education based on evaluation error distribution",\n                "global dominant, rare value, rare pattern, and generic context-dominant rules are disabled to avoid excessive false positives",\n                "relationship-specific attribution rules target Husband/Wife conflicts with maritalstatus, age, and sex",\n                "FD and soft FD rules are mined only for primary target RHS columns and should be used as weak evidence rather than final labels",\n            ],\n        },\n        "column_profiles": profiles,\n        "rules": rule_groups,\n    }\n\n    with open(output_json, "w", encoding="utf-8") as f:\n        json.dump(rule_pool, f, ensure_ascii=False, indent=2)\n\n    print(f"[OK] Rule pool saved to: {output_json}")\n    print(f"Schema rules: {len(schema_rules)}")\n    print(f"FD rules: {len(fd_rules)}")\n    print(f"Soft FD rules: {len(soft_fd_rules)}")\n    print(f"Candidate generation rules: {len(candidate_rules)}")\n\n\nif __name__ == "__main__":\n    build_rule_pool(INPUT_CSV, OUTPUT_JSON)\n',
    'soccer': 'import json\nimport math\nimport re\nfrom collections import Counter\nfrom itertools import combinations\nfrom typing import Dict, List, Any, Optional, Tuple\n\nimport pandas as pd\n\n\n# ============================================================\n# 1. 用户配置区\n# ============================================================\n\nINPUT_CSV = "/mnt/mydata/dq/projects/Splittree/soccer/soccer_dirty.csv"\nOUTPUT_JSON = "rule_pool_soccer.json"\n\nMISSING_TOKENS = {\n    "", "empty", "null", "none", "nan", "na", "n/a", "missing", "unk",\n    "unknown", "?", "not available", "contact airline"\n}\n\nNUMERIC_RATIO_THRESHOLD = 0.90\nENUM_UNIQUE_THRESHOLD = 120\nENUM_RATIO_THRESHOLD = 0.12\n\nID_LIKE_UNIQUE_RATIO_THRESHOLD = 0.98\nCODE_LIKE_AVG_LEN_THRESHOLD = 35\nCODE_LIKE_DOMINANT_PATTERN_THRESHOLD = 0.70\nDOMINANT_PATTERN_THRESHOLD = 0.70\nDOMINANT_TYPO_MIN_RATIO = 0.50\n\nMAX_LHS_SIZE = 2\n\n# FD/soft-FD 是本轮结果中 FP 激增的主要来源。\n# 因此强 FD 只保留极高置信、较大支持的关系；soft-FD 只输出为 evidence_only，\n# 不允许直接作为候选生成规则。\nFD_CONFIDENCE_THRESHOLD = 0.995\nMIN_SUPPORT_ROWS = 50\nFD_MIN_GROUP_SIZE = 10\nFD_MIN_DOMINANT_RATIO = 0.98\nFD_MIN_DOMINANT_MARGIN = 5\n\nSOFT_FD_CONFIDENCE_THRESHOLD = 0.90\nSOFT_FD_MIN_GROUP_SIZE = 20\nSOFT_FD_MIN_SUPPORT_ROWS = 200\nSOFT_FD_USAGE_ROLE = "evidence_only"\n\nPAIR_CONTEXT_MIN_RATIO = 0.98\nPAIR_CONTEXT_MIN_GROUP_SIZE = 20\n\nHIGH_CARDINALITY_RATIO_FOR_LHS = 0.95\nALLOW_INDEX_COLUMN = False\nSKIP_SCHEMA_FOR_ID_LIKE = True\n\n# ------------------------------------------------------------\n# soccer 数据集字段\n# ------------------------------------------------------------\nSOCCER_COLUMNS = [\n    "name",\n    "surname",\n    "birthyear",\n    "birthplace",\n    "position",\n    "team",\n    "city",\n    "stadium",\n    "season",\n    "manager",\n]\n\n# ------------------------------------------------------------\n# Soccer 候选生成策略\n# ------------------------------------------------------------\n# Soccer 数据集中，name/surname/manager/team/stadium 等文本字段可能存在格式噪声，\n# birthyear/season 存在数值范围与年龄一致性约束，position 是强 domain 字段。\n# 这里采用 schema-aware 但尽量不过度数据集后验调参的设计：\n# 1) PRIMARY_TARGET_COLUMNS 是主要检测列；\n# 2) CONTEXT_ONLY_COLUMNS 主要用于上下文证据，不使用 rare/global dominant 大规模造候选；\n# 3) team-season/team/stadium/city/manager 等关系用 mined context/FD 作为候选证据。\nPRIMARY_TARGET_COLUMNS = set(SOCCER_COLUMNS)\n\n# Soccer 本轮修正：不再把 name/surname 排除在候选目标外。\n# 上一版评估中 name/surname/birthplace 几乎没有进入候选，导致候选召回上限被锁死。\n# 这里所有列都允许由 schema/missing/format 强规则进入候选；\n# 但 FD / context / rare / global-dominant 仍不能把 name/surname 这类长尾身份列大规模拉入候选。\nCONTEXT_ONLY_COLUMNS = set()\n\nSCHEMA_RULE_COLUMNS = set(SOCCER_COLUMNS)\nTARGET_CANDIDATE_COLUMNS = set(PRIMARY_TARGET_COLUMNS)\nHIGH_RISK_MISSING_COLUMNS = set(SOCCER_COLUMNS)\n\n# Soccer domain\nVALID_POSITIONS = {\n    "Goalkeeper",\n    "Defender",\n    "Midfield",\n    "Midfielder",\n    "Forward",\n    "Striker",\n    "Winger",\n}\n\nPOSITION_CANONICAL_MAP = {\n    "Midfielder": "Midfield",\n}\n\n# 年龄/赛季合理范围。Soccer 中 season 是比赛/赛季年份，birthyear 是出生年份。\nBIRTHYEAR_MIN = 1940\nBIRTHYEAR_MAX = 2010\nSEASON_MIN = 1900\nSEASON_MAX = 2035\nPLAYER_MIN_AGE_AT_SEASON = 15\nPLAYER_MAX_AGE_AT_SEASON = 50\n\n# pattern 规则：下划线是该数据集中常见分隔符。\nPERSON_NAME_REGEX = r"^[A-Za-z]+(?:_[A-Za-z]+)*$"\nSURNAME_REGEX = r"^[A-Za-z]+(?:[-_\'][A-Za-z]+)*$"\nTEAM_REGEX = r"^[A-Za-z0-9]+(?:[._\'\\-][A-Za-z0-9]+)*$"\nLOCATION_REGEX = r"^[A-Za-z]+(?:[ _\'\\-][A-Za-z]+)*$"\nSTADIUM_REGEX = r"^[A-Za-z0-9]+(?:[ _\'\\-][A-Za-z0-9]+)*$"\n\n# 弱规则控制\nENABLE_RARE_VALUE_RULE = False\nRARE_VALUE_MAX_FREQ = 2\nSKIP_RARE_VALUE_COLUMNS = set(SOCCER_COLUMNS)\n\nENABLE_RARE_PATTERN_RULE = False\nRARE_PATTERN_MAX_RATIO = 0.02\nSKIP_RARE_PATTERN_COLUMNS = set(SOCCER_COLUMNS)\n\n# global dominant 容易把多数队伍/城市/球场误当规则，默认关闭。\nSKIP_GLOBAL_DOMINANT_COLUMNS = set(SOCCER_COLUMNS)\n\n# Generic pattern 规则只用于明显格式字段。数值/position 用专门规则。\nSKIP_GENERIC_PATTERN_COLUMNS = {\n    "birthyear",\n    "position",\n    "season",\n}\n\n# FD/soft-FD 的 RHS 只允许指向相对结构化的非身份列。\n# name/surname 的召回依靠 missing/pattern，不依靠统计相关性。\nFD_RHS_CANDIDATE_COLUMNS = {\n    "birthplace",\n    "position",\n    "team",\n    "city",\n    "stadium",\n    "season",\n    "manager",\n}\nEXTRA_SKIP_FD_LHS_COLUMNS = {"name", "surname", "manager"}\n\n# team-season 上下文 dominant 规则。通常同一 team + season 的 city/stadium/manager 更稳定。\nTEAM_SEASON_CONTEXT_LHS_SPECS = [\n    ["team", "season"],\n    ["team"],\n    ["stadium"],\n    ["city", "stadium"],\n]\nTEAM_CONTEXT_TARGETS = ["city", "stadium", "manager"]\n# context dominant 同样不能过宽。上一版 team-context 虽然比 soft-FD 少，\n# 但仍应当作为弱证据而不是最终判断。\nTEAM_CONTEXT_MIN_GROUP_SIZE = 20\nTEAM_CONTEXT_MIN_RATIO = 0.98\nTEAM_CONTEXT_MIN_DOMINANT_MARGIN = 5\nTEAM_CONTEXT_USAGE_ROLE = "evidence_only"\n\n# birthyear/season 年龄一致性\nENABLE_BIRTHYEAR_SEASON_AGE_RULE = True\n\n\n# ============================================================\n# 2. 基础函数\n# ============================================================\n\ndef normalize_value(x):\n    if pd.isna(x):\n        return None\n    s = str(x).strip()\n    if s.lower() in MISSING_TOKENS:\n        return None\n    return s\n\n\ndef normalize_series(s):\n    return s.map(normalize_value)\n\n\ndef maybe_drop_unnamed_columns(df):\n    keep_cols = [c for c in df.columns if not str(c).lower().startswith("unnamed:")]\n    return df[keep_cols].copy()\n\n\ndef detect_basic_pattern(value):\n    if value is None:\n        return "NULL"\n    parts, prev_type, cnt = [], None, 0\n    for ch in str(value):\n        if ch.isdigit():\n            cur = "D"\n        elif ch.isalpha():\n            cur = "L"\n        elif ch in {" ", "-", "_", "/", ".", ",", "(", ")", "%", ":", ";", "&", "\'", "+", "<", ">"}:\n            cur = "S"\n        else:\n            cur = "X"\n        if cur == prev_type:\n            cnt += 1\n        else:\n            if prev_type is not None:\n                parts.append(f"{prev_type}{cnt}")\n            prev_type = cur\n            cnt = 1\n    if prev_type is not None:\n        parts.append(f"{prev_type}{cnt}")\n    return "".join(parts)\n\n\ndef try_parse_numeric(series):\n    cleaned = series.dropna().astype(str).str.replace(",", "", regex=False).str.replace("%", "", regex=False)\n    numeric = pd.to_numeric(cleaned, errors="coerce")\n    success_ratio = numeric.notna().mean() if len(cleaned) > 0 else 0.0\n    return numeric, success_ratio\n\n\ndef parse_int_like(x: Optional[str]) -> Optional[int]:\n    if x is None:\n        return None\n    s = str(x).strip().replace(",", "")\n    if re.fullmatch(r"[+-]?\\d+(\\.0+)?", s):\n        try:\n            return int(float(s))\n        except Exception:\n            return None\n    return None\n\n\ndef parse_year(value: Optional[str]) -> Optional[int]:\n    n = parse_int_like(value)\n    if n is None:\n        return None\n    return n\n\n\ndef canonical_position(value: Optional[str]) -> Optional[str]:\n    if value is None:\n        return None\n    s = str(value).strip()\n    if s in POSITION_CANONICAL_MAP:\n        return POSITION_CANONICAL_MAP[s]\n    if s in VALID_POSITIONS:\n        return s\n    return None\n\n\ndef is_regex_match(value: Optional[str], pattern: str) -> bool:\n    if value is None:\n        return True\n    return bool(re.fullmatch(pattern, str(value).strip()))\n\n\ndef shannon_entropy(series):\n    vals = series.dropna().tolist()\n    if not vals:\n        return 0.0\n    cnt = Counter(vals)\n    total = len(vals)\n    ent = 0.0\n    for c in cnt.values():\n        p = c / total\n        ent -= p * math.log2(p)\n    return ent\n\n\ndef value_frequency_dict(series, topk=20):\n    cnt = Counter(series.dropna().tolist())\n    total = sum(cnt.values()) if cnt else 0\n    out = []\n    for k, v in cnt.most_common(topk):\n        out.append({"value": k, "count": v, "ratio": round(v / total, 6) if total > 0 else 0.0})\n    return out\n\n\ndef is_index_like_column(series):\n    s = series.dropna()\n    if len(s) == 0:\n        return False\n    numeric = pd.to_numeric(s, errors="coerce")\n    if numeric.notna().mean() < 0.95:\n        return False\n    unique_ratio = s.nunique() / len(s)\n    return unique_ratio > 0.98\n\n\ndef is_id_like_column(non_null, unique_ratio, numeric_ratio, avg_len):\n    if len(non_null) == 0:\n        return False\n    if unique_ratio >= ID_LIKE_UNIQUE_RATIO_THRESHOLD and avg_len <= CODE_LIKE_AVG_LEN_THRESHOLD:\n        return True\n    if unique_ratio >= ID_LIKE_UNIQUE_RATIO_THRESHOLD and numeric_ratio >= NUMERIC_RATIO_THRESHOLD:\n        return True\n    return False\n\n\ndef is_code_like_column(non_null, unique_ratio, numeric_ratio, avg_len, top_patterns):\n    if len(non_null) == 0:\n        return False\n    dominant_ratio = top_patterns[0]["ratio"] if top_patterns else 0.0\n    if avg_len <= CODE_LIKE_AVG_LEN_THRESHOLD and dominant_ratio >= CODE_LIKE_DOMINANT_PATTERN_THRESHOLD:\n        if unique_ratio > ENUM_RATIO_THRESHOLD:\n            return True\n    if numeric_ratio >= 0.95 and avg_len <= 15 and unique_ratio < ID_LIKE_UNIQUE_RATIO_THRESHOLD:\n        return True\n    return False\n\n\n# ============================================================\n# 3. 规则统计函数\n# ============================================================\n\ndef calc_fd_confidence_and_support(df, lhs_cols, rhs_col):\n    sub = df[lhs_cols + [rhs_col]].dropna()\n    support = len(sub)\n    if support < MIN_SUPPORT_ROWS:\n        return 0.0, support\n    grouped = sub.groupby(lhs_cols, dropna=True)[rhs_col]\n    majority_sum = 0\n    for _, grp in grouped:\n        cnt = Counter(grp.tolist())\n        majority_sum += cnt.most_common(1)[0][1]\n    confidence = majority_sum / support if support > 0 else 0.0\n    return round(confidence, 6), int(support)\n\n\ndef calc_soft_fd_confidence_and_support(df, lhs_cols, rhs_col):\n    sub = df[lhs_cols + [rhs_col]].dropna()\n    support = len(sub)\n    if support < SOFT_FD_MIN_GROUP_SIZE:\n        return 0.0, support\n    grouped = sub.groupby(lhs_cols, dropna=True)[rhs_col]\n    majority_sum = 0\n    used_support = 0\n    for _, grp in grouped:\n        if len(grp) < SOFT_FD_MIN_GROUP_SIZE:\n            continue\n        cnt = Counter(grp.tolist())\n        majority_sum += cnt.most_common(1)[0][1]\n        used_support += len(grp)\n    confidence = majority_sum / used_support if used_support > 0 else 0.0\n    return round(confidence, 6), int(used_support)\n\n\ndef calc_fd_quality_profile(df, lhs_cols, rhs_col, min_group_size):\n    """Return stricter FD quality signals used to avoid soft-FD candidate explosion.\n\n    confidence alone is insufficient on long-tail entity data. This profile requires:\n    - enough non-null support;\n    - enough usable groups;\n    - sufficiently pure majority value inside groups;\n    - sufficient majority margin over the second value.\n    """\n    sub = df[lhs_cols + [rhs_col]].dropna()\n    support = len(sub)\n    if support == 0:\n        return {\n            "support": 0,\n            "used_support": 0,\n            "confidence": 0.0,\n            "usable_group_count": 0,\n            "avg_group_size": 0.0,\n            "min_group_size": 0,\n            "qualified_group_count": 0,\n            "qualified_support": 0,\n            "qualified_ratio": 0.0,\n        }\n\n    grouped = sub.groupby(lhs_cols, dropna=True)[rhs_col]\n    majority_sum = 0\n    used_support = 0\n    usable_group_count = 0\n    qualified_group_count = 0\n    qualified_support = 0\n    group_sizes = []\n\n    for _, grp in grouped:\n        gsize = len(grp)\n        if gsize < min_group_size:\n            continue\n        cnt = Counter(grp.tolist())\n        most = cnt.most_common(2)\n        maj_val, maj_cnt = most[0]\n        second_cnt = most[1][1] if len(most) > 1 else 0\n        ratio = maj_cnt / gsize if gsize > 0 else 0.0\n        margin = maj_cnt - second_cnt\n\n        usable_group_count += 1\n        used_support += gsize\n        majority_sum += maj_cnt\n        group_sizes.append(gsize)\n\n        if ratio >= FD_MIN_DOMINANT_RATIO and margin >= FD_MIN_DOMINANT_MARGIN:\n            qualified_group_count += 1\n            qualified_support += gsize\n\n    confidence = majority_sum / used_support if used_support > 0 else 0.0\n    qualified_ratio = qualified_support / used_support if used_support > 0 else 0.0\n\n    return {\n        "support": int(support),\n        "used_support": int(used_support),\n        "confidence": round(float(confidence), 6),\n        "usable_group_count": int(usable_group_count),\n        "avg_group_size": round(float(sum(group_sizes) / len(group_sizes)), 6) if group_sizes else 0.0,\n        "min_group_size": int(min(group_sizes)) if group_sizes else 0,\n        "qualified_group_count": int(qualified_group_count),\n        "qualified_support": int(qualified_support),\n        "qualified_ratio": round(float(qualified_ratio), 6),\n    }\n\n\ndef calc_not_null_confidence_and_support(series):\n    total = len(series)\n    if total == 0:\n        return 0.0, 0\n    non_null = series.notna().sum()\n    return round(non_null / total, 6), int(total)\n\n\ndef calc_pattern_confidence_and_support(series, dominant_pattern):\n    non_null = series.dropna()\n    support = len(non_null)\n    if support == 0:\n        return 0.0, 0\n    pats = non_null.map(detect_basic_pattern)\n    ok = (pats == dominant_pattern).sum()\n    return round(ok / support, 6), int(support)\n\n\n# ============================================================\n# 4. 列画像\n# ============================================================\n\ndef analyze_columns(df):\n    profiles = {}\n    n = len(df)\n\n    for col in df.columns:\n        s = normalize_series(df[col])\n        non_null = s.dropna()\n        missing_rate = 1.0 - (len(non_null) / n if n > 0 else 0.0)\n        unique_count = non_null.nunique()\n        unique_ratio = unique_count / len(non_null) if len(non_null) > 0 else 0.0\n        numeric_vals, numeric_ratio = try_parse_numeric(non_null)\n\n        patterns = non_null.map(detect_basic_pattern)\n        pattern_counter = Counter(patterns.tolist())\n        total_patterns = sum(pattern_counter.values())\n        top_patterns = [\n            {"pattern": p, "count": c, "ratio": round(c / total_patterns, 6)}\n            for p, c in pattern_counter.most_common(10)\n        ]\n\n        lengths = non_null.map(lambda x: len(str(x)))\n        avg_len = float(lengths.mean()) if len(lengths) > 0 else 0.0\n\n        profile = {\n            "column": col,\n            "missing_rate": round(missing_rate, 6),\n            "non_null_count": int(len(non_null)),\n            "unique_count": int(unique_count),\n            "unique_ratio": round(unique_ratio, 6),\n            "numeric_parse_ratio": round(float(numeric_ratio), 6),\n            "entropy": round(shannon_entropy(non_null), 6),\n            "detected_type": None,\n            "semantic_type": None,\n            "index_like": is_index_like_column(non_null),\n            "avg_length": round(avg_len, 6),\n            "top_values": value_frequency_dict(non_null, topk=20),\n            "top_patterns": top_patterns,\n            "value_counter": Counter(non_null.tolist()),\n        }\n\n        if col == "birthyear":\n            profile["detected_type"] = "numeric"\n            profile["semantic_type"] = "birth_year"\n        elif col == "season":\n            profile["detected_type"] = "numeric"\n            profile["semantic_type"] = "season_year"\n        elif col == "position":\n            profile["detected_type"] = "categorical"\n            profile["semantic_type"] = "position_category"\n        elif col in {"team", "stadium"}:\n            profile["detected_type"] = "categorical" if unique_count <= ENUM_UNIQUE_THRESHOLD or unique_ratio <= 0.25 else "text"\n            profile["semantic_type"] = f"{col}_entity"\n        elif col in {"name", "surname", "manager"}:\n            profile["detected_type"] = "text"\n            profile["semantic_type"] = "person_name"\n        elif col in {"birthplace", "city"}:\n            profile["detected_type"] = "categorical" if unique_count <= ENUM_UNIQUE_THRESHOLD or unique_ratio <= 0.25 else "text"\n            profile["semantic_type"] = "location"\n        elif numeric_ratio >= NUMERIC_RATIO_THRESHOLD:\n            profile["detected_type"] = "numeric"\n            profile["semantic_type"] = "numeric"\n        else:\n            if unique_count <= ENUM_UNIQUE_THRESHOLD or unique_ratio <= ENUM_RATIO_THRESHOLD:\n                profile["detected_type"] = "categorical"\n            else:\n                profile["detected_type"] = "text"\n\n            if profile["index_like"]:\n                profile["semantic_type"] = "id_like"\n            elif is_id_like_column(non_null, unique_ratio, numeric_ratio, avg_len):\n                profile["semantic_type"] = "id_like"\n            elif is_code_like_column(non_null, unique_ratio, numeric_ratio, avg_len, top_patterns):\n                profile["semantic_type"] = "code_like"\n            elif profile["detected_type"] == "numeric":\n                profile["semantic_type"] = "numeric"\n            elif profile["detected_type"] == "categorical":\n                profile["semantic_type"] = "categorical"\n            else:\n                profile["semantic_type"] = "text"\n\n        profiles[col] = profile\n\n    return profiles\n\n\n# ============================================================\n# 5. schema/domain rules\n# ============================================================\n\ndef build_schema_rules(df, profiles):\n    rules = []\n    rule_id = 1\n\n    for col, info in profiles.items():\n        if col not in SCHEMA_RULE_COLUMNS:\n            continue\n\n        series = normalize_series(df[col])\n\n        if col in HIGH_RISK_MISSING_COLUMNS:\n            # Soccer 修正：name/surname/birthplace 的 missing 是上一轮漏召回的主要来源，因此统一纳入 missing guard。\n            not_null_threshold = 0.95\n            if col in {"team", "position", "season"}:\n                not_null_threshold = 0.98\n            if info["missing_rate"] <= (1.0 - not_null_threshold):\n                confidence, support = calc_not_null_confidence_and_support(series)\n                rules.append({\n                    "rule_id": f"SCHEMA_{rule_id}",\n                    "rule_type": "not_null",\n                    "column": col,\n                    "target_column": col,\n                    "description": f"{col} should not be null in soccer records",\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "strong_rule" if col in PRIMARY_TARGET_COLUMNS else "candidate_generation_rule",\n                    "target_scope": "primary_target" if col in PRIMARY_TARGET_COLUMNS else "context_guard",\n                })\n                rule_id += 1\n\n        if col == "birthyear":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "birthyear_numeric_range",\n                "column": col,\n                "target_column": col,\n                "description": f"birthyear should be an integer year within {BIRTHYEAR_MIN}..{BIRTHYEAR_MAX}",\n                "lower_bound": BIRTHYEAR_MIN,\n                "upper_bound": BIRTHYEAR_MAX,\n                "regex": r"^\\d{4}$",\n                "confidence": 0.95,\n                "support": info["non_null_count"],\n                "usage_role": "strong_rule",\n                "target_scope": "primary_target_numeric_guard",\n            })\n            rule_id += 1\n\n        if col == "season":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "season_numeric_range",\n                "column": col,\n                "target_column": col,\n                "description": f"season should be an integer year within {SEASON_MIN}..{SEASON_MAX}",\n                "lower_bound": SEASON_MIN,\n                "upper_bound": SEASON_MAX,\n                "regex": r"^\\d{4}$",\n                "confidence": 0.95,\n                "support": info["non_null_count"],\n                "usage_role": "strong_rule",\n                "target_scope": "primary_target_numeric_guard",\n            })\n            rule_id += 1\n\n        if col == "position":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "position_domain",\n                "column": col,\n                "target_column": col,\n                "description": "position should be a known soccer playing position",\n                "valid_values": sorted(list(VALID_POSITIONS)),\n                "canonical_map": POSITION_CANONICAL_MAP,\n                "confidence": 0.96,\n                "support": info["non_null_count"],\n                "usage_role": "strong_rule",\n                "target_scope": "primary_target_domain_guard",\n            })\n            rule_id += 1\n\n        if col == "name":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "name_pattern",\n                "column": col,\n                "target_column": col,\n                "description": "name should contain alphabetic tokens separated by underscores",\n                "regex": PERSON_NAME_REGEX,\n                "confidence": 0.88,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n                "target_scope": "identity_format_guard",\n            })\n            rule_id += 1\n\n        if col == "surname":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "surname_pattern",\n                "column": col,\n                "target_column": col,\n                "description": "surname should be alphabetic, optionally with hyphen/underscore/apostrophe separators",\n                "regex": SURNAME_REGEX,\n                "confidence": 0.88,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n                "target_scope": "identity_format_guard",\n            })\n            rule_id += 1\n\n        if col == "manager":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "manager_name_pattern",\n                "column": col,\n                "target_column": col,\n                "description": "manager should look like a person name, often with underscore-separated tokens",\n                "regex": PERSON_NAME_REGEX,\n                "confidence": 0.88,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n                "target_scope": "primary_target_format_guard",\n            })\n            rule_id += 1\n\n        if col == "team":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "team_name_pattern",\n                "column": col,\n                "target_column": col,\n                "description": "team should look like a club/team entity string",\n                "regex": TEAM_REGEX,\n                "confidence": 0.86,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n                "target_scope": "primary_target_format_guard",\n            })\n            rule_id += 1\n\n        if col in {"birthplace", "city"}:\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": f"{col}_location_pattern",\n                "column": col,\n                "target_column": col,\n                "description": f"{col} should look like a location name",\n                "regex": LOCATION_REGEX,\n                "confidence": 0.86,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n                "target_scope": "primary_target_format_guard",\n            })\n            rule_id += 1\n\n        if col == "stadium":\n            rules.append({\n                "rule_id": f"SCHEMA_{rule_id}",\n                "rule_type": "stadium_name_pattern",\n                "column": col,\n                "target_column": col,\n                "description": "stadium should look like a stadium/entity string",\n                "regex": STADIUM_REGEX,\n                "confidence": 0.86,\n                "support": info["non_null_count"],\n                "usage_role": "candidate_generation_rule",\n                "target_scope": "primary_target_format_guard",\n            })\n            rule_id += 1\n\n        # Generic dominant pattern rule: only for selected text/entity columns, not for numeric/domain fields.\n        if col not in SKIP_GENERIC_PATTERN_COLUMNS:\n            top_patterns = info.get("top_patterns", [])\n            if top_patterns:\n                dominant = top_patterns[0]\n                if dominant["ratio"] >= DOMINANT_PATTERN_THRESHOLD:\n                    confidence, support = calc_pattern_confidence_and_support(series, dominant["pattern"])\n                    rules.append({\n                        "rule_id": f"SCHEMA_{rule_id}",\n                        "rule_type": "pattern",\n                        "column": col,\n                        "target_column": col,\n                        "description": f"{col} usually follows pattern {dominant[\'pattern\']}",\n                        "dominant_pattern": dominant["pattern"],\n                        "dominant_pattern_ratio": dominant["ratio"],\n                        "confidence": confidence,\n                        "support": support,\n                        "usage_role": "candidate_generation_rule",\n                        "target_scope": "format_guard",\n                    })\n                    rule_id += 1\n\n    return rules\n\n\n# ============================================================\n# 6. FD / soft FD\n# ============================================================\n\ndef select_fd_lhs_candidates(profiles):\n    candidates = []\n    for col, info in profiles.items():\n        if col in EXTRA_SKIP_FD_LHS_COLUMNS:\n            continue\n        if (not ALLOW_INDEX_COLUMN) and info.get("index_like", False):\n            continue\n        if info["unique_ratio"] >= HIGH_CARDINALITY_RATIO_FOR_LHS:\n            continue\n        candidates.append(col)\n    return candidates\n\n\ndef build_fd_rules(df, profiles):\n    rules = []\n    rule_id = 1\n\n    cols = list(df.columns)\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in cols})\n\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n    rhs_candidates = [c for c in FD_RHS_CANDIDATE_COLUMNS if c in cols]\n\n    lhs_sets = []\n    for k in range(1, MAX_LHS_SIZE + 1):\n        lhs_sets.extend(list(combinations(lhs_candidates, k)))\n\n    for lhs in lhs_sets:\n        for rhs in rhs_candidates:\n            if rhs in lhs:\n                continue\n\n            profile = calc_fd_quality_profile(norm_df, list(lhs), rhs, min_group_size=FD_MIN_GROUP_SIZE)\n            confidence = profile["confidence"]\n            support = profile["used_support"]\n            if support < MIN_SUPPORT_ROWS:\n                continue\n\n            # Strong FD must be both highly confident and dominated by qualified groups.\n            if (\n                confidence >= FD_CONFIDENCE_THRESHOLD\n                and profile["qualified_group_count"] > 0\n                and profile["qualified_ratio"] >= 0.80\n            ):\n                rules.append({\n                    "rule_id": f"FD_{rule_id}",\n                    "rule_type": "functional_dependency",\n                    "lhs": list(lhs),\n                    "rhs": rhs,\n                    "target_column": rhs,\n                    "description": f"{\', \'.join(lhs)} -> {rhs}",\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": "strong_rule",\n                    "priority": "low",\n                    "candidate_trigger": "strict_fd_only",\n                    "fd_quality_profile": profile,\n                    "candidate_trigger_conditions": {\n                        "min_group_size": FD_MIN_GROUP_SIZE,\n                        "min_dominant_ratio": FD_MIN_DOMINANT_RATIO,\n                        "min_dominant_margin": FD_MIN_DOMINANT_MARGIN,\n                        "min_qualified_ratio": 0.80,\n                    },\n                })\n                rule_id += 1\n\n    dedup = {(tuple(sorted(r["lhs"])), r["rhs"]): r for r in rules}\n    return list(dedup.values())\n\n\ndef build_soft_fd_rules(df, profiles):\n    rules = []\n    rule_id = 1\n\n    cols = list(df.columns)\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in cols})\n\n    lhs_candidates = select_fd_lhs_candidates(profiles)\n    rhs_candidates = [c for c in FD_RHS_CANDIDATE_COLUMNS if c in cols]\n\n    lhs_sets = []\n    for k in range(1, MAX_LHS_SIZE + 1):\n        lhs_sets.extend(list(combinations(lhs_candidates, k)))\n\n    for lhs in lhs_sets:\n        for rhs in rhs_candidates:\n            if rhs in lhs:\n                continue\n\n            profile = calc_fd_quality_profile(norm_df, list(lhs), rhs, min_group_size=SOFT_FD_MIN_GROUP_SIZE)\n            confidence = profile["confidence"]\n            support = profile["used_support"]\n            if support < SOFT_FD_MIN_SUPPORT_ROWS:\n                continue\n\n            if SOFT_FD_CONFIDENCE_THRESHOLD <= confidence < FD_CONFIDENCE_THRESHOLD:\n                rules.append({\n                    "rule_id": f"SOFTFD_EVID_{rule_id}",\n                    "rule_type": "soft_functional_dependency",\n                    "lhs": list(lhs),\n                    "rhs": rhs,\n                    "target_column": rhs,\n                    "description": f"soft FD evidence only: {\', \'.join(lhs)} -> {rhs}",\n                    "confidence": confidence,\n                    "support": support,\n                    "usage_role": SOFT_FD_USAGE_ROLE,\n                    "priority": "low",\n                    "candidate_trigger": "disabled_evidence_only",\n                    "allow_candidate_generation": False,\n                    "fd_quality_profile": profile,\n                    "note": "soft FD is retained only as evidence; shrink_search_space should not add candidates solely from this rule",\n                })\n                rule_id += 1\n\n    return rules\n\n\n# ============================================================\n# 7. Soccer context / consistency rules\n# ============================================================\n\ndef build_team_context_rules(df):\n    """Build soccer-specific context dominant rules.\n\n    与 Adult 的 relationship_context_dominant 类似，但这里不使用测试集后验归因。\n    只从 dirty table 中挖掘 team/season/stadium/city 等上下文下的多数值分布，\n    用作候选生成或证据。弱上下文规则后续应通过 LLM 标注 reliability gate 校准。\n    """\n    rules = []\n    rule_id = 1\n\n    norm_df = pd.DataFrame({c: normalize_series(df[c]) for c in df.columns})\n\n    for rhs in TEAM_CONTEXT_TARGETS:\n        if rhs not in norm_df.columns:\n            continue\n\n        for lhs in TEAM_SEASON_CONTEXT_LHS_SPECS:\n            if rhs in lhs:\n                continue\n            if any(c not in norm_df.columns for c in lhs + [rhs]):\n                continue\n\n            sub = norm_df[lhs + [rhs]].dropna()\n            if len(sub) < TEAM_CONTEXT_MIN_GROUP_SIZE:\n                continue\n\n            grouped = sub.groupby(lhs, dropna=True)[rhs]\n            majority_map = {}\n            total_support = 0\n\n            for key, grp in grouped:\n                if len(grp) < TEAM_CONTEXT_MIN_GROUP_SIZE:\n                    continue\n\n                cnt = Counter(grp.tolist())\n                most = cnt.most_common(2)\n                maj_val, maj_cnt = most[0]\n                second_cnt = most[1][1] if len(most) > 1 else 0\n                ratio = maj_cnt / len(grp)\n                margin = maj_cnt - second_cnt\n\n                if ratio >= TEAM_CONTEXT_MIN_RATIO and margin >= TEAM_CONTEXT_MIN_DOMINANT_MARGIN:\n                    if not isinstance(key, tuple):\n                        key = (key,)\n                    majority_map["||".join(map(str, key))] = {\n                        "dominant_value": maj_val,\n                        "group_size": len(grp),\n                        "ratio": round(ratio, 6),\n                        "dominant_margin": int(margin),\n                    }\n                    total_support += len(grp)\n\n            if majority_map:\n                rules.append({\n                    "rule_id": f"CAND_TEAMCTX_{rule_id}",\n                    "rule_type": "team_context_dominant",\n                    "lhs": lhs,\n                    "rhs": rhs,\n                    "target_column": rhs,\n                    "description": f"soccer context dominant: {\', \'.join(lhs)} -> {rhs}",\n                    "mapping_size": len(majority_map),\n                    "majority_map": majority_map,\n                    "confidence": 0.84,\n                    "support": total_support,\n                    "usage_role": TEAM_CONTEXT_USAGE_ROLE,\n                    "priority": "low",\n                    "candidate_trigger": "disabled_evidence_only",\n                    "allow_candidate_generation": False,\n                    "min_group_size": TEAM_CONTEXT_MIN_GROUP_SIZE,\n                    "min_ratio": TEAM_CONTEXT_MIN_RATIO,\n                    "min_dominant_margin": TEAM_CONTEXT_MIN_DOMINANT_MARGIN,\n                    "note": "team context is retained only as evidence; shrink_search_space should not add candidates solely from this rule",\n                })\n                rule_id += 1\n\n    return rules\n\n\ndef build_soccer_consistency_rules(df, profiles):\n    rules = []\n    rule_id = 1\n\n    if ENABLE_BIRTHYEAR_SEASON_AGE_RULE and {"birthyear", "season"}.issubset(df.columns):\n        rules.append({\n            "rule_id": f"CAND_SOCCERCONS_{rule_id}",\n            "rule_type": "birthyear_season_age_consistency",\n            "columns": ["birthyear", "season"],\n            "target_column": "birthyear",\n            "description": (\n                "A player\'s age at the given season should usually be within a plausible professional football range; "\n                "if season-birthyear is outside the configured range, birthyear is suspicious."\n            ),\n            "min_age": PLAYER_MIN_AGE_AT_SEASON,\n            "max_age": PLAYER_MAX_AGE_AT_SEASON,\n            "birthyear_lower_bound": BIRTHYEAR_MIN,\n            "birthyear_upper_bound": BIRTHYEAR_MAX,\n            "season_lower_bound": SEASON_MIN,\n            "season_upper_bound": SEASON_MAX,\n            "confidence": 0.90,\n            "support": len(df),\n            "usage_role": "strong_rule",\n            "priority": "high",\n        })\n        rule_id += 1\n\n    if {"team", "manager", "season"}.issubset(df.columns):\n        rules.append({\n            "rule_id": f"CAND_SOCCERCONS_{rule_id}",\n            "rule_type": "team_season_manager_consistency_hint",\n            "columns": ["team", "season", "manager"],\n            "target_column": "manager",\n            "description": (\n                "Within a team-season group, manager is expected to be relatively stable; "\n                "the actual majority mapping is provided by team_context_dominant rules."\n            ),\n            "confidence": 0.82,\n            "support": len(df),\n            "usage_role": "evidence_only",\n            "priority": "low",\n            "candidate_trigger": "disabled_evidence_only",\n            "allow_candidate_generation": False,\n        })\n        rule_id += 1\n\n    if {"city", "stadium"}.issubset(df.columns):\n        rules.append({\n            "rule_id": f"CAND_SOCCERCONS_{rule_id}",\n            "rule_type": "city_stadium_consistency_hint",\n            "columns": ["city", "stadium"],\n            "target_column": "stadium",\n            "description": (\n                "A stadium and city pair should be contextually consistent; "\n                "mined city/stadium majority mappings should be used as weak evidence."\n            ),\n            "confidence": 0.80,\n            "support": len(df),\n            "usage_role": "evidence_only",\n            "priority": "low",\n            "candidate_trigger": "disabled_evidence_only",\n            "allow_candidate_generation": False,\n        })\n        rule_id += 1\n\n    return rules\n\n\ndef build_candidate_generation_rules(df, profiles):\n    rules = []\n    rule_id = 1\n\n    # Soccer: 不启用 rare/global dominant 作为候选生成规则，避免长尾球员、球队、城市被误报。\n    # high risk missing: 对关键字段缺失进行候选生成。\n    for col in HIGH_RISK_MISSING_COLUMNS:\n        if col not in profiles:\n            continue\n        prof = profiles[col]\n        rules.append({\n            "rule_id": f"CAND_HRMISS_{rule_id}",\n            "rule_type": "high_risk_missing",\n            "column": col,\n            "target_column": col,\n            "description": f"{col} missing values are suspicious in soccer candidate generation",\n            "confidence": 0.82,\n            "support": prof["non_null_count"],\n            "usage_role": "candidate_generation_rule",\n            "priority": "medium",\n            "target_scope": "schema_missing_guard",\n        })\n        rule_id += 1\n\n    rules.extend(build_team_context_rules(df))\n    rules.extend(build_soccer_consistency_rules(df, profiles))\n\n    return rules\n\n\n# ============================================================\n# 8. priority\n# ============================================================\n\ndef assign_rule_priority(rule):\n    rtype = rule.get("rule_type", "")\n\n    if rtype in {\n        "position_domain",\n        "birthyear_numeric_range",\n        "season_numeric_range",\n        "birthyear_season_age_consistency",\n    }:\n        return "high"\n\n    if rtype in {\n        "name_pattern",\n        "surname_pattern",\n        "manager_name_pattern",\n        "team_name_pattern",\n        "birthplace_location_pattern",\n        "city_location_pattern",\n        "stadium_name_pattern",\n        "pattern",\n        "high_risk_missing",\n    }:\n        return "medium"\n\n    if rtype in {\n        "team_context_dominant",\n        "team_season_manager_consistency_hint",\n        "city_stadium_consistency_hint",\n        "functional_dependency",\n        "soft_functional_dependency",\n    }:\n        return "low"\n\n    if rule.get("usage_role", "candidate_generation_rule") == "candidate_generation_rule":\n        if rule.get("confidence", 0.0) >= 0.90 and rule.get("support", 0) >= 20:\n            return "medium"\n        return "low"\n\n    return "medium"\n\n\ndef enrich_rules_with_priority(rule_groups):\n    new_groups = {}\n    for group_name, rules in rule_groups.items():\n        enriched = []\n        for r in rules:\n            r2 = dict(r)\n            r2["priority"] = assign_rule_priority(r2)\n            enriched.append(r2)\n        new_groups[group_name] = enriched\n    return new_groups\n\n\n# ============================================================\n# 9. 主流程\n# ============================================================\n\ndef build_rule_pool(input_csv, output_json):\n    df = pd.read_csv(input_csv, dtype=str)\n    df = maybe_drop_unnamed_columns(df)\n\n    expected_cols = set(SOCCER_COLUMNS)\n    actual_cols = set(df.columns)\n    missing_cols = sorted(list(expected_cols - actual_cols))\n    extra_cols = sorted(list(actual_cols - expected_cols))\n    if missing_cols:\n        print(f"[WARN] Missing expected soccer columns: {missing_cols}")\n    if extra_cols:\n        print(f"[WARN] Extra columns in input: {extra_cols}")\n\n    for col in df.columns:\n        df[col] = normalize_series(df[col])\n\n    profiles = analyze_columns(df)\n    schema_rules = build_schema_rules(df, profiles)\n    fd_rules = build_fd_rules(df, profiles)\n    soft_fd_rules = build_soft_fd_rules(df, profiles)\n    candidate_rules = build_candidate_generation_rules(df, profiles)\n\n    rule_groups = {\n        "schema_rules": schema_rules,\n        "fd_rules": fd_rules,\n        "soft_fd_rules": soft_fd_rules,\n        "candidate_rules": candidate_rules,\n    }\n    rule_groups = enrich_rules_with_priority(rule_groups)\n\n    rule_pool = {\n        "metadata": {\n            "source_file": input_csv,\n            "row_count": int(len(df)),\n            "column_count": int(len(df.columns)),\n            "design_goal": "high_recall_candidate_generation_for_soccer",\n            "dataset": "soccer",\n            "expected_columns": SOCCER_COLUMNS,\n            "target_candidate_columns": sorted(list(TARGET_CANDIDATE_COLUMNS)),\n            "primary_target_columns": sorted(list(PRIMARY_TARGET_COLUMNS)),\n            "context_only_columns": sorted(list(CONTEXT_ONLY_COLUMNS)),\n            "notes": [\n                "candidate inclusion is determined only by violating rules in this pool",\n                "soccer rule pool uses schema/domain/range/pattern rules plus mined FD/soft-FD/context evidence",\n                "rare value, rare pattern, and global dominant rules are disabled to avoid excessive false positives on long-tail soccer entities",\n                "birthyear-season age consistency captures implausible player ages at a season",\n                "name, surname, and birthplace are now primary candidate columns because the previous run missed many true errors in these fields",\n                "not-null, numeric range, domain, and explicit format rules are intended to be direct candidate-generation rules",\n                "team/stadium/city/manager context dominant rules are evidence-only by default to avoid large false-positive expansion",\n                "soft FD rules are evidence-only and should not be used by shrink_search_space to add candidates directly",\n                "strong FD rules are mined only under strict confidence/support/group-purity conditions",\n            ],\n        },\n        "column_profiles": profiles,\n        "rules": rule_groups,\n    }\n\n    with open(output_json, "w", encoding="utf-8") as f:\n        json.dump(rule_pool, f, ensure_ascii=False, indent=2)\n\n    print(f"[OK] Rule pool saved to: {output_json}")\n    print(f"Schema rules: {len(schema_rules)}")\n    print(f"FD rules: {len(fd_rules)}")\n    print(f"Soft FD rules: {len(soft_fd_rules)}")\n    print(f"Candidate generation rules: {len(candidate_rules)}")\n\n\nif __name__ == "__main__":\n    build_rule_pool(INPUT_CSV, OUTPUT_JSON)\n',
}



def _write_temp_script(dataset: str, tmp_dir: Path) -> Path:
    """把指定数据集的原始 build_rule_pool 代码写成临时脚本。"""
    code = RAW_SCRIPTS[dataset]
    path = tmp_dir / f"_build_rule_pool_{dataset}.py"
    path.write_text(code, encoding="utf-8")
    return path


def _run_one(dataset: str, python_bin: str, cwd: Path, keep_temp: bool = False) -> int:
    if dataset not in RAW_SCRIPTS:
        raise ValueError(f"Unknown dataset: {dataset}. Available: {', '.join(DATASET_ORDER)}")

    tmp_parent = cwd if keep_temp else None
    with tempfile.TemporaryDirectory(prefix=f"unified_rule_pool_{dataset}_", dir=str(tmp_parent) if tmp_parent else None) as td:
        tmp_dir = Path(td)
        script_path = _write_temp_script(dataset, tmp_dir)
        print(f"\n===== build_rule_pool: {dataset} =====")
        print(f"[INFO] cwd      : {cwd}")
        print(f"[INFO] sha256   : {SCRIPT_SHA256[dataset]}")
        print(f"[INFO] temp_py  : {script_path}")
        print(f"[INFO] command  : {python_bin} {script_path}")

        proc = subprocess.run([python_bin, str(script_path)], cwd=str(cwd))
        rc = int(proc.returncode)
        print(f"[INFO] dataset={dataset}, exit_code={rc}")
        return rc


def run_datasets(datasets: List[str], python_bin: str, cwd: Path, keep_temp: bool = False) -> int:
    final_rc = 0
    for dataset in datasets:
        rc = _run_one(dataset=dataset, python_bin=python_bin, cwd=cwd, keep_temp=keep_temp)
        if rc != 0:
            final_rc = rc
            break
    return final_rc


def extract_originals(output_dir: Path):
    """把嵌入的六份原始脚本导出，方便你人工 diff 或备份。"""
    output_dir.mkdir(parents=True, exist_ok=True)
    for dataset in DATASET_ORDER:
        out = output_dir / f"build_rule_pool_{dataset}_original.py"
        out.write_text(RAW_SCRIPTS[dataset], encoding="utf-8")
        print(f"[OK] extracted {dataset}: {out}")


def print_list():
    print("Available datasets:")
    for ds in DATASET_ORDER:
        print(f"  - {ds:8s} sha256={SCRIPT_SHA256[ds]}")


def parse_args():
    parser = argparse.ArgumentParser(description="Unified build_rule_pool dispatcher for six datasets.")
    parser.add_argument(
        "--dataset",
        type=str,
        default=None,
        choices=DATASET_ORDER + ["all"],
        help="要运行的数据集；all 表示按 hospital, flights, beers, rayyan, adult, soccer 顺序全部运行。",
    )
    parser.add_argument(
        "--python-bin",
        type=str,
        default=sys.executable,
        help="Python 解释器路径，默认使用当前环境。",
    )
    parser.add_argument(
        "--cwd",
        type=str,
        default=".",
        help="运行原始脚本时使用的工作目录。默认当前目录；OUTPUT_JSON 会写到这个目录。",
    )
    parser.add_argument(
        "--list",
        action="store_true",
        help="列出可用数据集和嵌入脚本 SHA256。",
    )
    parser.add_argument(
        "--extract-originals",
        type=str,
        default=None,
        help="把嵌入的原始脚本导出到指定目录。",
    )
    parser.add_argument(
        "--keep-temp",
        action="store_true",
        help="保留临时脚本目录，方便调试。默认不保留。",
    )
    return parser.parse_args()


def main():
    args = parse_args()

    if args.list:
        print_list()
        return

    if args.extract_originals:
        extract_originals(Path(args.extract_originals).expanduser().resolve())
        return

    if not args.dataset:
        print("[ERROR] 请指定 --dataset，或者使用 --list 查看可用数据集。", file=sys.stderr)
        sys.exit(2)

    cwd = Path(args.cwd).expanduser().resolve()
    if not cwd.exists():
        print(f"[ERROR] cwd does not exist: {cwd}", file=sys.stderr)
        sys.exit(2)

    datasets = DATASET_ORDER if args.dataset == "all" else [args.dataset]
    rc = run_datasets(datasets=datasets, python_bin=args.python_bin, cwd=cwd, keep_temp=args.keep_temp)
    sys.exit(rc)


if __name__ == "__main__":
    main()
